<template>
  <div class="avatar-tool">
    <el-card>
      <div slot="header">
        <span>头像生成器</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="100px">
            <el-form-item label="生成方式">
              <el-radio-group v-model="avatar.type">
                <el-radio label="initials">首字母</el-radio>
                <el-radio label="identicon">Identicon</el-radio>
                <el-radio label="boring">Boring Avatar</el-radio>
                <el-radio label="dicebear">DiceBear</el-radio>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="文字" v-if="avatar.type === 'initials'">
              <el-input v-model="avatar.text" placeholder="输入名字" style="width: 200px" />
            </el-form-item>

            <el-form-item label="种子" v-if="avatar.type !== 'initials'">
              <el-input v-model="avatar.seed" placeholder="随机种子" style="width: 200px" />
              <el-button type="text" @click="randomSeed" style="margin-left: 10px">随机</el-button>
            </el-form-item>

            <el-form-item label="尺寸">
              <el-slider v-model="avatar.size" :min="32" :max="512" show-input />
            </el-form-item>

            <el-form-item label="背景色" v-if="avatar.type === 'initials'">
              <el-color-picker v-model="avatar.bgColor" />
              <el-button type="text" @click="randomColor" style="margin-left: 10px">随机</el-button>
            </el-form-item>

            <el-form-item label="文字颜色" v-if="avatar.type === 'initials'">
              <el-color-picker v-model="avatar.textColor" />
            </el-form-item>

            <el-form-item label="字体大小" v-if="avatar.type === 'initials'">
              <el-slider v-model="avatar.fontSize" :min="10" :max="200" />
            </el-form-item>

            <el-form-item label="圆角" v-if="avatar.type === 'initials'">
              <el-slider v-model="avatar.borderRadius" :min="0" :max="50" />
              <span>{{ avatar.borderRadius }}%</span>
            </el-form-item>

            <el-form-item label="风格" v-if="avatar.type === 'dicebear'">
              <el-select v-model="avatar.style" style="width: 200px">
                <el-option label="Adventurer" value="adventurer" />
                <el-option label="Adventurer Neutral" value="adventurer-neutral" />
                <el-option label="Avataaars" value="avataaars" />
                <el-option label="Big Ears" value="big-ears" />
                <el-option label="Big Smile" value="big-smile" />
                <el-option label="Bottts" value="bottts" />
                <el-option label="Croodles" value="croodles" />
                <el-option label="Fun Emoji" value="fun-emoji" />
                <el-option label="Lorelei" value="lorelei" />
                <el-option label="Notionists" value="notionists" />
                <el-option label="Open Peeps" value="open-peeps" />
                <el-option label="Personas" value="personas" />
                <el-option label="Rings" value="rings" />
                <el-option label="Shapes" value="shapes" />
                <el-option label="Thumbs" value="thumbs" />
              </el-select>
            </el-form-item>
          </el-form>

          <el-divider>批量生成</el-divider>
          <el-form label-width="100px">
            <el-form-item label="数量">
              <el-input-number v-model="avatar.batchCount" :min="1" :max="20" />
            </el-form-item>
            <el-form-item>
              <el-button type="primary" @click="generateBatch">批量生成</el-button>
            </el-form-item>
          </el-form>
        </el-col>

        <el-col :span="12">
          <el-divider>预览</el-divider>
          <div class="preview-container">
            <div class="avatar-preview" :style="previewStyle" v-if="avatar.type === 'initials'">
              {{ initials }}
            </div>
            <img v-else :src="externalAvatarUrl" :style="{ width: avatar.size + 'px', height: avatar.size + 'px' }" />
          </div>

          <el-divider>批量预览</el-divider>
          <div class="batch-preview">
            <div v-for="(item, index) in batchAvatars" :key="index" class="batch-item">
              <div class="batch-avatar" :style="getBatchStyle(item)" v-if="avatar.type === 'initials'">
                {{ item.initials }}
              </div>
              <img v-else :src="item.url" style="width: 60px; height: 60px; border-radius: 8px" />
            </div>
          </div>

          <el-divider>操作</el-divider>
          <div class="actions">
            <el-button type="primary" @click="downloadAvatar">下载头像</el-button>
            <el-button @click="copyAvatarUrl" v-if="avatar.type !== 'initials'">复制URL</el-button>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'AvatarTool',
  data() {
    return {
      avatar: {
        type: 'initials',
        text: 'John Doe',
        seed: 'random-seed',
        size: 200,
        bgColor: '#409EFF',
        textColor: '#ffffff',
        fontSize: 80,
        borderRadius: 50,
        style: 'avataaars',
        batchCount: 8
      },
      batchAvatars: []
    }
  },
  computed: {
    initials() {
      const words = this.avatar.text.trim().split(/\s+/)
      if (words.length >= 2) {
        return (words[0][0] + words[1][0]).toUpperCase()
      }
      return this.avatar.text.slice(0, 2).toUpperCase()
    },
    previewStyle() {
      return {
        width: this.avatar.size + 'px',
        height: this.avatar.size + 'px',
        backgroundColor: this.avatar.bgColor,
        color: this.avatar.textColor,
        fontSize: this.avatar.fontSize + 'px',
        borderRadius: this.avatar.borderRadius + '%'
      }
    },
    externalAvatarUrl() {
      const size = this.avatar.size
      const seed = encodeURIComponent(this.avatar.seed)
      switch (this.avatar.type) {
        case 'identicon':
          return `https://identicon-api.herokuapp.com/${seed}/${size}.png?format=png`
        case 'boring':
          return `https://source.boringavatars.com/beam/${size}/${seed}?colors=264653,2a9d8f,e9c46a,f4a261,e76f51`
        case 'dicebear':
          return `https://api.dicebear.com/7.x/${this.avatar.style}/svg?seed=${seed}&size=${size}`
        default:
          return ''
      }
    }
  },
  methods: {
    randomSeed() {
      this.avatar.seed = Math.random().toString(36).substring(2, 15)
    },
    randomColor() {
      const colors = ['#409EFF', '#67C23A', '#E6A23C', '#F56C6C', '#909399', '#00d1b2', '#ff69b4', '#8b4513']
      this.avatar.bgColor = colors[Math.floor(Math.random() * colors.length)]
    },
    generateBatch() {
      this.batchAvatars = []
      for (let i = 0; i < this.avatar.batchCount; i++) {
        if (this.avatar.type === 'initials') {
          const names = ['John Doe', 'Jane Smith', 'Bob Wilson', 'Alice Brown', 'Charlie Davis', 'Eva Martinez', 'Frank Lee', 'Grace Kim']
          const name = names[Math.floor(Math.random() * names.length)]
          const words = name.trim().split(/\s+/)
          const initials = words.length >= 2 ? (words[0][0] + words[1][0]).toUpperCase() : name.slice(0, 2).toUpperCase()
          const colors = ['#409EFF', '#67C23A', '#E6A23C', '#F56C6C', '#909399', '#00d1b2', '#ff69b4', '#8b4513']
          this.batchAvatars.push({
            initials,
            bgColor: colors[Math.floor(Math.random() * colors.length)]
          })
        } else {
          const seed = Math.random().toString(36).substring(2, 15)
          let url = ''
          switch (this.avatar.type) {
            case 'identicon':
              url = `https://identicon-api.herokuapp.com/${seed}/60.png?format=png`
              break
            case 'boring':
              url = `https://source.boringavatars.com/beam/60/${seed}?colors=264653,2a9d8f,e9c46a,f4a261,e76f51`
              break
            case 'dicebear':
              url = `https://api.dicebear.com/7.x/${this.avatar.style}/svg?seed=${seed}&size=60`
              break
          }
          this.batchAvatars.push({ url })
        }
      }
    },
    getBatchStyle(item) {
      return {
        width: '60px',
        height: '60px',
        backgroundColor: item.bgColor,
        color: '#ffffff',
        fontSize: '24px',
        borderRadius: this.avatar.borderRadius + '%'
      }
    },
    downloadAvatar() {
      if (this.avatar.type === 'initials') {
        const canvas = document.createElement('canvas')
        canvas.width = this.avatar.size
        canvas.height = this.avatar.size
        const ctx = canvas.getContext('2d')
        
        ctx.fillStyle = this.avatar.bgColor
        if (this.avatar.borderRadius === 50) {
          ctx.beginPath()
          ctx.arc(this.avatar.size / 2, this.avatar.size / 2, this.avatar.size / 2, 0, Math.PI * 2)
          ctx.fill()
        } else {
          const radius = this.avatar.size * this.avatar.borderRadius / 100
          ctx.beginPath()
          ctx.roundRect(0, 0, this.avatar.size, this.avatar.size, radius)
          ctx.fill()
        }
        
        ctx.fillStyle = this.avatar.textColor
        ctx.font = `bold ${this.avatar.fontSize}px Arial`
        ctx.textAlign = 'center'
        ctx.textBaseline = 'middle'
        ctx.fillText(this.initials, this.avatar.size / 2, this.avatar.size / 2)
        
        const link = document.createElement('a')
        link.download = 'avatar.png'
        link.href = canvas.toDataURL('image/png')
        link.click()
      } else {
        const link = document.createElement('a')
        link.download = 'avatar.png'
        link.href = this.externalAvatarUrl
        link.click()
      }
      this.$message.success('下载成功')
    },
    copyAvatarUrl() {
      navigator.clipboard.writeText(this.externalAvatarUrl).then(() => {
        this.$message.success('URL已复制')
      })
    }
  },
  mounted() {
    this.generateBatch()
  }
}
</script>

<style scoped>
.avatar-tool {
  padding: 20px;
}

.preview-container {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 250px;
  background: #f5f7fa;
  border-radius: 8px;
  padding: 20px;
}

.avatar-preview {
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
}

.batch-preview {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.batch-item {
  cursor: pointer;
}

.batch-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
}

.actions {
  display: flex;
  gap: 10px;
  justify-content: center;
}
</style>
