<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>WebSocket 测试工具</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearMessages">清空消息</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <div class="connection-panel">
            <el-input
              v-model="wsUrl"
              placeholder="ws://localhost:8080/ws 或 wss://..."
              class="url-input"
            >
              <template slot="prepend">WebSocket URL</template>
            </el-input>
            <el-button
              :type="connected ? 'danger' : 'primary'"
              @click="toggleConnection"
            >
              {{ connected ? '断开连接' : '连接' }}
            </el-button>
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="24">
          <div class="status-bar">
            <span class="status-label">状态:</span>
            <el-tag :type="connected ? 'success' : 'info'" size="small">
              {{ connected ? '已连接' : '未连接' }}
            </el-tag>
            <span v-if="connected" class="connection-info">
              | 连接时间: {{ connectTime }}
            </span>
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="12">
          <div class="message-panel">
            <div class="panel-header">
              <span>发送消息</span>
              <el-select v-model="messageType" size="small" style="width: 100px">
                <el-option label="文本" value="text" />
                <el-option label="JSON" value="json" />
              </el-select>
            </div>
            <el-input
              v-model="messageToSend"
              type="textarea"
              :rows="6"
              placeholder="输入要发送的消息..."
            />
            <div class="send-actions">
              <el-button type="primary" :disabled="!connected" @click="sendMessage">
                发送
              </el-button>
              <el-button @click="formatJson" :disabled="messageType !== 'json'">
                格式化JSON
              </el-button>
            </div>
          </div>
        </el-col>

        <el-col :span="12">
          <div class="message-panel">
            <div class="panel-header">
              <span>消息记录</span>
              <el-button size="mini" @click="exportMessages">导出</el-button>
            </div>
            <div class="messages-container" ref="messagesContainer">
              <div
                v-for="(msg, index) in messages"
                :key="index"
                :class="['message-item', msg.type]"
              >
                <div class="message-header">
                  <span class="message-time">{{ msg.time }}</span>
                  <el-tag size="mini" :type="msg.type === 'sent' ? 'warning' : 'success'">
                    {{ msg.type === 'sent' ? '发送' : '接收' }}
                  </el-tag>
                </div>
                <div class="message-content">
                  <pre v-if="isJson(msg.content)">{{ formatJsonContent(msg.content) }}</pre>
                  <span v-else>{{ msg.content }}</span>
                </div>
              </div>
              <div v-if="messages.length === 0" class="no-messages">
                暂无消息
              </div>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="24">
          <div class="quick-actions">
            <span class="label">快速发送:</span>
            <el-button size="small" @click="sendPing">Ping</el-button>
            <el-button size="small" @click="sendEcho">Echo Test</el-button>
            <el-button size="small" @click="sendJsonExample">JSON 示例</el-button>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'WebSocketTool',
  data() {
    return {
      wsUrl: 'ws://localhost:8080/ws',
      connected: false,
      connectTime: '',
      ws: null,
      messageToSend: '',
      messageType: 'text',
      messages: []
    }
  },
  methods: {
    toggleConnection() {
      if (this.connected) {
        this.disconnect()
      } else {
        this.connect()
      }
    },
    connect() {
      try {
        this.ws = new WebSocket(this.wsUrl)
        
        this.ws.onopen = () => {
          this.connected = true
          this.connectTime = new Date().toLocaleTimeString()
          this.addMessage('系统', 'WebSocket 连接成功', 'received')
          this.$message.success('连接成功')
        }
        
        this.ws.onmessage = (event) => {
          this.addMessage('服务器', event.data, 'received')
        }
        
        this.ws.onerror = (error) => {
          this.addMessage('系统', '连接错误: ' + (error.message || '未知错误'), 'error')
          this.$message.error('连接错误')
        }
        
        this.ws.onclose = () => {
          this.connected = false
          this.addMessage('系统', 'WebSocket 连接已关闭', 'received')
          this.ws = null
        }
      } catch (e) {
        this.$message.error('连接失败: ' + e.message)
      }
    },
    disconnect() {
      if (this.ws) {
        this.ws.close()
        this.ws = null
      }
      this.connected = false
    },
    sendMessage() {
      if (!this.connected || !this.ws) {
        this.$message.warning('请先连接 WebSocket')
        return
      }
      
      try {
        this.ws.send(this.messageToSend)
        this.addMessage('客户端', this.messageToSend, 'sent')
      } catch (e) {
        this.$message.error('发送失败: ' + e.message)
      }
    },
    addMessage(from, content, type) {
      this.messages.push({
        from,
        content,
        type,
        time: new Date().toLocaleTimeString()
      })
      this.$nextTick(() => {
        const container = this.$refs.messagesContainer
        if (container) {
          container.scrollTop = container.scrollHeight
        }
      })
    },
    clearMessages() {
      this.messages = []
    },
    formatJson() {
      try {
        const obj = JSON.parse(this.messageToSend)
        this.messageToSend = JSON.stringify(obj, null, 2)
      } catch (e) {
        this.$message.error('JSON 格式错误')
      }
    },
    isJson(str) {
      try {
        JSON.parse(str)
        return true
      } catch (e) {
        return false
      }
    },
    formatJsonContent(str) {
      try {
        return JSON.stringify(JSON.parse(str), null, 2)
      } catch (e) {
        return str
      }
    },
    sendPing() {
      this.messageToSend = JSON.stringify({ type: 'ping', timestamp: Date.now() })
      this.messageType = 'json'
    },
    sendEcho() {
      this.messageToSend = JSON.stringify({ type: 'echo', message: 'Hello WebSocket!', timestamp: Date.now() })
      this.messageType = 'json'
    },
    sendJsonExample() {
      this.messageToSend = JSON.stringify({
        action: 'subscribe',
        channel: 'updates',
        data: {
          userId: '12345',
          timestamp: Date.now()
        }
      }, null, 2)
      this.messageType = 'json'
    },
    exportMessages() {
      const content = this.messages.map(m => `[${m.time}] ${m.type === 'sent' ? '发送' : '接收'}: ${m.content}`).join('\n')
      const blob = new Blob([content], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'websocket_messages_' + new Date().toISOString().slice(0, 10) + '.txt'
      a.click()
      URL.revokeObjectURL(url)
    }
  },
  beforeDestroy() {
    if (this.ws) {
      this.ws.close()
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  padding: 20px;

  .tool-card {
    ::v-deep .el-card__header {
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
  }

  .connection-panel {
    display: flex;
    gap: 10px;

    .url-input {
      flex: 1;
    }
  }

  .status-bar {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px;
    background: #f5f7fa;
    border-radius: 4px;

    .status-label {
      font-weight: bold;
    }

    .connection-info {
      color: #909399;
      font-size: 13px;
    }
  }

  .message-panel {
    border: 1px solid #ebeef5;
    border-radius: 4px;
    overflow: hidden;

    .panel-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 10px 15px;
      background: #f5f7fa;
      border-bottom: 1px solid #ebeef5;
      font-weight: bold;
    }

    .send-actions {
      display: flex;
      gap: 10px;
      padding: 10px;
      border-top: 1px solid #ebeef5;
    }

    .messages-container {
      height: 300px;
      overflow-y: auto;
      padding: 10px;
      background: #fafafa;

      .message-item {
        margin-bottom: 10px;
        padding: 10px;
        border-radius: 4px;
        background: #fff;
        border-left: 3px solid #67c23a;

        &.sent {
          border-left-color: #e6a23c;
        }

        &.error {
          border-left-color: #f56c6c;
          background: #fef0f0;
        }

        .message-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 5px;

          .message-time {
            font-size: 12px;
            color: #909399;
          }
        }

        .message-content {
          font-size: 13px;
          word-break: break-all;

          pre {
            margin: 0;
            white-space: pre-wrap;
            font-family: 'Courier New', monospace;
            font-size: 12px;
          }
        }
      }

      .no-messages {
        text-align: center;
        color: #909399;
        padding: 40px;
      }
    }
  }

  .quick-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px;
    background: #f5f7fa;
    border-radius: 4px;

    .label {
      font-weight: bold;
    }
  }
}
</style>
