<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>时间戳转换</span>
        <el-button size="small" @click="setCurrentTime">当前时间</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="11">
          <div class="input-section">
            <div class="section-header">
              <span>时间戳</span>
              <el-tag size="mini" type="primary">输入或输出</el-tag>
            </div>
            <el-input
              v-model="timestamp"
              placeholder="输入时间戳（毫秒或秒）"
              @input="onTimestampChange"
            >
              <el-select v-model="timestampUnit" slot="append" style="width: 80px" @change="onTimestampChange">
                <el-option label="毫秒" value="ms" />
                <el-option label="秒" value="s" />
              </el-select>
            </el-input>
            
            <div class="quick-timestamps">
              <el-button size="mini" @click="setTimestamp(Date.now())">现在</el-button>
              <el-button size="mini" @click="setTimestamp(todayStart)">今天0点</el-button>
              <el-button size="mini" @click="setTimestamp(weekStart)">本周一</el-button>
              <el-button size="mini" @click="setTimestamp(monthStart)">本月1日</el-button>
            </div>
          </div>
        </el-col>
        
        <el-col :span="2" class="actions-col">
          <div class="action-buttons">
            <el-button type="primary" circle @click="timestampToDate" title="时间戳 → 日期">
              <i class="el-icon-right"></i>
            </el-button>
            <span class="action-label">转日期</span>
            <el-button type="success" circle @click="dateToTimestamp" title="日期 → 时间戳">
              <i class="el-icon-back"></i>
            </el-button>
            <span class="action-label">转时间戳</span>
          </div>
        </el-col>
        
        <el-col :span="11">
          <div class="output-section">
            <div class="section-header">
              <span>日期时间</span>
              <el-tag size="mini" type="success">输入或输出</el-tag>
            </div>
            <el-date-picker
              v-model="datetime"
              type="datetime"
              placeholder="选择日期时间"
              value-format="yyyy-MM-dd HH:mm:ss"
              format="yyyy-MM-dd HH:mm:ss"
              style="width: 100%"
              @change="onDatetimeChange"
            />
            <el-input
              v-model="datetimeStr"
              placeholder="或输入日期字符串"
              style="margin-top: 10px"
              @input="onDatetimeStrChange"
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px" v-if="parsedInfo">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">时间详情</div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="本地时间">{{ parsedInfo.local }}</el-descriptions-item>
              <el-descriptions-item label="UTC时间">{{ parsedInfo.utc }}</el-descriptions-item>
              <el-descriptions-item label="ISO格式">{{ parsedInfo.iso }}</el-descriptions-item>
              <el-descriptions-item label="星期">{{ parsedInfo.weekday }}</el-descriptions-item>
              <el-descriptions-item label="毫秒时间戳">{{ parsedInfo.timestampMs }}</el-descriptions-item>
              <el-descriptions-item label="秒时间戳">{{ parsedInfo.timestampS }}</el-descriptions-item>
              <el-descriptions-item label="相对时间">{{ parsedInfo.relative }}</el-descriptions-item>
              <el-descriptions-item label="时区">{{ parsedInfo.timezone }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'TimestampTool',
  data() {
    return {
      timestamp: '',
      timestampUnit: 'ms',
      datetime: '',
      datetimeStr: '',
      parsedInfo: null,
      isConverting: false
    }
  },
  computed: {
    todayStart() {
      const d = new Date()
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    },
    weekStart() {
      const d = new Date()
      const day = d.getDay()
      const diff = d.getDate() - day + (day === 0 ? -6 : 1)
      d.setDate(diff)
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    },
    monthStart() {
      const d = new Date()
      d.setDate(1)
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    }
  },
  mounted() {
    this.setCurrentTime()
  },
  methods: {
    onTimestampChange() {
      if (this.isConverting) return
      this.updateParsedInfo()
    },
    onDatetimeChange() {
      if (this.isConverting) return
      this.datetimeStr = this.datetime
      this.dateToTimestamp()
    },
    onDatetimeStrChange() {
      if (this.isConverting) return
      this.datetime = this.datetimeStr
      this.dateToTimestamp()
    },
    timestampToDate() {
      if (!this.timestamp) {
        this.$message.warning('请输入时间戳')
        return
      }
      
      try {
        let ts = parseInt(this.timestamp)
        if (this.timestampUnit === 's') {
          ts = ts * 1000
        }
        
        const date = new Date(ts)
        if (isNaN(date.getTime())) {
          throw new Error('无效的时间戳')
        }
        
        this.isConverting = true
        this.datetime = this.formatDate(date)
        this.datetimeStr = this.datetime
        this.updateParsedInfo()
        this.isConverting = false
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('转换失败: ' + e.message)
      }
    },
    dateToTimestamp() {
      if (!this.datetimeStr && !this.datetime) {
        this.$message.warning('请输入日期时间')
        return
      }
      
      try {
        const dateStr = this.datetimeStr || this.datetime
        const date = new Date(dateStr.replace(/-/g, '/'))
        
        if (isNaN(date.getTime())) {
          throw new Error('无效的日期格式')
        }
        
        this.isConverting = true
        const ts = date.getTime()
        
        if (this.timestampUnit === 's') {
          this.timestamp = Math.floor(ts / 1000).toString()
        } else {
          this.timestamp = ts.toString()
        }
        
        this.updateParsedInfo()
        this.isConverting = false
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('转换失败: ' + e.message)
      }
    },
    updateParsedInfo() {
      if (!this.timestamp) {
        this.parsedInfo = null
        return
      }
      
      let ts = parseInt(this.timestamp)
      if (this.timestampUnit === 's') {
        ts = ts * 1000
      }
      
      const date = new Date(ts)
      if (isNaN(date.getTime())) {
        this.parsedInfo = null
        return
      }
      
      const now = Date.now()
      const diff = ts - now
      let relative = ''
      
      if (Math.abs(diff) < 1000) {
        relative = '刚刚'
      } else if (diff > 0) {
        const minutes = Math.floor(diff / 60000)
        const hours = Math.floor(diff / 3600000)
        const days = Math.floor(diff / 86400000)
        
        if (days > 0) relative = `${days}天后`
        else if (hours > 0) relative = `${hours}小时后`
        else relative = `${minutes}分钟后`
      } else {
        const minutes = Math.floor(-diff / 60000)
        const hours = Math.floor(-diff / 3600000)
        const days = Math.floor(-diff / 86400000)
        
        if (days > 0) relative = `${days}天前`
        else if (hours > 0) relative = `${hours}小时前`
        else relative = `${minutes}分钟前`
      }
      
      const weekdays = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']
      
      this.parsedInfo = {
        local: this.formatDate(date),
        utc: date.toUTCString(),
        iso: date.toISOString(),
        weekday: weekdays[date.getDay()],
        timestampMs: date.getTime(),
        timestampS: Math.floor(date.getTime() / 1000),
        relative,
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone
      }
    },
    formatDate(date) {
      const pad = n => n.toString().padStart(2, '0')
      return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
    },
    setTimestamp(ts) {
      this.timestamp = ts.toString()
      this.timestampToDate()
    },
    setCurrentTime() {
      this.timestamp = Date.now().toString()
      this.timestampUnit = 'ms'
      this.timestampToDate()
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section, .output-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;
    }
  }

  .quick-timestamps {
    margin-top: 10px;
    display: flex;
    gap: 5px;
    flex-wrap: wrap;
  }

  .actions-col {
    display: flex;
    align-items: center;
    justify-content: center;

    .action-buttons {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;

      .action-label {
        font-size: 12px;
        color: #606266;
        margin-bottom: 10px;
      }
    }
  }
}
</style>
