<template>
  <div class="html-converter-tool">
    <el-card>
      <div slot="header">
        <span>HTML 转换器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-form :model="config" label-width="120px">
        <el-form-item label="转换方向">
          <el-radio-group v-model="config.direction">
            <el-radio-button label="html-to-jsx">HTML → JSX</el-radio-button>
            <el-radio-button label="html-to-vue">HTML → Vue</el-radio-button>
            <el-radio-button label="jsx-to-html">JSX → HTML</el-radio-button>
            <el-radio-button label="vue-to-html">Vue → HTML</el-radio-button>
          </el-radio-group>
        </el-form-item>
      </el-form>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span class="section-title">{{ inputLabel }}</span>
              <div class="section-actions">
                <el-button type="text" size="small" @click="formatInput">格式化</el-button>
                <el-button type="text" size="small" @click="clearInput">清空</el-button>
              </div>
            </div>
            <el-input
              v-model="input"
              type="textarea"
              :rows="20"
              :placeholder="inputPlaceholder"
            />
          </div>
        </el-col>

        <el-col :span="12">
          <div class="output-section">
            <div class="section-header">
              <span class="section-title">{{ outputLabel }}</span>
              <div class="section-actions">
                <el-button type="text" size="small" @click="copyOutput">复制</el-button>
                <el-button type="text" size="small" @click="downloadOutput">下载</el-button>
              </div>
            </div>
            <el-input
              v-model="output"
              type="textarea"
              :rows="20"
              readonly
              :placeholder="outputPlaceholder"
            />
          </div>
        </el-col>
      </el-row>

      <div class="action-buttons">
        <el-button type="primary" @click="convert">转换</el-button>
        <el-button @click="clear">全部清空</el-button>
      </div>

      <el-divider>转换选项</el-divider>

      <el-form :model="options" label-width="150px">
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="使用单引号">
              <el-switch v-model="options.singleQuote" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="缩进空格">
              <el-input-number v-model="options.indentSize" :min="2" :max="8" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="保留注释">
              <el-switch v-model="options.preserveComments" />
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'HtmlConverterTool',
  data() {
    return {
      config: {
        direction: 'html-to-jsx'
      },
      input: '',
      output: '',
      options: {
        singleQuote: false,
        indentSize: 2,
        preserveComments: true
      }
    }
  },
  computed: {
    inputLabel() {
      const labels = {
        'html-to-jsx': 'HTML',
        'html-to-vue': 'HTML',
        'jsx-to-html': 'JSX',
        'vue-to-html': 'Vue 模板'
      }
      return labels[this.config.direction]
    },
    outputLabel() {
      const labels = {
        'html-to-jsx': 'JSX',
        'html-to-vue': 'Vue 模板',
        'jsx-to-html': 'HTML',
        'vue-to-html': 'HTML'
      }
      return labels[this.config.direction]
    },
    inputPlaceholder() {
      const placeholders = {
        'html-to-jsx': '粘贴 HTML 代码...',
        'html-to-vue': '粘贴 HTML 代码...',
        'jsx-to-html': '粘贴 JSX 代码...',
        'vue-to-html': '粘贴 Vue 模板代码...'
      }
      return placeholders[this.config.direction]
    },
    outputPlaceholder() {
      return '转换结果将显示在这里...'
    }
  },
  methods: {
    convert() {
      if (!this.input) {
        this.$message.warning('请输入需要转换的代码')
        return
      }

      try {
        switch (this.config.direction) {
          case 'html-to-jsx':
            this.output = this.htmlToJsx(this.input)
            break
          case 'html-to-vue':
            this.output = this.htmlToVue(this.input)
            break
          case 'jsx-to-html':
            this.output = this.jsxToHtml(this.input)
            break
          case 'vue-to-html':
            this.output = this.vueToHtml(this.input)
            break
        }
      } catch (error) {
        this.$message.error('转换失败: ' + error.message)
      }
    },
    htmlToJsx(html) {
      let jsx = html
      const quote = this.options.singleQuote ? "'" : '"'

      // Convert class to className
      jsx = jsx.replace(/\bclass=/g, 'className=')
      
      // Convert for to htmlFor
      jsx = jsx.replace(/\bfor=/g, 'htmlFor=')
      
      // Convert style string to object
      jsx = jsx.replace(/style="([^"]*)"/g, (match, styles) => {
        const styleObj = this.parseStyleToObject(styles)
        return `style={${styleObj}}`
      })
      
      // Convert kebab-case attributes to camelCase
      jsx = jsx.replace(/\b([a-z]+-[a-z-]+)=/g, (match, attr) => {
        return attr.replace(/-([a-z])/g, (m, letter) => letter.toUpperCase()) + '='
      })
      
      // Convert boolean attributes
      jsx = jsx.replace(/\b(checked|disabled|selected|readonly|multiple|autofocus)=(["']?)\2/g, '$1={true}')
      
      // Close self-closing tags
      const selfClosing = ['img', 'input', 'br', 'hr', 'meta', 'link', 'area', 'base', 'col', 'embed', 'param', 'source', 'track', 'wbr']
      selfClosing.forEach(tag => {
        const regex = new RegExp(`<${tag}([^>]*)>`, 'gi')
        jsx = jsx.replace(regex, `<${tag}$1 />`)
      })
      
      // Convert comments
      if (!this.options.preserveComments) {
        jsx = jsx.replace(/<!--[\s\S]*?-->/g, '')
      } else {
        jsx = jsx.replace(/<!--([\s\S]*?)-->/g, '{/*$1*/}')
      }

      return this.formatCode(jsx)
    },
    htmlToVue(html) {
      let vue = html

      // Convert @click to v-on:click (both are valid in Vue, but let's standardize)
      vue = vue.replace(/\b@click=/g, 'v-on:click=')
      vue = vue.replace(/\b:([a-z-]+)=/g, 'v-bind:$1=')
      
      // Convert style to bind if needed
      vue = vue.replace(/style="([^"]*)"/g, (match, styles) => {
        if (styles.includes('{{')) {
          return `v-bind:style="${this.parseStyleToObject(styles)}"`
        }
        return match
      })

      // Convert class with conditionals
      vue = vue.replace(/class="([^"]*)"/g, (match, classes) => {
        if (classes.includes('{{')) {
          return `v-bind:class="${classes.replace(/{{|}}/g, '')}"`
        }
        return match
      })

      // Handle Vue directives
      vue = vue.replace(/\bv-if=/g, 'v-if=')
      vue = vue.replace(/\bv-for=/g, 'v-for=')
      vue = vue.replace(/\bv-model=/g, 'v-model=')
      vue = vue.replace(/\bv-show=/g, 'v-show=')

      if (!this.options.preserveComments) {
        vue = vue.replace(/<!--[\s\S]*?-->/g, '')
      }

      return this.formatCode(vue)
    },
    jsxToHtml(jsx) {
      let html = jsx

      // Convert className to class
      html = html.replace(/\bclassName=/g, 'class=')
      
      // Convert htmlFor to for
      html = html.replace(/\bhtmlFor=/g, 'for=')
      
      // Convert style object to string
      html = html.replace(/style={\s*{([^}]+)}\s*}/g, (match, styles) => {
        const styleStr = styles.replace(/([a-zA-Z]+):\s*([^,]+)/g, (m, prop, val) => {
          const kebabProp = prop.replace(/[A-Z]/g, m => '-' + m.toLowerCase())
          return `${kebabProp}: ${val.trim()}`
        })
        return `style="${styleStr}"`
      })
      
      // Convert JSX expressions
      html = html.replace(/{([^}]+)}/g, '{{$1}}')
      
      // Remove self-closing slash for HTML5
      html = html.replace(/\s*\/>/g, '>')
      
      // Convert boolean attributes
      html = html.replace(/\b(checked|disabled|selected|readonly|multiple|autofocus)={true}/g, '$1')
      html = html.replace(/\b(checked|disabled|selected|readonly|multiple|autofocus)={false}/g, '')

      if (!this.options.preserveComments) {
        html = html.replace(/{\/\*[\s\S]*?\*\/}/g, '')
      } else {
        html = html.replace(/{\/\*([\s\S]*?)\*\/}/g, '<!--$1-->')
      }

      return this.formatCode(html)
    },
    vueToHtml(vue) {
      let html = vue

      // Convert Vue directives to standard HTML or data attributes
      html = html.replace(/\bv-bind:([a-z-]+)=/g, '$1=')
      html = html.replace(/\b:([a-z-]+)=/g, '$1=')
      html = html.replace(/\bv-on:(\w+)=/g, 'on$1=')
      html = html.replace(/\b@(\w+)=/g, 'on$1=')
      
      // Remove Vue-specific directives
      html = html.replace(/\bv-(if|for|model|show|else|else-if)="[^"]*"/g, '')
      
      // Convert Vue expressions
      html = html.replace(/"{{([^}]+)}}"/g, '"$1"')
      
      // Handle v-bind:class and v-bind:style
      html = html.replace(/\bv-bind:class="[^"]*"/g, '')
      html = html.replace(/\bv-bind:style="[^"]*"/g, '')

      if (!this.options.preserveComments) {
        html = html.replace(/<!--[\s\S]*?-->/g, '')
      }

      // Clean up empty attributes
      html = html.replace(/\s+/g, ' ')
      html = html.replace(/\s*\>\s*/g, '>')
      html = html.replace(/\s*<\s*/g, '<')

      return this.formatCode(html)
    },
    parseStyleToObject(styleStr) {
      const styles = styleStr.split(';').filter(s => s.trim())
      const obj = {}
      styles.forEach(style => {
        const [prop, val] = style.split(':').map(s => s.trim())
        if (prop && val) {
          const camelProp = prop.replace(/-([a-z])/g, (m, letter) => letter.toUpperCase())
          obj[camelProp] = isNaN(val) ? `"${val}"` : val
        }
      })
      return JSON.stringify(obj).replace(/"/g, this.options.singleQuote ? "'" : '"')
    },
    formatCode(code) {
      // Simple formatting
      const indent = ' '.repeat(this.options.indentSize)
      let formatted = ''
      let indentLevel = 0
      
      const tokens = code.split(/(<\/?[^>]+>)/g).filter(Boolean)
      
      tokens.forEach(token => {
        token = token.trim()
        if (!token) return
        
        if (token.startsWith('</')) {
          indentLevel = Math.max(0, indentLevel - 1)
        }
        
        formatted += indent.repeat(indentLevel) + token + '\n'
        
        if (token.startsWith('<') && !token.startsWith('</') && !token.endsWith('/>')) {
          indentLevel++
        }
      })
      
      return formatted.trim()
    },
    formatInput() {
      if (!this.input) return
      this.input = this.formatCode(this.input)
    },
    copyOutput() {
      if (!this.output) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.output).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadOutput() {
      if (!this.output) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const extensions = {
        'html-to-jsx': 'jsx',
        'html-to-vue': 'vue',
        'jsx-to-html': 'html',
        'vue-to-html': 'html'
      }
      const blob = new Blob([this.output], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `converted.${extensions[this.config.direction]}`
      link.click()
      URL.revokeObjectURL(url)
    },
    clearInput() {
      this.input = ''
    },
    clear() {
      this.input = ''
      this.output = ''
    },
    loadExample() {
      this.config.direction = 'html-to-jsx'
      this.input = `<div class="container">
  <h1 class="title">Hello World</h1>
  <p style="color: red; font-size: 16px;">This is a paragraph</p>
  <button class="btn btn-primary" onclick="handleClick()">Click me</button>
  <img src="image.jpg" alt="Example">
</div>`
      this.convert()
    }
  }
}
</script>

<style scoped>
.html-converter-tool {
  padding: 20px;
}

.input-section, .output-section {
  height: 100%;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.section-title {
  font-weight: bold;
  color: #606266;
}

.section-actions {
  display: flex;
  gap: 10px;
}

.action-buttons {
  text-align: center;
  margin: 20px 0;
}
</style>
