<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>JSON 格式化</span>
        <el-button size="small" @click="clear">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <div class="input-section">
            <div class="section-header">
              <span>JSON 内容</span>
              <el-tag size="mini" type="info">输入或粘贴 JSON，点击按钮格式化</el-tag>
            </div>
            <el-input
              v-model="jsonText"
              type="textarea"
              :rows="15"
              placeholder='输入 JSON，如: {"name": "张三", "age": 25}'
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px">
        <el-col :span="24" class="action-row">
          <el-radio-group v-model="indent" size="small">
            <el-radio-button :label="2">2空格</el-radio-button>
            <el-radio-button :label="4">4空格</el-radio-button>
            <el-radio-button :label="1">Tab</el-radio-button>
          </el-radio-group>
          
          <div class="action-buttons">
            <el-button type="primary" @click="format">格式化</el-button>
            <el-button type="warning" @click="compress">压缩</el-button>
            <el-button type="success" @click="sortKeys">排序键名</el-button>
            <el-button type="info" @click="validate">验证</el-button>
            <el-button @click="copy">复制</el-button>
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px" v-if="error">
        <el-col :span="24">
          <el-alert type="error" :closable="false" show-icon>
            <template slot="title">{{ error }}</template>
          </el-alert>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px" v-if="stats">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">JSON 统计</div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="对象数">{{ stats.objects }}</el-descriptions-item>
              <el-descriptions-item label="数组数">{{ stats.arrays }}</el-descriptions-item>
              <el-descriptions-item label="键数量">{{ stats.keys }}</el-descriptions-item>
              <el-descriptions-item label="字符数">{{ stats.chars }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonTool',
  data() {
    return {
      jsonText: '',
      indent: 2,
      error: '',
      stats: null
    }
  },
  methods: {
    format() {
      if (!this.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }
      
      try {
        const obj = JSON.parse(this.jsonText)
        this.jsonText = JSON.stringify(obj, null, this.indent)
        this.error = ''
        this.updateStats(obj)
        this.$message.success('格式化成功')
      } catch (e) {
        this.error = 'JSON 格式错误: ' + e.message
        this.stats = null
      }
    },
    compress() {
      if (!this.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }
      
      try {
        const obj = JSON.parse(this.jsonText)
        this.jsonText = JSON.stringify(obj)
        this.error = ''
        this.updateStats(obj)
        this.$message.success('压缩成功')
      } catch (e) {
        this.error = 'JSON 格式错误: ' + e.message
        this.stats = null
      }
    },
    sortKeys() {
      if (!this.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }
      
      try {
        const obj = JSON.parse(this.jsonText)
        const sorted = this.sortObjectKeys(obj)
        this.jsonText = JSON.stringify(sorted, null, this.indent)
        this.error = ''
        this.updateStats(sorted)
        this.$message.success('排序成功')
      } catch (e) {
        this.error = 'JSON 格式错误: ' + e.message
        this.stats = null
      }
    },
    sortObjectKeys(obj) {
      if (typeof obj !== 'object' || obj === null) {
        return obj
      }
      
      if (Array.isArray(obj)) {
        return obj.map(item => this.sortObjectKeys(item))
      }
      
      const sorted = {}
      Object.keys(obj).sort().forEach(key => {
        sorted[key] = this.sortObjectKeys(obj[key])
      })
      return sorted
    },
    validate() {
      if (!this.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }
      
      try {
        JSON.parse(this.jsonText)
        this.error = ''
        this.$message.success('JSON 格式正确')
      } catch (e) {
        this.error = 'JSON 格式错误: ' + e.message
      }
    },
    updateStats(obj) {
      let objects = 0
      let arrays = 0
      let keys = 0
      
      const count = (o) => {
        if (typeof o !== 'object' || o === null) return
        
        if (Array.isArray(o)) {
          arrays++
          o.forEach(item => count(item))
        } else {
          objects++
          keys += Object.keys(o).length
          Object.values(o).forEach(v => count(v))
        }
      }
      
      count(obj)
      
      this.stats = {
        objects,
        arrays,
        keys,
        chars: this.jsonText.length
      }
    },
    copy() {
      if (!this.jsonText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.jsonText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      this.jsonText = ''
      this.error = ''
      this.stats = null
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;
    }
  }

  .action-row {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .action-buttons {
      display: flex;
      gap: 10px;
    }
  }
}
</style>
