item5`,
        extract: `联系方式：
邮箱：test@example.com, admin@test.org
电话：13800138000, 13900139000
网址：https://www.example.com
IP：192.168.1.1
身份证：110101199001011234`,
        tts: '你好，这是一个文本转语音的示例。',
        stt: ''
      }
      
      const map = {
        dedup: 'dedupInput',
        sort: 'sortInput',
        replace: 'replaceInput',
        split: 'splitInput',
        join: 'joinInput',
        extract: 'extractInput',
        tts: 'ttsInput',
        stt: 'sttOutput'
      }
      
      if (examples[this.activeTab]) {
        this[map[this.activeTab]] = examples[this.activeTab]
      }
    },
    
    clearAll() {
      this.dedupInput = ''
      this.dedupOutput = ''
      this.sortInput = ''
      this.sortOutput = ''
      this.replaceInput = ''
      this.replaceOutput = ''
      this.splitInput = ''
      this.splitParts = []
      this.joinInput = ''
      this.joinOutput = ''
      this.extractInput = ''
      this.ttsInput = ''
      this.sttOutput = ''
    }
  }
}
</script>

