<template>
  <div class="matrix-tool">
    <el-card>
      <div slot="header">
        <span>矩阵计算器</span>
      </div>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="矩阵运算" name="operations">
          <el-row :gutter="20">
            <el-col :span="11">
              <div class="matrix-section">
                <div class="matrix-header">
                  <span>矩阵 A</span>
                  <el-button-group>
                    <el-button size="small" @click="addRow('A')">+行</el-button>
                    <el-button size="small" @click="removeRow('A')">-行</el-button>
                    <el-button size="small" @click="addCol('A')">+列</el-button>
                    <el-button size="small" @click="removeCol('A')">-列</el-button>
                  </el-button-group>
                </div>
                <div class="matrix-grid">
                  <div v-for="(row, i) in matrixA" :key="i" class="matrix-row">
                    <el-input
                      v-for="(cell, j) in row" :key="j"
                      v-model="matrixA[i][j]"
                      size="small"
                      class="matrix-cell"
                    />
                  </div>
                </div>
                <div class="matrix-size">{{ matrixA.length }} × {{ matrixA[0].length }}</div>
              </div>
            </el-col>

            <el-col :span="2">
              <div class="operator-section">
                <el-select v-model="matrixOperator" style="width: 100%">
                  <el-option label="+" value="+" />
                  <el-option label="-" value="-" />
                  <el-option label="×" value="*" />
                </el-select>
              </div>
            </el-col>

            <el-col :span="11">
              <div class="matrix-section">
                <div class="matrix-header">
                  <span>矩阵 B</span>
                  <el-button-group>
                    <el-button size="small" @click="addRow('B')">+行</el-button>
                    <el-button size="small" @click="removeRow('B')">-行</el-button>
                    <el-button size="small" @click="addCol('B')">+列</el-button>
                    <el-button size="small" @click="removeCol('B')">-列</el-button>
                  </el-button-group>
                </div>
                <div class="matrix-grid">
                  <div v-for="(row, i) in matrixB" :key="i" class="matrix-row">
                    <el-input
                      v-for="(cell, j) in row" :key="j"
                      v-model="matrixB[i][j]"
                      size="small"
                      class="matrix-cell"
                    />
                  </div>
                </div>
                <div class="matrix-size">{{ matrixB.length }} × {{ matrixB[0].length }}</div>
              </div>
            </el-col>
          </el-row>

          <div class="action-buttons">
            <el-button type="primary" @click="calculateMatrix">计算</el-button>
            <el-button @click="clearMatrices">清空</el-button>
            <el-button @click="loadExample">加载示例</el-button>
          </div>

          <div v-if="matrixResult.length > 0" class="result-section">
            <div class="result-title">计算结果</div>
            <div class="matrix-grid result-grid">
              <div v-for="(row, i) in matrixResult" :key="i" class="matrix-row">
                <div
                  v-for="(cell, j) in row" :key="j"
                  class="matrix-cell result-cell"
                >{{ cell }}</div>
              </div>
            </div>
          </div>
        </el-tab-pane>

        <el-tab-pane label="矩阵属性" name="properties">
          <el-row :gutter="20">
            <el-col :span="12">
              <div class="matrix-section">
                <div class="matrix-header">
                  <span>输入矩阵</span>
                  <el-button-group>
                    <el-button size="small" @click="addRow('P')">+行</el-button>
                    <el-button size="small" @click="removeRow('P')">-行</el-button>
                  </el-button-group>
                </div>
                <div class="matrix-grid">
                  <div v-for="(row, i) in matrixP" :key="i" class="matrix-row">
                    <el-input
                      v-for="(cell, j) in row" :key="j"
                      v-model="matrixP[i][j]"
                      size="small"
                      class="matrix-cell"
                    />
                  </div>
                </div>
              </div>
            </el-col>

            <el-col :span="12">
              <div class="properties-section">
                <el-button type="primary" @click="calculateProperties">计算属性</el-button>
                
                <div v-if="propertiesResult" class="properties-result">
                  <el-descriptions :column="1" border>
                    <el-descriptions-item label="行列式">{{ propertiesResult.determinant }}</el-descriptions-item>
                    <el-descriptions-item label="秩">{{ propertiesResult.rank }}</el-descriptions-item>
                    <el-descriptions-item label="迹">{{ propertiesResult.trace }}</el-descriptions-item>
                    <el-descriptions-item label="转置">
                      <div class="transpose-matrix">
                        <div v-for="(row, i) in propertiesResult.transpose" :key="i" class="matrix-row">
                          <span v-for="(cell, j) in row" :key="j" class="matrix-cell result-cell">{{ cell }}</span>
                        </div>
                      </div>
                    </el-descriptions-item>
                    <el-descriptions-item label="逆矩阵" v-if="propertiesResult.inverse">
                      <div class="inverse-matrix">
                        <div v-for="(row, i) in propertiesResult.inverse" :key="i" class="matrix-row">
                          <span v-for="(cell, j) in row" :key="j" class="matrix-cell result-cell">{{ formatNumber(cell) }}</span>
                        </div>
                      </div>
                    </el-descriptions-item>
                  </el-descriptions>
                </div>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="方程求解" name="equation">
          <el-row :gutter="20">
            <el-col :span="12">
              <div class="matrix-section">
                <div class="matrix-header">
                  <span>系数矩阵 A</span>
                </div>
                <div class="matrix-grid">
                  <div v-for="(row, i) in matrixEqA" :key="i" class="matrix-row">
                    <el-input
                      v-for="(cell, j) in row" :key="j"
                      v-model="matrixEqA[i][j]"
                      size="small"
                      class="matrix-cell"
                    />
                  </div>
                </div>
              </div>
            </el-col>

            <el-col :span="12">
              <div class="matrix-section">
                <div class="matrix-header">
                  <span>常数向量 B</span>
                </div>
                <div class="matrix-grid">
                  <div v-for="(row, i) in matrixEqB" :key="i" class="matrix-row">
                    <el-input
                      v-model="matrixEqB[i][0]"
                      size="small"
                      class="matrix-cell"
                    />
                  </div>
                </div>
              </div>
            </el-col>
          </el-row>

          <div class="action-buttons">
            <el-button type="primary" @click="solveEquation">求解</el-button>
            <el-button @click="clearEquation">清空</el-button>
          </div>

          <div v-if="equationResult" class="result-section">
            <div class="result-title">方程解</div>
            <div class="equation-result">
              <div v-for="(value, i) in equationResult" :key="i" class="equation-variable">
                x{{ i + 1 }} = {{ formatNumber(value) }}
              </div>
            </div>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'MatrixTool',
  data() {
    return {
      activeTab: 'operations',
      matrixOperator: '+',
      matrixA: [
        ['1', '2'],
        ['3', '4']
      ],
      matrixB: [
        ['5', '6'],
        ['7', '8']
      ],
      matrixResult: [],
      matrixP: [
        ['1', '2', '3'],
        ['4', '5', '6'],
        ['7', '8', '9']
      ],
      propertiesResult: null,
      matrixEqA: [
        ['2', '1', '-1'],
        ['-3', '-1', '2'],
        ['-2', '1', '2']
      ],
      matrixEqB: [
        ['8'],
        ['-11'],
        ['-3']
      ],
      equationResult: null
    }
  },
  methods: {
    addRow(matrix) {
      const target = matrix === 'A' ? this.matrixA : matrix === 'B' ? this.matrixB : this.matrixP
      const cols = target[0].length
      target.push(Array(cols).fill('0'))
    },
    removeRow(matrix) {
      const target = matrix === 'A' ? this.matrixA : matrix === 'B' ? this.matrixB : this.matrixP
      if (target.length > 1) {
        target.pop()
      }
    },
    addCol(matrix) {
      const target = matrix === 'A' ? this.matrixA : matrix === 'B' ? this.matrixB : this.matrixP
      target.forEach(row => row.push('0'))
    },
    removeCol(matrix) {
      const target = matrix === 'A' ? this.matrixA : matrix === 'B' ? this.matrixB : this.matrixP
      if (target[0].length > 1) {
        target.forEach(row => row.pop())
      }
    },
    calculateMatrix() {
      const a = this.matrixA.map(row => row.map(Number))
      const b = this.matrixB.map(row => row.map(Number))
      
      try {
        switch (this.matrixOperator) {
          case '+':
            this.matrixResult = this.addMatrices(a, b)
            break
          case '-':
            this.matrixResult = this.subtractMatrices(a, b)
            break
          case '*':
            this.matrixResult = this.multiplyMatrices(a, b)
            break
        }
      } catch (error) {
        this.$message.error(error.message)
      }
    },
    addMatrices(a, b) {
      if (a.length !== b.length || a[0].length !== b[0].length) {
        throw new Error('矩阵维度不匹配')
      }
      return a.map((row, i) => row.map((val, j) => val + b[i][j]))
    },
    subtractMatrices(a, b) {
      if (a.length !== b.length || a[0].length !== b[0].length) {
        throw new Error('矩阵维度不匹配')
      }
      return a.map((row, i) => row.map((val, j) => val - b[i][j]))
    },
    multiplyMatrices(a, b) {
      if (a[0].length !== b.length) {
        throw new Error('矩阵维度不匹配，A的列数必须等于B的行数')
      }
      
      const result = []
      for (let i = 0; i < a.length; i++) {
        result[i] = []
        for (let j = 0; j < b[0].length; j++) {
          let sum = 0
          for (let k = 0; k < a[0].length; k++) {
            sum += a[i][k] * b[k][j]
          }
          result[i][j] = sum
        }
      }
      return result
    },
    calculateProperties() {
      const m = this.matrixP.map(row => row.map(Number))
      
      this.propertiesResult = {
        determinant: this.calculateDeterminant(m),
        rank: this.calculateRank(m),
        trace: this.calculateTrace(m),
        transpose: this.transposeMatrix(m),
        inverse: this.calculateInverse(m)
      }
    },
    calculateDeterminant(m) {
      if (m.length !== m[0].length) return 'N/A (非方阵)'
      if (m.length === 2) {
        return m[0][0] * m[1][1] - m[0][1] * m[1][0]
      }
      if (m.length === 3) {
        return m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) -
               m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) +
               m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0])
      }
      return '仅支持2x2和3x3矩阵'
    },
    calculateRank(m) {
      // Simplified rank calculation
      return Math.min(m.length, m[0].length)
    },
    calculateTrace(m) {
      if (m.length !== m[0].length) return 'N/A (非方阵)'
      return m.reduce((sum, row, i) => sum + row[i], 0)
    },
    transposeMatrix(m) {
      return m[0].map((_, i) => m.map(row => row[i]))
    },
    calculateInverse(m) {
      if (m.length !== m[0].length) return null
      
      const det = this.calculateDeterminant(m)
      if (det === 0) return null
      
      if (m.length === 2) {
        return [
          [m[1][1] / det, -m[0][1] / det],
          [-m[1][0] / det, m[0][0] / det]
        ]
      }
      
      return null // Simplified - full inverse for larger matrices is complex
    },
    solveEquation() {
      const a = this.matrixEqA.map(row => row.map(Number))
      const b = this.matrixEqB.map(row => Number(row[0]))
      
      try {
        this.equationResult = this.gaussianElimination(a, b)
      } catch (error) {
        this.$message.error('求解失败: ' + error.message)
      }
    },
    gaussianElimination(a, b) {
      const n = a.length
      
      // Forward elimination
      for (let i = 0; i < n; i++) {
        // Find pivot
        let maxRow = i
        for (let k = i + 1; k < n; k++) {
          if (Math.abs(a[k][i]) > Math.abs(a[maxRow][i])) {
            maxRow = k
          }
        }
        
        // Swap rows
        [a[i], a[maxRow]] = [a[maxRow], a[i]]
        [b[i], b[maxRow]] = [b[maxRow], b[i]]
        
        // Eliminate column
        for (let k = i + 1; k < n; k++) {
          const factor = a[k][i] / a[i][i]
          for (let j = i; j < n; j++) {
            a[k][j] -= factor * a[i][j]
          }
          b[k] -= factor * b[i]
        }
      }
      
      // Back substitution
      const x = new Array(n)
      for (let i = n - 1; i >= 0; i--) {
        let sum = 0
        for (let j = i + 1; j < n; j++) {
          sum += a[i][j] * x[j]
        }
        x[i] = (b[i] - sum) / a[i][i]
      }
      
      return x
    },
    formatNumber(num) {
      if (typeof num === 'number') {
        return Number(num.toFixed(4))
      }
      return num
    },
    clearMatrices() {
      this.matrixA = [['0', '0'], ['0', '0']]
      this.matrixB = [['0', '0'], ['0', '0']]
      this.matrixResult = []
    },
    clearEquation() {
      this.matrixEqA = [['0', '0', '0'], ['0', '0', '0'], ['0', '0', '0']]
      this.matrixEqB = [['0'], ['0'], ['0']]
      this.equationResult = null
    },
    loadExample() {
      this.matrixA = [['1', '2'], ['3', '4']]
      this.matrixB = [['5', '6'], ['7', '8']]
      this.calculateMatrix()
    }
  }
}
</script>

<style scoped>
.matrix-tool {
  padding: 20px;
}

.matrix-section {
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  padding: 15px;
}

.matrix-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
}

.matrix-grid {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.matrix-row {
  display: flex;
  gap: 5px;
}

.matrix-cell {
  width: 60px;
}

.matrix-cell >>> .el-input__inner {
  text-align: center;
  padding: 0 5px;
}

.matrix-size {
  text-align: center;
  margin-top: 10px;
  color: #909399;
  font-size: 12px;
}

.operator-section {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
}

.action-buttons {
  text-align: center;
  margin: 20px 0;
}

.result-section {
  margin-top: 20px;
  padding: 15px;
  background: #f5f7fa;
  border-radius: 4px;
}

.result-title {
  font-weight: bold;
  margin-bottom: 10px;
  color: #606266;
}

.result-grid {
  display: inline-flex;
}

.result-cell {
  width: 60px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  font-size: 14px;
}

.properties-section {
  padding: 15px;
}

.properties-result {
  margin-top: 15px;
}

.transpose-matrix,
.inverse-matrix {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.equation-result {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
}

.equation-variable {
  padding: 10px 20px;
  background: #fff;
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  font-size: 16px;
  font-weight: bold;
  color: #409eff;
}
</style>
