<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>国家信息查询</span>
        <span style="font-size:12px;color:#909399;margin-left:10px">数据来源: REST Countries API</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <el-input
            v-model="searchKeyword"
            placeholder="搜索国家名称（支持中英文）..."
            prefix-icon="el-icon-search"
            clearable
            size="large"
            @input="debouncedSearch"
          />
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 15px">
        <el-col :span="24">
          <el-radio-group v-model="regionFilter" size="small" @change="filterByRegion">
            <el-radio-button label="">全部</el-radio-button>
            <el-radio-button label="Asia">亚洲</el-radio-button>
            <el-radio-button label="Europe">欧洲</el-radio-button>
            <el-radio-button label="Africa">非洲</el-radio-button>
            <el-radio-button label="Americas">美洲</el-radio-button>
            <el-radio-button label="Oceania">大洋洲</el-radio-button>
          </el-radio-group>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 15px">
        <el-col :span="24">
          <el-table
            :data="displayedCountries"
            border
            size="small"
            v-loading="loading"
            @row-click="showDetail"
            style="cursor: pointer"
            max-height="400"
          >
            <el-table-column label="国旗" width="80" align="center">
              <template slot-scope="scope">
                <img :src="scope.row.flag" style="width:40px;height:auto;border:1px solid #ebeef5" :alt="scope.row.name" />
              </template>
            </el-table-column>
            <el-table-column prop="name" label="国家名称" sortable />
            <el-table-column prop="capital" label="首都" sortable />
            <el-table-column prop="region" label="地区" sortable width="100" />
            <el-table-column prop="population" label="人口" sortable width="140">
              <template slot-scope="scope">
                {{ formatNumber(scope.row.population) }}
              </template>
            </el-table-column>
            <el-table-column prop="area" label="面积(km²)" sortable width="120">
              <template slot-scope="scope">
                {{ formatNumber(scope.row.area) }}
              </template>
            </el-table-column>
            <el-table-column label="货币" width="120">
              <template slot-scope="scope">
                {{ scope.row.currencies || '-' }}
              </template>
            </el-table-column>
          </el-table>
        </el-col>
      </el-row>

      <el-dialog :title="detailCountry ? detailCountry.name : ''" :visible.sync="dialogVisible" width="700px">
        <el-row :gutter="20" v-if="detailCountry">
          <el-col :span="8" style="text-align:center">
            <img :src="detailCountry.flag" style="width:120px;border:1px solid #ebeef5" />
            <h3>{{ detailCountry.nativeName }}</h3>
          </el-col>
          <el-col :span="16">
            <el-descriptions :column="2" border size="small">
              <el-descriptions-item label="首都">{{ detailCountry.capital }}</el-descriptions-item>
              <el-descriptions-item label="地区">{{ detailCountry.region }} / {{ detailCountry.subregion }}</el-descriptions-item>
              <el-descriptions-item label="人口">{{ formatNumber(detailCountry.population) }}</el-descriptions-item>
              <el-descriptions-item label="面积">{{ formatNumber(detailCountry.area) }} km²</el-descriptions-item>
              <el-descriptions-item label="货币">{{ detailCountry.currencies }}</el-descriptions-item>
              <el-descriptions-item label="语言">{{ detailCountry.languages }}</el-descriptions-item>
              <el-descriptions-item label="时区">{{ detailCountry.timezones }}</el-descriptions-item>
              <el-descriptions-item label="域名">{{ detailCountry.tld }}</el-descriptions-item>
              <el-descriptions-item label="ISO代码" :span="2">
                {{ detailCountry.alpha2Code }} / {{ detailCountry.alpha3Code }}
              </el-descriptions-item>
              <el-descriptions-item label="电话区号">{{ detailCountry.callingCodes }}</el-descriptions-item>
              <el-descriptions-item label="独立状态">{{ detailCountry.independent }}</el-descriptions-item>
              <el-descriptions-item label="联合国成员">{{ detailCountry.unMember }}</el-descriptions-item>
              <el-descriptions-item label="经纬度">{{ detailCountry.latlng }}</el-descriptions-item>
            </el-descriptions>
          </el-col>
        </el-row>
      </el-dialog>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CountryInfoTool',
  data() {
    return {
      searchKeyword: '',
      regionFilter: '',
      allCountries: [],
      displayedCountries: [],
      loading: false,
      dialogVisible: false,
      detailCountry: null,
      searchTimer: null,
      regionNameMap: {
        'Asia': '亚洲',
        'Europe': '欧洲',
        'Africa': '非洲',
        'Americas': '美洲',
        'Oceania': '大洋洲',
      }
    }
  },
  mounted() {
    this.fetchCountries()
  },
  methods: {
    async fetchCountries() {
      this.loading = true
      try {
        const res = await fetch('https://restcountries.com/v2/all?fields=name,capital,region,subregion,population,area,flag,nativeName,currencies,languages,timezones,topLevelDomain,alpha2Code,alpha3Code,callingCodes,latlng,independent,unMember')
        if (!res.ok) throw new Error('API 请求失败')
        const data = await res.json()
        this.allCountries = data.map(c => ({
          name: c.name || c.translations?.zh || '',
          capital: c.capital || '-',
          region: c.region || '-',
          subregion: c.subregion || '-',
          population: c.population || 0,
          area: c.area || 0,
          flag: c.flag || '',
          nativeName: c.nativeName || '',
          currencies: (c.currencies || []).map(cu => `${cu.name || ''} (${cu.symbol || ''})`).join(', '),
          languages: (c.languages || []).map(l => l.name).join(', '),
          timezones: (c.timezones || []).join(', '),
          tld: (c.topLevelDomain || []).join(', '),
          alpha2Code: c.alpha2Code || '',
          alpha3Code: c.alpha3Code || '',
          callingCodes: (c.callingCodes || []).filter(Boolean).join(', '),
          latlng: (c.latlng || []).filter(Boolean).join(', '),
          independent: c.independent ? '是' : '否',
          unMember: c.unMember ? '是' : '否',
        }))
        this.displayedCountries = this.allCountries
      } catch (e) {
        this.$message.error('获取国家数据失败: ' + e.message)
      } finally {
        this.loading = false
      }
    },
    debouncedSearch() {
      if (this.searchTimer) clearTimeout(this.searchTimer)
      this.searchTimer = setTimeout(() => this.doSearch(), 300)
    },
    doSearch() {
      const kw = this.searchKeyword.trim().toLowerCase()
      let list = this.allCountries

      if (this.regionFilter) {
        list = list.filter(c => c.region === this.regionFilter)
      }

      if (kw) {
        list = list.filter(c =>
          c.name.toLowerCase().includes(kw) ||
          c.capital.toLowerCase().includes(kw) ||
          c.region.toLowerCase().includes(kw) ||
          c.alpha2Code.toLowerCase().includes(kw) ||
          c.alpha3Code.toLowerCase().includes(kw)
        )
      }

      this.displayedCountries = list
    },
    filterByRegion(region) {
      this.regionFilter = region
      this.doSearch()
    },
    showDetail(row) {
      this.detailCountry = row
      this.dialogVisible = true
    },
    formatNumber(num) {
      if (!num) return '-'
      if (num >= 1e8) return (num / 1e8).toFixed(1) + ' 亿'
      if (num >= 1e4) return (num / 1e4).toFixed(1) + ' 万'
      return num.toLocaleString()
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  padding: 20px;
}
</style>
