<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Lorem 文本生成器</span>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="100px">
            <el-form-item label="生成类型">
              <el-radio-group v-model="type">
                <el-radio label="paragraphs">段落</el-radio>
                <el-radio label="sentences">句子</el-radio>
                <el-radio label="words">单词</el-radio>
              </el-radio-group>
            </el-form-item>
            
            <el-form-item label="数量">
              <el-input-number v-model="count" :min="1" :max="100" />
            </el-form-item>
            
            <el-form-item label="开始方式">
              <el-checkbox v-model="startWithLorem">以 "Lorem ipsum..." 开头</el-checkbox>
            </el-form-item>
            
            <el-form-item>
              <el-button type="primary" @click="generate">生成</el-button>
              <el-button @click="copyResult">复制结果</el-button>
            </el-form-item>
          </el-form>
        </el-col>
        
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">统计信息</div>
            <el-descriptions :column="2" border size="small">
              <el-descriptions-item label="字符数">{{ stats.chars }}</el-descriptions-item>
              <el-descriptions-item label="单词数">{{ stats.words }}</el-descriptions-item>
              <el-descriptions-item label="句子数">{{ stats.sentences }}</el-descriptions-item>
              <el-descriptions-item label="段落数">{{ stats.paragraphs }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <div class="result-section">
            <div class="section-header">
              <span>生成结果</span>
            </div>
            <el-input
              v-model="result"
              type="textarea"
              :rows="12"
              readonly
              placeholder="生成的 Lorem 文本将显示在这里"
            />
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'LoremTool',
  data() {
    return {
      type: 'paragraphs',
      count: 3,
      startWithLorem: true,
      result: '',
      loremWords: [
        'lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing', 'elit',
        'sed', 'do', 'eiusmod', 'tempor', 'incididunt', 'ut', 'labore', 'et', 'dolore',
        'magna', 'aliqua', 'enim', 'ad', 'minim', 'veniam', 'quis', 'nostrud',
        'exercitation', 'ullamco', 'laboris', 'nisi', 'aliquip', 'ex', 'ea', 'commodo',
        'consequat', 'duis', 'aute', 'irure', 'in', 'reprehenderit', 'voluptate',
        'velit', 'esse', 'cillum', 'fugiat', 'nulla', 'pariatur', 'excepteur', 'sint',
        'occaecat', 'cupidatat', 'non', 'proident', 'sunt', 'culpa', 'qui', 'officia',
        'deserunt', 'mollit', 'anim', 'id', 'est', 'laborum', 'perspiciatis', 'unde',
        'omnis', 'iste', 'natus', 'error', 'voluptatem', 'accusantium', 'doloremque',
        'laudantium', 'totam', 'rem', 'aperiam', 'eaque', 'ipsa', 'quae', 'ab', 'illo',
        'inventore', 'veritatis', 'quasi', 'architecto', 'beatae', 'vitae', 'dicta',
        'explicabo', 'nemo', 'ipsam', 'quia', 'voluptas', 'aspernatur', 'aut', 'odit',
        'fugit', 'consequuntur', 'magni', 'dolores', 'eos', 'ratione', 'sequi',
        'nesciunt', 'neque', 'porro', 'quisquam', 'dolorem', 'adipisci', 'numquam',
        'eius', 'modi', 'tempora', 'magnam', 'quaerat'
      ],
      startText: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit'
    }
  },
  computed: {
    stats() {
      if (!this.result) return { chars: 0, words: 0, sentences: 0, paragraphs: 0 }
      
      return {
        chars: this.result.length,
        words: this.result.split(/\s+/).filter(w => w).length,
        sentences: this.result.split(/[.!?]+/).filter(s => s.trim()).length,
        paragraphs: this.result.split(/\n\n+/).filter(p => p.trim()).length
      }
    }
  },
  mounted() {
    this.generate()
  },
  methods: {
    generate() {
      this.result = ''
      
      switch (this.type) {
        case 'paragraphs':
          this.result = this.generateParagraphs(this.count)
          break
        case 'sentences':
          this.result = this.generateSentences(this.count)
          break
        case 'words':
          this.result = this.generateWords(this.count)
          break
      }
    },
    generateParagraphs(count) {
      const paragraphs = []
      for (let i = 0; i < count; i++) {
        const sentenceCount = Math.floor(Math.random() * 4) + 4
        let paragraph = ''
        
        if (i === 0 && this.startWithLorem) {
          paragraph = this.startText + '. '
          for (let j = 1; j < sentenceCount; j++) {
            paragraph += this.generateSentence() + ' '
          }
        } else {
          for (let j = 0; j < sentenceCount; j++) {
            paragraph += this.generateSentence() + ' '
          }
        }
        
        paragraphs.push(paragraph.trim())
      }
      return paragraphs.join('\n\n')
    },
    generateSentences(count) {
      const sentences = []
      for (let i = 0; i < count; i++) {
        if (i === 0 && this.startWithLorem) {
          sentences.push(this.startText + '.')
        } else {
          sentences.push(this.generateSentence())
        }
      }
      return sentences.join(' ')
    },
    generateWords(count) {
      const words = []
      for (let i = 0; i < count; i++) {
        if (i === 0 && this.startWithLorem) {
          words.push('Lorem', 'ipsum', 'dolor', 'sit', 'amet')
          i += 4
        } else {
          words.push(this.loremWords[Math.floor(Math.random() * this.loremWords.length)])
        }
      }
      return words.slice(0, count).join(' ')
    },
    generateSentence() {
      const wordCount = Math.floor(Math.random() * 10) + 5
      const words = []
      
      for (let i = 0; i < wordCount; i++) {
        words.push(this.loremWords[Math.floor(Math.random() * this.loremWords.length)])
      }
      
      let sentence = words.join(' ')
      sentence = sentence.charAt(0).toUpperCase() + sentence.slice(1)
      sentence += '.'
      
      return sentence
    },
    copyResult() {
      if (!this.result) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.result).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .result-section {
    .section-header {
      font-weight: bold;
      margin-bottom: 10px;
    }
  }
}
</style>
