<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>进制转换</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="11">
          <div class="input-section">
            <div class="section-header">
              <span>输入值</span>
              <el-tag size="mini" type="primary">选择进制后输入</el-tag>
            </div>
            <el-select v-model="fromRadix" style="width: 100%; margin-bottom: 10px" @change="onRadixChange">
              <el-option label="二进制 (Base 2)" :value="2" />
              <el-option label="八进制 (Base 8)" :value="8" />
              <el-option label="十进制 (Base 10)" :value="10" />
              <el-option label="十六进制 (Base 16)" :value="16" />
              <el-option label="三十二进制 (Base 32)" :value="32" />
              <el-option label="六十四进制 (Base 64)" :value="64" />
            </el-select>
            <el-input
              v-model="inputValue"
              placeholder="输入数值"
              @input="convert"
            />
          </div>
        </el-col>
        
        <el-col :span="2" class="actions-col">
          <div class="action-buttons">
            <el-button type="primary" circle @click="convert" title="转换">
              <i class="el-icon-right"></i>
            </el-button>
            <span class="action-label">转换</span>
            <el-button type="warning" circle @click="swapRadix" title="交换进制">
              <i class="el-icon-sort"></i>
            </el-button>
            <span class="action-label">交换</span>
          </div>
        </el-col>
        
        <el-col :span="11">
          <div class="output-section">
            <div class="section-header">
              <span>输出值</span>
              <el-tag size="mini" type="success">选择目标进制</el-tag>
            </div>
            <el-select v-model="toRadix" style="width: 100%; margin-bottom: 10px" @change="convert">
              <el-option label="二进制 (Base 2)" :value="2" />
              <el-option label="八进制 (Base 8)" :value="8" />
              <el-option label="十进制 (Base 10)" :value="10" />
              <el-option label="十六进制 (Base 16)" :value="16" />
              <el-option label="三十二进制 (Base 32)" :value="32" />
              <el-option label="六十四进制 (Base 64)" :value="64" />
            </el-select>
            <el-input
              v-model="outputValue"
              placeholder="转换结果"
              readonly
            />
            <el-button type="text" size="mini" style="margin-top: 5px" @click="copyResult">复制结果</el-button>
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px" v-if="inputValue">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">所有进制结果</div>
            <el-table :data="allRadixResults" border size="small">
              <el-table-column prop="name" label="进制" width="150" />
              <el-table-column prop="value" label="值">
                <template slot-scope="scope">
                  <code>{{ scope.row.value }}</code>
                  <el-button type="text" size="mini" style="float: right" @click="copy(scope.row.value)">复制</el-button>
                </template>
              </el-table-column>
            </el-table>
          </el-card>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-alert type="info" :closable="false" show-icon>
            <template slot="title">
              使用提示：选择输入进制后输入数值，自动转换为所有进制。点击"交换"可快速切换输入输出进制。
            </template>
          </el-alert>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
const BASE64_CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/'

export default {
  name: 'RadixTool',
  data() {
    return {
      fromRadix: 10,
      toRadix: 16,
      inputValue: '',
      outputValue: '',
      decimalValue: null
    }
  },
  computed: {
    allRadixResults() {
      if (this.decimalValue === null) return []
      
      return [
        { name: '二进制 (Base 2)', value: this.decimalValue.toString(2) },
        { name: '八进制 (Base 8)', value: this.decimalValue.toString(8) },
        { name: '十进制 (Base 10)', value: this.decimalValue.toString(10) },
        { name: '十六进制 (Base 16)', value: this.decimalValue.toString(16).toUpperCase() },
        { name: '三十二进制 (Base 32)', value: this.toBase32(this.decimalValue) },
        { name: '六十四进制 (Base 64)', value: this.toBase64(this.decimalValue) }
      ]
    }
  },
  methods: {
    onRadixChange() {
      this.convert()
    },
    convert() {
      if (!this.inputValue.trim()) {
        this.outputValue = ''
        this.decimalValue = null
        return
      }
      
      try {
        const input = this.inputValue.trim()
        
        if (this.fromRadix === 32) {
          this.decimalValue = this.fromBase32(input)
        } else if (this.fromRadix === 64) {
          this.decimalValue = this.fromBase64(input)
        } else {
          this.decimalValue = parseInt(input, this.fromRadix)
        }
        
        if (isNaN(this.decimalValue)) {
          throw new Error('无效的数值')
        }
        
        if (this.toRadix === 32) {
          this.outputValue = this.toBase32(this.decimalValue)
        } else if (this.toRadix === 64) {
          this.outputValue = this.toBase64(this.decimalValue)
        } else {
          this.outputValue = this.decimalValue.toString(this.toRadix).toUpperCase()
        }
      } catch (e) {
        this.outputValue = '转换错误: ' + e.message
        this.decimalValue = null
      }
    },
    toBase32(num) {
      if (num === 0) return '0'
      const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUV'
      let result = ''
      while (num > 0) {
        result = chars[num % 32] + result
        num = Math.floor(num / 32)
      }
      return result
    },
    fromBase32(str) {
      const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUV'
      let result = 0
      for (let i = 0; i < str.length; i++) {
        const c = str[i].toUpperCase()
        const idx = chars.indexOf(c)
        if (idx === -1) throw new Error('无效的Base32字符')
        result = result * 32 + idx
      }
      return result
    },
    toBase64(num) {
      if (num === 0) return '0'
      let result = ''
      while (num > 0) {
        result = BASE64_CHARS[num % 64] + result
        num = Math.floor(num / 64)
      }
      return result
    },
    fromBase64(str) {
      let result = 0
      for (let i = 0; i < str.length; i++) {
        const idx = BASE64_CHARS.indexOf(str[i])
        if (idx === -1) throw new Error('无效的Base64字符')
        result = result * 64 + idx
      }
      return result
    },
    swapRadix() {
      const temp = this.fromRadix
      this.fromRadix = this.toRadix
      this.toRadix = temp
      this.inputValue = this.outputValue
      this.convert()
    },
    clearAll() {
      this.inputValue = ''
      this.outputValue = ''
      this.decimalValue = null
    },
    copyResult() {
      if (!this.outputValue) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.outputValue).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    copy(text) {
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section, .output-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;
    }
  }

  .actions-col {
    display: flex;
    align-items: center;
    justify-content: center;

    .action-buttons {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;

      .action-label {
        font-size: 12px;
        color: #606266;
        margin-bottom: 10px;
      }
    }
  }

  code {
    background: #f5f7fa;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: monospace;
    word-break: break-all;
  }
}
</style>
