<template>
  <div class="image-filter-tool">
    <el-card>
      <div slot="header">
        <span>图片滤镜工具</span>
        <el-button-group style="float: right;">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="upload-area" @click="triggerUpload">
            <input type="file" ref="fileInput" @change="handleFileSelect" accept="image/*" style="display: none" />
            <div v-if="!originalImage" class="upload-placeholder">
              <i class="el-icon-upload" style="font-size: 48px; color: #909399"></i>
              <p>点击上传图片</p>
            </div>
            <img v-else :src="originalImage" class="preview-image" />
          </div>
        </el-col>

        <el-col :span="12">
          <div class="result-area">
            <canvas ref="canvas" class="preview-image" v-show="processedImage"></canvas>
            <div v-if="!processedImage" class="result-placeholder">
              <i class="el-icon-picture-outline" style="font-size: 48px; color: #c0c4cc"></i>
              <p>处理后的图片</p>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-divider>滤镜设置</el-divider>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="基础调整" name="basic">
          <el-form label-width="80px">
            <el-row :gutter="20">
              <el-col :span="12">
                <el-form-item label="亮度">
                  <el-slider v-model="filters.brightness" :min="0" :max="200" :format-tooltip="val => val + '%'" @change="applyFilters" />
                </el-form-item>
              </el-col>
              <el-col :span="12">
                <el-form-item label="对比度">
                  <el-slider v-model="filters.contrast" :min="0" :max="200" :format-tooltip="val => val + '%'" @change="applyFilters" />
                </el-form-item>
              </el-col>
            </el-row>
            <el-row :gutter="20">
              <el-col :span="12">
                <el-form-item label="饱和度">
                  <el-slider v-model="filters.saturate" :min="0" :max="200" :format-tooltip="val => val + '%'" @change="applyFilters" />
                </el-form-item>
              </el-col>
              <el-col :span="12">
                <el-form-item label="色相旋转">
                  <el-slider v-model="filters.hueRotate" :min="0" :max="360" :format-tooltip="val => val + '°'" @change="applyFilters" />
                </el-form-item>
              </el-col>
            </el-row>
            <el-row :gutter="20">
              <el-col :span="12">
                <el-form-item label="模糊">
                  <el-slider v-model="filters.blur" :min="0" :max="20" :format-tooltip="val => val + 'px'" @change="applyFilters" />
                </el-form-item>
              </el-col>
              <el-col :span="12">
                <el-form-item label="透明度">
                  <el-slider v-model="filters.opacity" :min="0" :max="100" :format-tooltip="val => val + '%'" @change="applyFilters" />
                </el-form-item>
              </el-col>
            </el-row>
          </el-form>
        </el-tab-pane>

        <el-tab-pane label="预设滤镜" name="preset">
          <div class="preset-grid">
            <div v-for="preset in presets" :key="preset.name" class="preset-item" @click="applyPreset(preset)">
              <div class="preset-preview" :style="{ filter: preset.filter }">
                <i class="el-icon-picture"></i>
              </div>
              <span>{{ preset.name }}</span>
            </div>
          </div>
        </el-tab-pane>

        <el-tab-pane label="色彩调整" name="color">
          <el-form label-width="80px">
            <el-row :gutter="20">
              <el-col :span="8">
                <el-form-item label="红色">
                  <el-slider v-model="colorAdjust.r" :min="-100" :max="100" @change="applyColorAdjust" />
                </el-form-item>
              </el-col>
              <el-col :span="8">
                <el-form-item label="绿色">
                  <el-slider v-model="colorAdjust.g" :min="-100" :max="100" @change="applyColorAdjust" />
                </el-form-item>
              </el-col>
              <el-col :span="8">
                <el-form-item label="蓝色">
                  <el-slider v-model="colorAdjust.b" :min="-100" :max="100" @change="applyColorAdjust" />
                </el-form-item>
              </el-col>
            </el-row>
          </el-form>
        </el-tab-pane>
      </el-tabs>

      <el-divider></el-divider>

      <el-form label-width="80px">
        <el-form-item>
          <el-button type="primary" @click="applyFilters" :disabled="!originalImage">应用滤镜</el-button>
          <el-button @click="resetFilters">重置</el-button>
          <el-button type="success" @click="download" :disabled="!processedImage">下载图片</el-button>
        </el-form-item>
      </el-form>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ImageFilterTool',
  data() {
    return {
      originalImage: '',
      processedImage: false,
      activeTab: 'basic',
      filters: {
        brightness: 100,
        contrast: 100,
        saturate: 100,
        hueRotate: 0,
        blur: 0,
        opacity: 100
      },
      colorAdjust: {
        r: 0,
        g: 0,
        b: 0
      },
      presets: [
        { name: '原图', filter: 'none', values: { brightness: 100, contrast: 100, saturate: 100, hueRotate: 0, blur: 0, opacity: 100 } },
        { name: '复古', filter: 'sepia(80%)', values: { brightness: 100, contrast: 90, saturate: 80, hueRotate: 30, blur: 0, opacity: 100 } },
        { name: '黑白', filter: 'grayscale(100%)', values: { brightness: 100, contrast: 100, saturate: 0, hueRotate: 0, blur: 0, opacity: 100 } },
        { name: '反转', filter: 'invert(100%)', values: { brightness: 100, contrast: 100, saturate: 100, hueRotate: 180, blur: 0, opacity: 100 } },
        { name: '暖色', filter: 'sepia(30%) saturate(140%)', values: { brightness: 105, contrast: 100, saturate: 140, hueRotate: 15, blur: 0, opacity: 100 } },
        { name: '冷色', filter: 'saturate(80%) hue-rotate(180deg)', values: { brightness: 100, contrast: 100, saturate: 80, hueRotate: 180, blur: 0, opacity: 100 } },
        { name: '高对比', filter: 'contrast(150%)', values: { brightness: 100, contrast: 150, saturate: 100, hueRotate: 0, blur: 0, opacity: 100 } },
        { name: '柔和', filter: 'brightness(110%) contrast(90%)', values: { brightness: 110, contrast: 90, saturate: 90, hueRotate: 0, blur: 1, opacity: 100 } },
        { name: '戏剧', filter: 'contrast(130%) saturate(130%)', values: { brightness: 100, contrast: 130, saturate: 130, hueRotate: 0, blur: 0, opacity: 100 } },
        { name: '褪色', filter: 'saturate(50%) brightness(110%)', values: { brightness: 110, contrast: 95, saturate: 50, hueRotate: 0, blur: 0, opacity: 100 } }
      ],
      originalImageData: null
    }
  },
  methods: {
    triggerUpload() {
      this.$refs.fileInput.click()
    },
    handleFileSelect(e) {
      const file = e.target.files[0]
      if (file) {
        const reader = new FileReader()
        reader.onload = (event) => {
          this.originalImage = event.target.result
          this.loadImageToCanvas()
        }
        reader.readAsDataURL(file)
      }
    },
    loadImageToCanvas() {
      const img = new Image()
      img.onload = () => {
        const canvas = this.$refs.canvas
        canvas.width = img.width
        canvas.height = img.height
        const ctx = canvas.getContext('2d')
        ctx.drawImage(img, 0, 0)
        this.originalImageData = ctx.getImageData(0, 0, canvas.width, canvas.height)
        this.processedImage = true
      }
      img.src = this.originalImage
    },
    applyFilters() {
      if (!this.originalImage) return
      
      const canvas = this.$refs.canvas
      const ctx = canvas.getContext('2d')
      
      const img = new Image()
      img.onload = () => {
        canvas.width = img.width
        canvas.height = img.height
        
        const filterString = `
          brightness(${this.filters.brightness}%)
          contrast(${this.filters.contrast}%)
          saturate(${this.filters.saturate}%)
          hue-rotate(${this.filters.hueRotate}deg)
          blur(${this.filters.blur}px)
          opacity(${this.filters.opacity}%)
        `
        
        ctx.filter = filterString
        ctx.drawImage(img, 0, 0)
        this.processedImage = true
      }
      img.src = this.originalImage
    },
    applyColorAdjust() {
      if (!this.originalImageData) return
      
      const canvas = this.$refs.canvas
      const ctx = canvas.getContext('2d')
      const imageData = new ImageData(
        new Uint8ClampedArray(this.originalImageData.data),
        this.originalImageData.width,
        this.originalImageData.height
      )
      
      const data = imageData.data
      for (let i = 0; i < data.length; i += 4) {
        data[i] = Math.min(255, Math.max(0, data[i] + this.colorAdjust.r * 2.55))
        data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + this.colorAdjust.g * 2.55))
        data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + this.colorAdjust.b * 2.55))
      }
      
      ctx.putImageData(imageData, 0, 0)
      this.processedImage = true
    },
    applyPreset(preset) {
      this.filters = { ...preset.values }
      this.applyFilters()
    },
    resetFilters() {
      this.filters = {
        brightness: 100,
        contrast: 100,
        saturate: 100,
        hueRotate: 0,
        blur: 0,
        opacity: 100
      }
      this.colorAdjust = { r: 0, g: 0, b: 0 }
      this.applyFilters()
    },
    download() {
      const canvas = this.$refs.canvas
      const link = document.createElement('a')
      link.download = `filtered_${Date.now()}.png`
      link.href = canvas.toDataURL('image/png')
      link.click()
    },
    clearAll() {
      this.originalImage = ''
      this.processedImage = false
      this.originalImageData = null
      this.resetFilters()
      this.$refs.fileInput.value = ''
    }
  }
}
</script>

<style scoped>
.image-filter-tool {
  padding: 20px;
}

.upload-area,
.result-area {
  border: 2px dashed #dcdfe6;
  border-radius: 8px;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color 0.3s;
  overflow: hidden;
}

.upload-area:hover {
  border-color: #409EFF;
}

.upload-placeholder,
.result-placeholder {
  text-align: center;
  color: #909399;
}

.preview-image {
  max-width: 100%;
  max-height: 300px;
  object-fit: contain;
}

.preset-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 15px;
}

.preset-item {
  text-align: center;
  cursor: pointer;
  padding: 10px;
  border-radius: 8px;
  transition: all 0.3s;
}

.preset-item:hover {
  background: #f5f7fa;
}

.preset-preview {
  width: 80px;
  height: 80px;
  margin: 0 auto 8px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preset-preview i {
  font-size: 32px;
  color: white;
}

.preset-item span {
  font-size: 12px;
  color: #606266;
}
</style>
