<template>
  <div class="border-radius-tool">
    <el-card>
      <div slot="header">
        <span>CSS 圆角生成器</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="100px">
            <el-form-item label="统一圆角">
              <el-switch v-model="unified" />
            </el-form-item>

            <template v-if="unified">
              <el-form-item label="圆角大小">
                <el-slider v-model="borderRadius.all" :min="0" :max="200" @input="generateCSS" />
                <span>{{ borderRadius.all }}px</span>
              </el-form-item>
            </template>

            <template v-else>
              <el-form-item label="左上角">
                <el-slider v-model="borderRadius.topLeft" :min="0" :max="200" @input="generateCSS" />
                <span>{{ borderRadius.topLeft }}px</span>
              </el-form-item>

              <el-form-item label="右上角">
                <el-slider v-model="borderRadius.topRight" :min="0" :max="200" @input="generateCSS" />
                <span>{{ borderRadius.topRight }}px</span>
              </el-form-item>

              <el-form-item label="左下角">
                <el-slider v-model="borderRadius.bottomLeft" :min="0" :max="200" @input="generateCSS" />
                <span>{{ borderRadius.bottomLeft }}px</span>
              </el-form-item>

              <el-form-item label="右下角">
                <el-slider v-model="borderRadius.bottomRight" :min="0" :max="200" @input="generateCSS" />
                <span>{{ borderRadius.bottomRight }}px</span>
              </el-form-item>
            </template>

            <el-divider>椭圆/圆形</el-divider>

            <el-form-item label="椭圆模式">
              <el-switch v-model="ellipse" />
            </el-form-item>

            <template v-if="ellipse">
              <el-form-item label="水平半径">
                <el-slider v-model="borderRadius.horizontal" :min="0" :max="200" @input="generateCSS" />
                <span>{{ borderRadius.horizontal }}px</span>
              </el-form-item>

              <el-form-item label="垂直半径">
                <el-slider v-model="borderRadius.vertical" :min="0" :max="200" @input="generateCSS" />
                <span>{{ borderRadius.vertical }}px</span>
              </el-form-item>
            </template>
          </el-form>

          <el-divider>预设样式</el-divider>
          <div class="preset-container">
            <div 
              v-for="(preset, index) in presets" 
              :key="index" 
              class="preset-item"
              @click="applyPreset(preset)"
            >
              <div class="preset-box" :style="getPresetStyle(preset)"></div>
              <span>{{ preset.name }}</span>
            </div>
          </div>
        </el-col>

        <el-col :span="12">
          <el-divider>预览</el-divider>
          <div class="preview-container">
            <div class="preview-box" :style="previewStyle">
              预览区域
            </div>
          </div>

          <el-divider>元素设置</el-divider>
          <el-form label-width="100px">
            <el-form-item label="宽度">
              <el-slider v-model="element.width" :min="50" :max="400" />
              <span>{{ element.width }}px</span>
            </el-form-item>
            <el-form-item label="高度">
              <el-slider v-model="element.height" :min="50" :max="400" />
              <span>{{ element.height }}px</span>
            </el-form-item>
            <el-form-item label="背景色">
              <el-color-picker v-model="element.background" />
            </el-form-item>
            <el-form-item label="边框">
              <el-input-number v-model="element.borderWidth" :min="0" :max="10" />
              <el-color-picker v-model="element.borderColor" style="margin-left: 10px" />
            </el-form-item>
          </el-form>

          <el-divider>生成的CSS代码</el-divider>
          <el-input
            type="textarea"
            :rows="8"
            :value="generatedCSS"
            readonly
          />
          <div style="margin-top: 10px">
            <el-button type="primary" @click="copyCSS">复制CSS</el-button>
            <el-button @click="reset">重置</el-button>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'BorderRadiusTool',
  data() {
    return {
      unified: true,
      ellipse: false,
      borderRadius: {
        all: 20,
        topLeft: 0,
        topRight: 0,
        bottomLeft: 0,
        bottomRight: 0,
        horizontal: 50,
        vertical: 50
      },
      element: {
        width: 200,
        height: 150,
        background: '#409EFF',
        borderWidth: 0,
        borderColor: '#303133'
      },
      presets: [
        { name: '无圆角', all: 0 },
        { name: '小圆角', all: 8 },
        { name: '中圆角', all: 16 },
        { name: '大圆角', all: 24 },
        { name: '圆形', all: 999 },
        { name: '胶囊', all: 999, width: 200, height: 60 },
        { name: '左上角', topLeft: 50, others: 0 },
        { name: '不对称', topLeft: 30, topRight: 10, bottomLeft: 10, bottomRight: 30 }
      ]
    }
  },
  computed: {
    previewStyle() {
      const style = {
        width: `${this.element.width}px`,
        height: `${this.element.height}px`,
        background: this.element.background,
        borderWidth: `${this.element.borderWidth}px`,
        borderColor: this.element.borderColor,
        borderStyle: 'solid'
      }

      if (this.ellipse) {
        style.borderRadius = `${this.borderRadius.horizontal}px / ${this.borderRadius.vertical}px`
      } else if (this.unified) {
        style.borderRadius = `${this.borderRadius.all}px`
      } else {
        style.borderRadius = `${this.borderRadius.topLeft}px ${this.borderRadius.topRight}px ${this.borderRadius.bottomRight}px ${this.borderRadius.bottomLeft}px`
      }

      return style
    },
    generatedCSS() {
      let radiusCSS = ''
      if (this.ellipse) {
        radiusCSS = `border-radius: ${this.borderRadius.horizontal}px / ${this.borderRadius.vertical}px;`
      } else if (this.unified) {
        radiusCSS = `border-radius: ${this.borderRadius.all}px;`
      } else {
        radiusCSS = `border-radius: ${this.borderRadius.topLeft}px ${this.borderRadius.topRight}px ${this.borderRadius.bottomRight}px ${this.borderRadius.bottomLeft}px;`
      }

      return `.element {
  width: ${this.element.width}px;
  height: ${this.element.height}px;
  background: ${this.element.background};
  ${radiusCSS}
  ${this.element.borderWidth > 0 ? `border: ${this.element.borderWidth}px solid ${this.element.borderColor};` : ''}
}`
    }
  },
  methods: {
    generateCSS() {
      // 触发计算属性更新
    },
    getPresetStyle(preset) {
      const style = {
        width: preset.width || 60,
        height: preset.height || 60,
        background: '#409EFF'
      }

      if (preset.all !== undefined) {
        style.borderRadius = preset.all === 999 ? '50%' : `${preset.all}px`
        if (preset.width && preset.height && preset.all === 999) {
          style.borderRadius = `${Math.min(preset.width, preset.height) / 2}px`
        }
      } else {
        const tl = preset.topLeft || 0
        const tr = preset.topRight || 0
        const bl = preset.bottomLeft || 0
        const br = preset.bottomRight || 0
        style.borderRadius = `${tl}px ${tr}px ${br}px ${bl}px`
      }

      return style
    },
    applyPreset(preset) {
      this.unified = preset.all !== undefined
      this.ellipse = false

      if (preset.all !== undefined) {
        this.borderRadius.all = preset.all === 999 ? Math.min(this.element.width, this.element.height) / 2 : preset.all
      } else {
        this.borderRadius.topLeft = preset.topLeft || 0
        this.borderRadius.topRight = preset.topRight || 0
        this.borderRadius.bottomLeft = preset.bottomLeft || 0
        this.borderRadius.bottomRight = preset.bottomRight || 0
      }

      if (preset.width) this.element.width = preset.width
      if (preset.height) this.element.height = preset.height
    },
    copyCSS() {
      navigator.clipboard.writeText(this.generatedCSS).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    reset() {
      this.unified = true
      this.ellipse = false
      this.borderRadius = {
        all: 20,
        topLeft: 0,
        topRight: 0,
        bottomLeft: 0,
        bottomRight: 0,
        horizontal: 50,
        vertical: 50
      }
      this.element = {
        width: 200,
        height: 150,
        background: '#409EFF',
        borderWidth: 0,
        borderColor: '#303133'
      }
    }
  }
}
</script>

<style scoped>
.border-radius-tool {
  padding: 20px;
}

.preview-container {
  height: 250px;
  background: #f5f7fa;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-box {
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: bold;
  transition: all 0.3s;
}

.preset-container {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
}

.preset-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  padding: 10px;
  border-radius: 8px;
  transition: all 0.3s;
}

.preset-item:hover {
  background: #f5f7fa;
}

.preset-box {
  margin-bottom: 5px;
}

.preset-item span {
  font-size: 12px;
  color: #909399;
}
</style>
