<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>日期时间转换</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>时间戳</span>
            </div>
            <el-input
              v-model="timestamp"
              placeholder="输入时间戳（毫秒）"
              @input="convertFromTimestamp"
            >
              <el-button slot="append" @click="copyTimestamp">复制</el-button>
            </el-input>
          </div>
        </el-col>
        
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>当前时间</span>
            </div>
            <el-input
              :value="currentTimestamp"
              readonly
            >
              <el-button slot="append" @click="copyCurrentTimestamp">复制</el-button>
            </el-input>
          </div>
        </el-col>
      </el-row>
      
      <el-divider>日期时间</el-divider>
      
      <el-row :gutter="20">
        <el-col :span="8">
          <el-form-item label="日期">
            <el-date-picker
              v-model="datetime.date"
              type="date"
              placeholder="选择日期"
              style="width: 100%"
              @change="convertFromDate"
            />
          </el-form-item>
        </el-col>
        
        <el-col :span="8">
          <el-form-item label="时间">
            <el-time-picker
              v-model="datetime.time"
              placeholder="选择时间"
              style="width: 100%"
              @change="convertFromDate"
            />
          </el-form-item>
        </el-col>
        
        <el-col :span="8">
          <el-form-item label="时区">
            <el-select v-model="datetime.timezone" style="width: 100%" @change="convertFromDate">
              <el-option label="UTC" value="UTC" />
              <el-option label="Asia/Shanghai" value="Asia/Shanghai" />
              <el-option label="Asia/Tokyo" value="Asia/Tokyo" />
              <el-option label="America/New_York" value="America/New_York" />
              <el-option label="Europe/London" value="Europe/London" />
              <el-option label="Australia/Sydney" value="Australia/Sydney" />
            </el-select>
          </el-form-item>
        </el-col>
      </el-row>
      
      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-button type="primary" @click="convertFromDate">转换为时间戳</el-button>
        </el-col>
      </el-row>
      
      <el-divider>转换结果</el-divider>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">
              <span>标准格式</span>
            </div>
            <el-form label-width="120px" size="small">
              <el-form-item label="ISO 8601">
                <el-input :value="formats.iso8601" readonly />
              </el-form-item>
              <el-form-item label="RFC 2822">
                <el-input :value="formats.rfc2822" readonly />
              </el-form-item>
              <el-form-item label="自定义格式">
                <el-input v-model="formats.custom" placeholder="YYYY-MM-DD HH:mm:ss" />
              </el-form-item>
            </el-form>
          </el-card>
        </el-col>
        
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">
              <span>相对时间</span>
            </div>
            <el-form label-width="120px" size="small">
              <el-form-item label="相对现在">
                <el-input :value="relativeTime.now" readonly />
              </el-form-item>
              <el-form-item label="相对今天">
                <el-input :value="relativeTime.today" readonly />
              </el-form-item>
              <el-form-item label="相对今年">
                <el-input :value="relativeTime.year" readonly />
              </el-form-item>
            </el-form>
          </el-card>
        </el-col>
      </el-row>
      
      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>更多格式</span>
            </div>
            <el-descriptions :column="3" border size="small">
              <el-descriptions-item label="Unix 时间戳">
                <el-button type="text" size="mini" @click="copyFormat(formats.unix)">复制</el-button>
                {{ formats.unix }}
              </el-descriptions-item>
              <el-descriptions-item label="JavaScript">
                <el-button type="text" size="mini" @click="copyFormat(formats.js)">复制</el-button>
                {{ formats.js }}
              </el-descriptions-item>
              <el-descriptions-item label="MySQL">
                <el-button type="text" size="mini" @click="copyFormat(formats.mysql)">复制</el-button>
                {{ formats.mysql }}
              </el-descriptions-item>
              <el-descriptions-item label="PostgreSQL">
                <el-button type="text" size="mini" @click="copyFormat(formats.postgresql)">复制</el-button>
                {{ formats.postgresql }}
              </el-descriptions-item>
              <el-descriptions-item label="Oracle">
                <el-button type="text" size="mini" @click="copyFormat(formats.oracle)">复制</el-button>
                {{ formats.oracle }}
              </el-descriptions-item>
              <el-descriptions-item label="Java">
                <el-button type="text" size="mini" @click="copyFormat(formats.java)">复制</el-button>
                {{ formats.java }}
              </el-descriptions-item>
              <el-descriptions-item label="Python">
                <el-button type="text" size="mini" @click="copyFormat(formats.python)">复制</el-button>
                {{ formats.python }}
              </el-descriptions-item>
              <el-descriptions-item label="PHP">
                <el-button type="text" size="mini" @click="copyFormat(formats.php)">复制</el-button>
                {{ formats.php }}
              </el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'DateTimeTool',
  data() {
    return {
      timestamp: '',
      currentTimestamp: '',
      datetime: {
        date: null,
        time: null,
        timezone: 'Asia/Shanghai'
      },
      formats: {
        iso8601: '',
        rfc2822: '',
        custom: '',
        unix: '',
        js: '',
        mysql: '',
        postgresql: '',
        oracle: '',
        java: '',
        python: '',
        php: ''
      },
      relativeTime: {
        now: '',
        today: '',
        year: ''
      }
    }
  },
  mounted() {
    this.updateCurrentTimestamp()
    setInterval(this.updateCurrentTimestamp, 1000)
  },
  methods: {
    updateCurrentTimestamp() {
      this.currentTimestamp = Date.now().toString()
    },
    convertFromTimestamp() {
      if (!this.timestamp) return
      
      try {
        const ts = parseInt(this.timestamp)
        const date = new Date(ts)
        
        this.datetime.date = date
        this.datetime.time = date
        
        this.updateFormats(date)
        this.updateRelativeTime(date)
      } catch (error) {
        this.$message.error('转换失败: ' + error.message)
      }
    },
    convertFromDate() {
      if (!this.datetime.date || !this.datetime.time) return
      
      try {
        const date = new Date(this.datetime.date)
        const time = this.datetime.time
        date.setHours(time.getHours())
        date.setMinutes(time.getMinutes())
        date.setSeconds(time.getSeconds())
        
        this.timestamp = date.getTime().toString()
        this.updateFormats(date)
        this.updateRelativeTime(date)
      } catch (error) {
        this.$message.error('转换失败: ' + error.message)
      }
    },
    updateFormats(date) {
      const timezone = this.datetime.timezone
      
      this.formats.iso8601 = date.toISOString()
      this.formats.rfc2822 = date.toUTCString()
      this.formats.unix = Math.floor(date.getTime() / 1000).toString()
      this.formats.js = date.getTime().toString()
      this.formats.mysql = date.toISOString().slice(0, 19).replace('T', ' ')
      this.formats.postgresql = date.toISOString().slice(0, 19).replace('T', ' ')
      this.formats.oracle = date.toISOString().slice(0, 19).replace('T', ' ')
      this.formats.java = date.getTime().toString()
      this.formats.python = date.toISOString()
      this.formats.php = Math.floor(date.getTime() / 1000).toString()
      
      if (this.formats.custom) {
        this.formats.custom = this.formatDate(date, this.formats.custom)
      }
    },
    formatDate(date, format) {
      const year = date.getFullYear()
      const month = String(date.getMonth() + 1).padStart(2, '0')
      const day = String(date.getDate()).padStart(2, '0')
      const hours = String(date.getHours()).padStart(2, '0')
      const minutes = String(date.getMinutes()).padStart(2, '0')
      const seconds = String(date.getSeconds()).padStart(2, '0')
      
      return format
        .replace('YYYY', year)
        .replace('MM', month)
        .replace('DD', day)
        .replace('HH', hours)
        .replace('mm', minutes)
        .replace('ss', seconds)
    },
    updateRelativeTime(date) {
      const now = new Date()
      const today = new Date()
      today.setHours(0, 0, 0, 0)
      const thisYear = new Date()
      thisYear.setMonth(0, 1)
      
      const diffNow = date.getTime() - now.getTime()
      const diffToday = date.getTime() - today.getTime()
      const diffYear = date.getTime() - thisYear.getTime()
      
      this.relativeTime.now = this.formatRelativeTime(diffNow)
      this.relativeTime.today = this.formatRelativeTime(diffToday)
      this.relativeTime.year = this.formatRelativeTime(diffYear)
    },
    formatRelativeTime(ms) {
      const seconds = Math.floor(ms / 1000)
      const minutes = Math.floor(seconds / 60)
      const hours = Math.floor(minutes / 60)
      const days = Math.floor(hours / 24)
      const months = Math.floor(days / 30)
      const years = Math.floor(days / 365)
      
      if (Math.abs(ms) < 1000) return '刚刚'
      if (Math.abs(seconds) < 60) return `${seconds}秒${ms > 0 ? '后' : '前'}`
      if (Math.abs(minutes) < 60) return `${minutes}分钟${ms > 0 ? '后' : '前'}`
      if (Math.abs(hours) < 24) return `${hours}小时${ms > 0 ? '后' : '前'}`
      if (Math.abs(days) < 30) return `${days}天${ms > 0 ? '后' : '前'}`
      if (Math.abs(months) < 12) return `${months}个月${ms > 0 ? '后' : '前'}`
      return `${years}年${ms > 0 ? '后' : '前'}`
    },
    copyTimestamp() {
      navigator.clipboard.writeText(this.timestamp).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    copyCurrentTimestamp() {
      navigator.clipboard.writeText(this.currentTimestamp).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    copyFormat(value) {
      navigator.clipboard.writeText(value).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    clearAll() {
      this.timestamp = ''
      this.datetime = {
        date: null,
        time: null,
        timezone: 'Asia/Shanghai'
      }
      this.formats = {
        iso8601: '',
        rfc2822: '',
        custom: '',
        unix: '',
        js: '',
        mysql: '',
        postgresql: '',
        oracle: '',
        java: '',
        python: '',
        php: ''
      }
      this.relativeTime = {
        now: '',
        today: '',
        year: ''
      }
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }
}
</style>
