<template>
  <div class="gitignore-tool">
    <el-card>
      <div slot="header">
        <span>Git Ignore 生成器</span>
        <el-button-group style="float: right;">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">
              <span>选择项目类型</span>
            </div>
            <el-checkbox-group v-model="selectedTypes">
              <el-row>
                <el-col :span="8" v-for="type in projectTypes" :key="type.value">
                  <el-checkbox :label="type.value" style="margin-bottom: 10px">{{ type.label }}</el-checkbox>
                </el-col>
              </el-row>
            </el-checkbox-group>
          </el-card>

          <el-card shadow="never" style="margin-top: 20px">
            <div slot="header">
              <span>常用忽略项</span>
            </div>
            <el-checkbox-group v-model="selectedCommon">
              <el-row>
                <el-col :span="12" v-for="item in commonItems" :key="item.value">
                  <el-checkbox :label="item.value" style="margin-bottom: 10px">{{ item.label }}</el-checkbox>
                </el-col>
              </el-row>
            </el-checkbox-group>
          </el-card>

          <el-card shadow="never" style="margin-top: 20px">
            <div slot="header">
              <span>自定义规则</span>
            </div>
            <el-input
              v-model="customRules"
              type="textarea"
              :rows="5"
              placeholder="输入自定义忽略规则，每行一个..."
            />
          </el-card>

          <el-button type="primary" style="margin-top: 20px; width: 100%" @click="generate">
            生成 .gitignore
          </el-button>
        </el-col>

        <el-col :span="12">
          <el-card shadow="never" class="result-card">
            <div slot="header">
              <span>生成结果</span>
              <el-button type="text" style="float: right" @click="copyResult">
                <i class="el-icon-document-copy"></i> 复制
              </el-button>
              <el-button type="text" style="float: right; margin-right: 10px" @click="download">
                <i class="el-icon-download"></i> 下载
              </el-button>
            </div>
            <el-input
              v-model="result"
              type="textarea"
              :rows="25"
              readonly
              placeholder="生成的 .gitignore 内容将显示在这里..."
            />
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'GitignoreTool',
  data() {
    return {
      selectedTypes: [],
      selectedCommon: [],
      customRules: '',
      result: '',
      projectTypes: [
        { label: 'Java', value: 'java' },
        { label: 'Python', value: 'python' },
        { label: 'Node.js', value: 'node' },
        { label: 'Vue', value: 'vue' },
        { label: 'React', value: 'react' },
        { label: 'Angular', value: 'angular' },
        { label: 'Spring Boot', value: 'springboot' },
        { label: 'Maven', value: 'maven' },
        { label: 'Gradle', value: 'gradle' },
        { label: 'Go', value: 'go' },
        { label: 'Rust', value: 'rust' },
        { label: 'PHP', value: 'php' },
        { label: '.NET/C#', value: 'dotnet' },
        { label: 'Ruby', value: 'ruby' },
        { label: 'Swift/iOS', value: 'swift' },
        { label: 'Android', value: 'android' },
        { label: 'Flutter', value: 'flutter' },
        { label: 'Django', value: 'django' }
      ],
      commonItems: [
        { label: 'IDE 配置文件', value: 'ide' },
        { label: '操作系统文件', value: 'os' },
        { label: '日志文件', value: 'logs' },
        { label: '临时文件', value: 'temp' },
        { label: '环境配置文件', value: 'env' },
        { label: '数据库文件', value: 'database' }
      ],
      templates: {
        java: `# Java
*.class
*.jar
*.war
*.ear
*.nar
hs_err_pid*
replay_pid*`,
        python: `# Python
__pycache__/
*.py[cod]
*$py.class
*.so
.Python
build/
develop-eggs/
dist/
downloads/
eggs/
.eggs/
lib/
lib64/
parts/
sdist/
var/
wheels/
*.egg-info/
.installed.cfg
*.egg`,
        node: `# Node
node_modules/
npm-debug.log*
yarn-debug.log*
yarn-error.log*
.npm
.yarn-integrity`,
        vue: `# Vue
dist/
dist-ssr/
*.local`,
        react: `# React
build/
.DS_Store`,
        angular: `# Angular
dist/
.angular/cache/`,
        springboot: `# Spring Boot
target/
!.mvn/wrapper/maven-wrapper.jar`,
        maven: `# Maven
target/
pom.xml.tag
pom.xml.releaseBackup
pom.xml.versionsBackup
pom.xml.next
release.properties
dependency-reduced-pom.xml
buildNumber.properties
.mvn/timing.properties`,
        gradle: `# Gradle
.gradle/
build/
!gradle/wrapper/gradle-wrapper.jar`,
        go: `# Go
*.exe
*.exe~
*.dll
*.so
*.dylib
*.test
*.out
go.work`,
        rust: `# Rust
target/
Cargo.lock
**/*.rs.bk`,
        php: `# PHP
vendor/
composer.lock
.phpunit.result.cache`,
        dotnet: `# .NET
bin/
obj/
*.suo
*.user
*.userosscache
*.sln.docstates`,
        ruby: `# Ruby
*.gem
*.rbc
.bundle/
.config/
coverage/
InstalledFiles
lib/bundler/man/
pkg/
rdoc/
spec/reports/
test/tmp/
test/version_tmp/
tmp/`,
        swift: `# Swift/iOS
*.xcodeproj/*
!*.xcodeproj/project.pbxproj
!*.xcodeproj/xcshareddata/
!*.xcworkspace/contents.xcworkspacedata
*.swiftdoc
*.swiftsourceinfo
DerivedData/
*.hmap
*.ipa
*.dSYM.zip
*.dSYM`,
        android: `# Android
*.iml
.gradle
/local.properties
/.idea/
.DS_Store
/build
/captures
.externalNativeBuild
.cxx
local.properties`,
        flutter: `# Flutter
.dart_tool/
.flutter-plugins
.flutter-plugins-dependencies
.packages
.pub-cache/
.pub/
build/`,
        django: `# Django
*.log
*.pot
*.pyc
__pycache__/
local_settings.py
db.sqlite3
db.sqlite3-journal
media/`
      },
      commonTemplates: {
        ide: `# IDE
.idea/
*.iml
*.ipr
*.iws
.vscode/
*.swp
*.swo
*~
.project
.classpath
.settings/
*.sublime-workspace`,
        os: `# OS
.DS_Store
.DS_Store?
._*
.Spotlight-V100
.Trashes
ehthumbs.db
Thumbs.db
Desktop.ini`,
        logs: `# Logs
logs/
*.log
npm-debug.log*
yarn-debug.log*
yarn-error.log*`,
        temp: `# Temp
*.tmp
*.temp
*.bak
*.swp
*.swo
*~`,
        env: `# Environment
.env
.env.local
.env.*.local
*.env`,
        database: `# Database
*.sql
*.sqlite
*.sqlite3
*.db
*.mdb`
      }
    }
  },
  methods: {
    generate() {
      let content = '# Created by IT Tools .gitignore Generator\n'
      content += '# ' + new Date().toLocaleString() + '\n\n'

      if (this.selectedTypes.length > 0) {
        content += '# ===== Project Types =====\n\n'
        this.selectedTypes.forEach(type => {
          if (this.templates[type]) {
            content += this.templates[type] + '\n\n'
          }
        })
      }

      if (this.selectedCommon.length > 0) {
        content += '# ===== Common Items =====\n\n'
        this.selectedCommon.forEach(item => {
          if (this.commonTemplates[item]) {
            content += this.commonTemplates[item] + '\n\n'
          }
        })
      }

      if (this.customRules.trim()) {
        content += '# ===== Custom Rules =====\n\n'
        content += this.customRules.trim() + '\n'
      }

      this.result = content.trim()
      this.$message.success('生成成功')
    },
    copyResult() {
      if (!this.result) {
        this.$message.warning('请先生成内容')
        return
      }
      navigator.clipboard.writeText(this.result).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    download() {
      if (!this.result) {
        this.$message.warning('请先生成内容')
        return
      }
      const blob = new Blob([this.result], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = '.gitignore'
      link.click()
      URL.revokeObjectURL(url)
    },
    clearAll() {
      this.selectedTypes = []
      this.selectedCommon = []
      this.customRules = ''
      this.result = ''
    }
  }
}
</script>

<style scoped>
.gitignore-tool {
  padding: 20px;
}

.result-card :deep(.el-card__body) {
  padding: 10px;
}
</style>
