<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Java 代码格式化</span>
        <el-button size="small" @click="clear">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <div class="input-section">
            <div class="section-header">
              <span>Java 代码</span>
              <el-tag size="mini" type="info">输入或粘贴 Java 代码，点击按钮格式化</el-tag>
            </div>
            <el-input
              v-model="javaCode"
              type="textarea"
              :rows="15"
              placeholder="输入 Java 代码，如: public class Main { public static void main(String[] args) { } }"
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px">
        <el-col :span="24" class="action-row">
          <el-radio-group v-model="indent" size="small">
            <el-radio-button :label="2">2空格</el-radio-button>
            <el-radio-button :label="4">4空格</el-radio-button>
            <el-radio-button :label="1">Tab</el-radio-button>
          </el-radio-group>
          
          <div class="action-buttons">
            <el-button type="primary" @click="format">格式化</el-button>
            <el-button type="warning" @click="compress">压缩</el-button>
            <el-button @click="copy">复制</el-button>
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px" v-if="stats">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">代码统计</div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="行数">{{ stats.lines }}</el-descriptions-item>
              <el-descriptions-item label="字符数">{{ stats.chars }}</el-descriptions-item>
              <el-descriptions-item label="类数">{{ stats.classes }}</el-descriptions-item>
              <el-descriptions-item label="方法数">{{ stats.methods }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JavaFormatTool',
  data() {
    return {
      javaCode: '',
      indent: 4,
      stats: null
    }
  },
  methods: {
    format() {
      if (!this.javaCode.trim()) {
        this.$message.warning('请输入 Java 代码')
        return
      }
      
      try {
        this.javaCode = this.formatJava(this.javaCode)
        this.updateStats()
        this.$message.success('格式化成功')
      } catch (e) {
        this.$message.error('格式化失败: ' + e.message)
      }
    },
    formatJava(code) {
      const PADDING = this.indent === 1 ? '\t' : ' '.repeat(this.indent)
      
      code = code.replace(/\s+/g, ' ')
      
      code = code.replace(/\s*([{};])\s*/g, '$1\n')
      code = code.replace(/\s*\(\s*/g, '(')
      code = code.replace(/\s*\)\s*/g, ')')
      code = code.replace(/\s*,\s*/g, ', ')
      
      const keywords = ['public', 'private', 'protected', 'static', 'final', 'class', 'interface', 'enum', 'void', 'int', 'String', 'boolean', 'return', 'if', 'else', 'for', 'while', 'do', 'switch', 'case', 'break', 'continue', 'try', 'catch', 'finally', 'throw', 'throws', 'new', 'this', 'super', 'import', 'package', 'extends', 'implements']
      
      keywords.forEach(kw => {
        const regex = new RegExp('\\b' + kw + '\\b', 'g')
        code = code.replace(regex, kw)
      })
      
      let result = []
      let level = 0
      let lines = code.split('\n')
      
      lines.forEach(line => {
        line = line.trim()
        if (!line) return
        
        if (line.startsWith('}')) {
          level = Math.max(0, level - 1)
        }
        
        result.push(PADDING.repeat(level) + line)
        
        const openBraces = (line.match(/{/g) || []).length
        const closeBraces = (line.match(/}/g) || []).length
        level += openBraces - closeBraces
        level = Math.max(0, level)
      })
      
      return result.join('\n')
    },
    compress() {
      if (!this.javaCode.trim()) {
        this.$message.warning('请输入 Java 代码')
        return
      }
      
      this.javaCode = this.javaCode
        .replace(/\n/g, ' ')
        .replace(/\s{2,}/g, ' ')
        .replace(/\s*([{}();,])\s*/g, '$1')
        .replace(/\s+/g, ' ')
        .trim()
      this.updateStats()
      this.$message.success('压缩成功')
    },
    updateStats() {
      const classMatches = this.javaCode.match(/\bclass\s+\w+/g) || []
      const methodMatches = this.javaCode.match(/\b(public|private|protected|static)\s+\w+\s+\w+\s*\(/g) || []
      
      this.stats = {
        lines: this.javaCode.split('\n').length,
        chars: this.javaCode.length,
        classes: classMatches.length,
        methods: methodMatches.length
      }
    },
    copy() {
      if (!this.javaCode) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.javaCode).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      this.javaCode = ''
      this.stats = null
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;
    }
  }

  .action-row {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .action-buttons {
      display: flex;
      gap: 10px;
    }
  }
}
</style>
