<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>JWT Token 解析</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>
      
      <el-row>
        <el-col :span="24">
          <div class="jwt-input-section">
            <el-input
              v-model="jwtToken"
              type="textarea"
              :rows="4"
              placeholder="请输入 JWT Token (格式: header.payload.signature)"
            />
            <el-button type="primary" style="margin-top: 10px" @click="parseJwt">解析</el-button>
          </div>
        </el-col>
      </el-row>

      <el-row v-if="parsed" :gutter="20" style="margin-top: 20px">
        <el-col :span="8">
          <el-card class="jwt-part">
            <div slot="header">
              <span>Header (头部)</span>
              <el-button type="text" size="mini" @click="copy(headerJson)">复制</el-button>
            </div>
            <pre class="json-content">{{ headerJson }}</pre>
          </el-card>
        </el-col>
        
        <el-col :span="8">
          <el-card class="jwt-part">
            <div slot="header">
              <span>Payload (载荷)</span>
              <el-button type="text" size="mini" @click="copy(payloadJson)">复制</el-button>
            </div>
            <pre class="json-content">{{ payloadJson }}</pre>
          </el-card>
        </el-col>
        
        <el-col :span="8">
          <el-card class="jwt-part">
            <div slot="header">
              <span>Signature (签名)</span>
              <el-button type="text" size="mini" @click="copy(signature)">复制</el-button>
            </div>
            <pre class="signature-content">{{ signature }}</pre>
          </el-card>
        </el-col>
      </el-row>

      <el-row v-if="parsed && payload" style="margin-top: 20px">
        <el-col :span="24">
          <el-card>
            <div slot="header">
              <span>Token 信息</span>
            </div>
            <el-descriptions :column="2" border>
              <el-descriptions-item label="签发时间 (iat)">{{ formatTime(payload.iat) }}</el-descriptions-item>
              <el-descriptions-item label="过期时间 (exp)">{{ formatTime(payload.exp) }}</el-descriptions-item>
              <el-descriptions-item label="生效时间 (nbf)">{{ formatTime(payload.nbf) }}</el-descriptions-item>
              <el-descriptions-item label="签发者 (iss)">{{ payload.iss || '-' }}</el-descriptions-item>
              <el-descriptions-item label="受众 (aud)">{{ payload.aud || '-' }}</el-descriptions-item>
              <el-descriptions-item label="主题 (sub)">{{ payload.sub || '-' }}</el-descriptions-item>
              <el-descriptions-item label="JWT ID (jti)">{{ payload.jti || '-' }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JwtTool',
  data() {
    return {
      jwtToken: '',
      parsed: false,
      header: null,
      payload: null,
      signature: ''
    }
  },
  computed: {
    headerJson() {
      return this.header ? JSON.stringify(this.header, null, 2) : ''
    },
    payloadJson() {
      return this.payload ? JSON.stringify(this.payload, null, 2) : ''
    }
  },
  methods: {
    parseJwt() {
      if (!this.jwtToken) {
        this.$message.warning('请输入 JWT Token')
        return
      }
      
      const parts = this.jwtToken.split('.')
      if (parts.length !== 3) {
        this.$message.error('无效的 JWT Token 格式')
        return
      }

      try {
        this.header = this.base64UrlDecode(parts[0])
        this.payload = this.base64UrlDecode(parts[1])
        this.signature = parts[2]
        this.parsed = true
      } catch (e) {
        this.$message.error('解析失败: ' + e.message)
        this.parsed = false
      }
    },
    base64UrlDecode(str) {
      // 将 Base64Url 转换为 Base64
      let base64 = str.replace(/-/g, '+').replace(/_/g, '/')
      // 补齐 padding
      while (base64.length % 4) {
        base64 += '='
      }
      const json = atob(base64)
      return JSON.parse(json)
    },
    formatTime(timestamp) {
      if (!timestamp) return '-'
      const date = new Date(timestamp * 1000)
      return date.toLocaleString()
    },
    clearAll() {
      this.jwtToken = ''
      this.parsed = false
      this.header = null
      this.payload = null
      this.signature = ''
    },
    copy(text) {
      if (!text) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .jwt-input-section {
    .el-textarea {
      font-family: monospace;
    }
  }

  .jwt-part {
    .json-content, .signature-content {
      margin: 0;
      padding: 10px;
      background: #f5f7fa;
      border-radius: 4px;
      font-family: monospace;
      font-size: 12px;
      overflow-x: auto;
      white-space: pre-wrap;
      word-break: break-all;
      max-height: 300px;
      overflow-y: auto;
    }

    .signature-content {
      color: #909399;
    }
  }
}
</style>
