<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>正则表达式测试</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <el-form label-width="100px">
            <el-form-item label="正则表达式">
              <el-input
                v-model="pattern"
                placeholder="输入正则表达式（不需要斜杠包裹）"
                class="regex-input"
              >
                <template slot="prepend">/</template>
                <template slot="append">
                  <el-select v-model="flags" multiple collapse-tags style="width: 120px">
                    <el-option label="g (全局)" value="g" />
                    <el-option label="i (忽略大小写)" value="i" />
                    <el-option label="m (多行)" value="m" />
                    <el-option label="s (单行)" value="s" />
                  </el-select>
                  /
                </template>
              </el-input>
            </el-form-item>
            
            <el-form-item label="测试文本">
              <el-input
                v-model="testText"
                type="textarea"
                :rows="8"
                placeholder="输入要测试的文本"
              />
            </el-form-item>
            
            <el-form-item>
              <el-button type="primary" @click="testRegex">测试匹配</el-button>
            </el-form-item>
          </el-form>
        </el-col>
      </el-row>

      <el-row v-if="matches.length > 0 || error" style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>匹配结果</span>
              <el-tag v-if="matches.length > 0" type="success" style="margin-left: 10px">
                找到 {{ matches.length }} 个匹配
              </el-tag>
            </div>
            
            <div v-if="error" class="error-msg">
              <i class="el-icon-error"></i> {{ error }}
            </div>
            
            <el-table v-else :data="matches" border size="small">
              <el-table-column type="index" width="60" align="center" label="序号" />
              <el-table-column prop="match" label="匹配内容" />
              <el-table-column prop="index" label="位置" width="100" />
              <el-table-column prop="groups" label="捕获组">
                <template slot-scope="scope">
                  <span v-if="Object.keys(scope.row.groups).length === 0">-</span>
                  <el-tag
                    v-for="(value, key) in scope.row.groups"
                    :key="key"
                    size="mini"
                    style="margin-right: 5px"
                  >
                    {{ key }}: {{ value }}
                  </el-tag>
                </template>
              </el-table-column>
            </el-table>
          </el-card>
        </el-col>
      </el-row>

      <el-divider>常用正则表达式</el-divider>

      <el-row>
        <el-col :span="24">
          <el-table :data="commonPatterns" border size="small">
            <el-table-column prop="name" label="名称" width="150" />
            <el-table-column prop="pattern" label="正则表达式">
              <template slot-scope="scope">
                <code>{{ scope.row.pattern }}</code>
                <el-button
                  type="text"
                  size="mini"
                  style="float: right"
                  @click="usePattern(scope.row.pattern)"
                >使用</el-button>
              </template>
            </el-table-column>
            <el-table-column prop="desc" label="说明" />
          </el-table>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'RegexTool',
  data() {
    return {
      pattern: '',
      flags: ['g'],
      testText: '',
      matches: [],
      error: '',
      commonPatterns: [
        { name: '邮箱', pattern: '^[\\w-]+(\\.[\\w-]+)*@[\\w-]+(\\.[\\w-]+)+$', desc: '匹配电子邮件地址' },
        { name: '手机号', pattern: '^1[3-9]\\d{9}$', desc: '匹配中国大陆手机号' },
        { name: 'URL', pattern: '^https?://[\\w-]+(\\.[\\w-]+)+[\\w-.,@?^=%&:/~+#]*$', desc: '匹配 HTTP/HTTPS URL' },
        { name: 'IP 地址', pattern: '^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$', desc: '匹配 IPv4 地址' },
        { name: '身份证号', pattern: '^[1-9]\\d{5}(?:18|19|20)\\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\\d|3[01])\\d{3}[\\dXx]$', desc: '匹配中国大陆身份证号' },
        { name: '中文字符', pattern: '[\\u4e00-\\u9fa5]', desc: '匹配中文字符' },
        { name: '数字', pattern: '^\\d+$', desc: '匹配纯数字' },
        { name: '字母数字', pattern: '^[a-zA-Z0-9]+$', desc: '匹配字母和数字' }
      ]
    }
  },
  methods: {
    testRegex() {
      if (!this.pattern) {
        this.$message.warning('请输入正则表达式')
        return
      }
      
      this.matches = []
      this.error = ''
      
      try {
        const regex = new RegExp(this.pattern, this.flags.join(''))
        
        if (this.flags.includes('g')) {
          let match
          while ((match = regex.exec(this.testText)) !== null) {
            this.matches.push({
              match: match[0],
              index: match.index,
              groups: match.groups || {}
            })
            if (match.index === regex.lastIndex) {
              regex.lastIndex++
            }
          }
        } else {
          const match = regex.exec(this.testText)
          if (match) {
            this.matches.push({
              match: match[0],
              index: match.index,
              groups: match.groups || {}
            })
          }
        }
        
        if (this.matches.length === 0) {
          this.$message.info('未找到匹配')
        }
      } catch (e) {
        this.error = '正则表达式错误: ' + e.message
      }
    },
    usePattern(pattern) {
      this.pattern = pattern
    },
    clearAll() {
      this.pattern = ''
      this.testText = ''
      this.matches = []
      this.error = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .regex-input {
    .el-select {
      width: 120px;
    }
  }

  .error-msg {
    color: #f56c6c;
    padding: 20px;
    text-align: center;
  }

  code {
    background: #f5f7fa;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: monospace;
    font-size: 12px;
  }
}
</style>
