<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>CSV 格式化</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>CSV 输入</span>
              <el-button type="text" size="mini" @click="loadExample">加载示例</el-button>
            </div>
            <el-input
              v-model="csvInput"
              type="textarea"
              :rows="15"
              placeholder="输入 CSV 数据..."
            />
            <el-form :model="options" label-width="100px" size="small" style="margin-top: 10px">
              <el-form-item label="分隔符">
                <el-select v-model="options.delimiter">
                  <el-option label="逗号 (,)" value="," />
                  <el-option label="分号 (;)" value=";" />
                  <el-option label="制表符 (TAB)" value="\t" />
                  <el-option label="竖线 (|)" value="|" />
                </el-select>
              </el-form-item>
              <el-form-item label="引号">
                <el-select v-model="options.quote">
                  <el-option label="双引号 (&quot;)" value='"' />
                  <el-option label="单引号 (')" value="'" />
                  <el-option label="无" value="" />
                </el-select>
              </el-form-item>
              <el-form-item label="包含标题">
                <el-switch v-model="options.hasHeader" />
              </el-form-item>
            </el-form>
            <el-button type="primary" style="margin-top: 10px" @click="parse">
              解析
            </el-button>
          </div>
        </el-col>
        
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>表格预览</span>
              <div>
                <el-button type="text" size="mini" @click="copyTable">复制</el-button>
                <el-button type="text" size="mini" @click="downloadTable">下载</el-button>
              </div>
            </div>
            <el-table
              :data="tableData"
              border
              stripe
              max-height="400"
              style="width: 100%"
              v-loading="loading"
            >
              <el-table-column
                v-for="column in columns"
                :key="column"
                :prop="column"
                :label="column"
                min-width="120"
              />
            </el-table>
          </div>
        </el-col>
      </el-row>
      
      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>统计信息</span>
            </div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="行数">{{ stats.rows }}</el-descriptions-item>
              <el-descriptions-item label="列数">{{ stats.columns }}</el-descriptions-item>
              <el-descriptions-item label="总单元格">{{ stats.cells }}</el-descriptions-item>
              <el-descriptions-item label="分隔符">{{ options.delimiter === '\t' ? 'TAB' : options.delimiter }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CsvTool',
  data() {
    return {
      csvInput: '',
      tableData: [],
      columns: [],
      loading: false,
      options: {
        delimiter: ',',
        quote: '"',
        hasHeader: true
      },
      stats: {
        rows: 0,
        columns: 0,
        cells: 0
      }
    }
  },
  methods: {
    parse() {
      if (!this.csvInput.trim()) {
        this.$message.warning('请输入 CSV 数据')
        return
      }
      
      this.loading = true
      
      try {
        const lines = this.csvInput.split('\n').filter(line => line.trim())
        
        if (lines.length === 0) {
          this.$message.warning('CSV 数据为空')
          this.loading = false
          return
        }
        
        const delimiter = this.options.delimiter
        const quote = this.options.quote
        
        let headers = []
        let data = []
        
        if (this.options.hasHeader) {
          headers = this.parseLine(lines[0], delimiter, quote)
          data = lines.slice(1).map(line => this.parseLine(line, delimiter, quote))
        } else {
          const firstLine = this.parseLine(lines[0], delimiter, quote)
          headers = firstLine.map((_, index) => `列${index + 1}`)
          data = lines.map(line => this.parseLine(line, delimiter, quote))
        }
        
        this.columns = headers
        this.tableData = data.map(row => {
          const obj = {}
          headers.forEach((header, index) => {
            obj[header] = row[index] || ''
          })
          return obj
        })
        
        this.stats = {
          rows: data.length,
          columns: headers.length,
          cells: data.length * headers.length
        }
        
        this.$message.success('解析成功')
      } catch (error) {
        this.$message.error('解析失败: ' + error.message)
      } finally {
        this.loading = false
      }
    },
    parseLine(line, delimiter, quote) {
      const result = []
      let current = ''
      let inQuotes = false
      
      for (let i = 0; i < line.length; i++) {
        const char = line[i]
        
        if (char === quote) {
          inQuotes = !inQuotes
        } else if (char === delimiter && !inQuotes) {
          result.push(current)
          current = ''
        } else {
          current += char
        }
      }
      
      result.push(current)
      return result
    },
    copyTable() {
      if (this.tableData.length === 0) {
        this.$message.warning('请先解析 CSV 数据')
        return
      }
      
      const headers = this.columns.join(this.options.delimiter)
      const rows = this.tableData.map(row => 
        this.columns.map(col => row[col] || '').join(this.options.delimiter)
      ).join('\n')
      
      const text = headers + '\n' + rows
      
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadTable() {
      if (this.tableData.length === 0) {
        this.$message.warning('请先解析 CSV 数据')
        return
      }
      
      const headers = this.columns.join(this.options.delimiter)
      const rows = this.tableData.map(row => 
        this.columns.map(col => row[col] || '').join(this.options.delimiter)
      ).join('\n')
      
      const text = headers + '\n' + rows
      const blob = new Blob([text], { type: 'text/csv;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'data.csv'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample() {
      this.csvInput = `姓名,年龄,城市,职业
张三,25,北京,工程师
李四,30,上海,设计师
王五,28,广州,产品经理
赵六,32,深圳,程序员`
      this.parse()
    },
    clearAll() {
      this.csvInput = ''
      this.tableData = []
      this.columns = []
      this.stats = {
        rows: 0,
        columns: 0,
        cells: 0
      }
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }
}
</style>
