<template>
  <div class="world-clock-tool">
    <el-card>
      <div slot="header">
        <span>世界时钟</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="addClock">添加时钟</el-button>
      </div>

      <div class="current-time-section">
        <div class="local-time">
          <div class="time-display">{{ localTime }}</div>
          <div class="date-display">{{ localDate }}</div>
          <div class="timezone-display">{{ localTimezone }}</div>
        </div>
      </div>

      <el-divider>世界主要城市时间</el-divider>

      <el-row :gutter="20">
        <el-col :span="8" v-for="(clock, index) in clocks" :key="index">
          <el-card shadow="hover" class="clock-card">
            <div slot="header" class="clock-header">
              <span>{{ clock.name }}</span>
              <el-button type="text" size="small" @click="removeClock(index)">
                <i class="el-icon-close"></i>
              </el-button>
            </div>
            <div class="clock-content">
              <div class="clock-time">{{ clock.time }}</div>
              <div class="clock-date">{{ clock.date }}</div>
              <div class="clock-offset">{{ clock.offset }}</div>
            </div>
          </el-card>
        </el-col>
      </el-row>

      <el-dialog title="添加时钟" :visible.sync="dialogVisible" width="400px">
        <el-form :model="newClock" label-width="100px">
          <el-form-item label="城市名称">
            <el-input v-model="newClock.name" placeholder="输入城市名称" />
          </el-form-item>
          <el-form-item label="时区">
            <el-select v-model="newClock.timezone" style="width: 100%" filterable>
              <el-option-group label="亚洲">
                <el-option label="北京/上海 (UTC+8)" value="Asia/Shanghai" />
                <el-option label="东京 (UTC+9)" value="Asia/Tokyo" />
                <el-option label="首尔 (UTC+9)" value="Asia/Seoul" />
                <el-option label="新加坡 (UTC+8)" value="Asia/Singapore" />
                <el-option label="孟买 (UTC+5:30)" value="Asia/Kolkata" />
                <el-option label="迪拜 (UTC+4)" value="Asia/Dubai" />
                <el-option label="曼谷 (UTC+7)" value="Asia/Bangkok" />
              </el-option-group>
              <el-option-group label="欧洲">
                <el-option label="伦敦 (UTC+0/+1)" value="Europe/London" />
                <el-option label="巴黎 (UTC+1/+2)" value="Europe/Paris" />
                <el-option label="柏林 (UTC+1/+2)" value="Europe/Berlin" />
                <el-option label="莫斯科 (UTC+3)" value="Europe/Moscow" />
                <el-option label="罗马 (UTC+1/+2)" value="Europe/Rome" />
              </el-option-group>
              <el-option-group label="美洲">
                <el-option label="纽约 (UTC-5/-4)" value="America/New_York" />
                <el-option label="洛杉矶 (UTC-8/-7)" value="America/Los_Angeles" />
                <el-option label="芝加哥 (UTC-6/-5)" value="America/Chicago" />
                <el-option label="多伦多 (UTC-5/-4)" value="America/Toronto" />
                <el-option label="温哥华 (UTC-8/-7)" value="America/Vancouver" />
                <el-option label="圣保罗 (UTC-3)" value="America/Sao_Paulo" />
              </el-option-group>
              <el-option-group label="大洋洲">
                <el-option label="悉尼 (UTC+10/+11)" value="Australia/Sydney" />
                <el-option label="墨尔本 (UTC+10/+11)" value="Australia/Melbourne" />
                <el-option label="奥克兰 (UTC+12/+13)" value="Pacific/Auckland" />
              </el-option-group>
            </el-select>
          </el-form-item>
        </el-form>
        <div slot="footer">
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="confirmAddClock">确定</el-button>
        </div>
      </el-dialog>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'WorldClockTool',
  data() {
    return {
      localTime: '',
      localDate: '',
      localTimezone: '',
      clocks: [
        { name: '纽约', timezone: 'America/New_York', time: '', date: '', offset: '' },
        { name: '伦敦', timezone: 'Europe/London', time: '', date: '', offset: '' },
        { name: '东京', timezone: 'Asia/Tokyo', time: '', date: '', offset: '' },
        { name: '悉尼', timezone: 'Australia/Sydney', time: '', date: '', offset: '' },
        { name: '巴黎', timezone: 'Europe/Paris', time: '', date: '', offset: '' },
        { name: '迪拜', timezone: 'Asia/Dubai', time: '', date: '', offset: '' }
      ],
      dialogVisible: false,
      newClock: {
        name: '',
        timezone: ''
      },
      timer: null
    }
  },
  mounted() {
    this.updateTime()
    this.timer = setInterval(this.updateTime, 1000)
  },
  beforeDestroy() {
    clearInterval(this.timer)
  },
  methods: {
    updateTime() {
      const now = new Date()
      
      // Local time
      this.localTime = now.toLocaleTimeString('zh-CN', { hour12: false })
      this.localDate = now.toLocaleDateString('zh-CN', { 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric',
        weekday: 'long'
      })
      this.localTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone
      
      // Update clocks
      this.clocks.forEach(clock => {
        try {
          const options = {
            timeZone: clock.timezone,
            hour12: false,
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
          }
          clock.time = now.toLocaleTimeString('zh-CN', options)
          
          const dateOptions = {
            timeZone: clock.timezone,
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            weekday: 'short'
          }
          clock.date = now.toLocaleDateString('zh-CN', dateOptions)
          
          // Calculate offset
          const localOffset = -now.getTimezoneOffset()
          const targetDate = new Date(now.toLocaleString('en-US', { timeZone: clock.timezone }))
          const targetOffset = (targetDate - now) / 60000 + localOffset
          const offsetHours = Math.round(targetOffset / 60)
          clock.offset = offsetHours >= 0 ? `+${offsetHours}小时` : `${offsetHours}小时`
        } catch (e) {
          clock.time = '--:--:--'
          clock.date = '---'
          clock.offset = ''
        }
      })
    },
    addClock() {
      this.newClock = { name: '', timezone: '' }
      this.dialogVisible = true
    },
    confirmAddClock() {
      if (!this.newClock.name || !this.newClock.timezone) {
        this.$message.warning('请填写完整信息')
        return
      }
      this.clocks.push({
        name: this.newClock.name,
        timezone: this.newClock.timezone,
        time: '',
        date: '',
        offset: ''
      })
      this.dialogVisible = false
      this.updateTime()
    },
    removeClock(index) {
      this.clocks.splice(index, 1)
    }
  }
}
</script>

<style scoped>
.world-clock-tool {
  padding: 20px;
}

.current-time-section {
  text-align: center;
  padding: 30px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  border-radius: 8px;
  color: white;
  margin-bottom: 20px;
}

.local-time .time-display {
  font-size: 48px;
  font-weight: bold;
  margin-bottom: 10px;
}

.local-time .date-display {
  font-size: 20px;
  margin-bottom: 5px;
}

.local-time .timezone-display {
  font-size: 14px;
  opacity: 0.8;
}

.clock-card {
  margin-bottom: 20px;
}

.clock-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.clock-content {
  text-align: center;
}

.clock-time {
  font-size: 28px;
  font-weight: bold;
  color: #409eff;
  margin-bottom: 5px;
}

.clock-date {
  font-size: 14px;
  color: #606266;
  margin-bottom: 5px;
}

.clock-offset {
  font-size: 12px;
  color: #909399;
}
</style>
