<template>
  <div class="fake-data-tool">
    <el-card>
      <div slot="header">
        <span>假数据生成器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-form label-width="100px">
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="生成数量">
              <el-input-number v-model="form.count" :min="1" :max="10000" style="width: 100%" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="输出格式">
              <el-select v-model="form.outputFormat" style="width: 100%">
                <el-option label="JSON" value="json" />
                <el-option label="CSV" value="csv" />
                <el-option label="SQL INSERT" value="sql" />
                <el-option label="Excel (复制粘贴)" value="excel" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="表名" v-if="form.outputFormat === 'sql'">
              <el-input v-model="form.tableName" placeholder="table_name" />
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <el-divider>字段配置</el-divider>

      <div class="field-config">
        <div class="field-header">
          <span>已添加字段 ({{ form.fields.length }})</span>
          <el-button type="primary" size="small" @click="addField">添加字段</el-button>
        </div>

        <el-table :data="form.fields" border style="width: 100%" v-if="form.fields.length > 0">
          <el-table-column prop="name" label="字段名" width="150">
            <template slot-scope="scope">
              <el-input v-model="scope.row.name" placeholder="字段名" size="small" />
            </template>
          </el-table-column>
          <el-table-column prop="type" label="数据类型" width="180">
            <template slot-scope="scope">
              <el-select v-model="scope.row.type" placeholder="选择类型" size="small" style="width: 100%">
                <el-option-group label="个人信息">
                  <el-option label="姓名" value="name" />
                  <el-option label="英文名" value="firstName" />
                  <el-option label="英文姓" value="lastName" />
                  <el-option label="中文名" value="chineseName" />
                  <el-option label="性别" value="gender" />
                  <el-option label="年龄" value="age" />
                  <el-option label="生日" value="birthday" />
                  <el-option label="邮箱" value="email" />
                  <el-option label="手机号" value="phone" />
                  <el-option label="身份证号" value="idCard" />
                  <el-option label="地址" value="address" />
                  <el-option label="省份" value="province" />
                  <el-option label="城市" value="city" />
                  <el-option label="邮编" value="zipcode" />
                </el-option-group>
                <el-option-group label="网络信息">
                  <el-option label="IP地址(IPv4)" value="ipv4" />
                  <el-option label="IP地址(IPv6)" value="ipv6" />
                  <el-option label="MAC地址" value="mac" />
                  <el-option label="URL" value="url" />
                  <el-option label="域名" value="domain" />
                  <el-option label="UUID" value="uuid" />
                  <el-option label="用户名" value="username" />
                  <el-option label="密码" value="password" />
                </el-option-group>
                <el-option-group label="文本数据">
                  <el-option label="随机字符串" value="string" />
                  <el-option label="随机数字" value="number" />
                  <el-option label="小数" value="decimal" />
                  <el-option label="布尔值" value="boolean" />
                  <el-option label="Lorem文本" value="lorem" />
                  <el-option label="中文句子" value="chineseText" />
                  <el-option label="颜色值(HEX)" value="colorHex" />
                  <el-option label="颜色值(RGB)" value="colorRgb" />
                </el-option-group>
                <el-option-group label="时间日期">
                  <el-option label="日期" value="date" />
                  <el-option label="时间" value="time" />
                  <el-option label="日期时间" value="datetime" />
                  <el-option label="时间戳" value="timestamp" />
                  <el-option label="年份" value="year" />
                  <el-option label="月份" value="month" />
                </el-option-group>
                <el-option-group label="商业数据">
                  <el-option label="银行卡号" value="bankCard" />
                  <el-option label="公司名称" value="company" />
                  <el-option label="职位" value="job" />
                  <el-option label="行业" value="industry" />
                  <el-option label="价格" value="price" />
                  <el-option label="产品名称" value="productName" />
                  <el-option label="订单号" value="orderId" />
                  <el-option label="ISBN" value="isbn" />
                </el-option-group>
                <el-option-group label="其他">
                  <el-option label="枚举值" value="enum" />
                  <el-option label="自增ID" value="autoIncrement" />
                  <el-option label="固定值" value="fixed" />
                  <el-option label="空值" value="null" />
                </el-option-group>
              </el-select>
            </template>
          </el-table-column>
          <el-table-column prop="config" label="配置" min-width="200">
            <template slot-scope="scope">
              <div v-if="scope.row.type === 'string'" class="config-row">
                <el-input-number v-model="scope.row.length" :min="1" :max="1000" size="small" placeholder="长度" style="width: 80px" />
                <el-select v-model="scope.row.charType" size="small" style="width: 100px; margin-left: 5px">
                  <el-option label="混合" value="mixed" />
                  <el-option label="数字" value="number" />
                  <el-option label="字母" value="letter" />
                  <el-option label="小写" value="lower" />
                  <el-option label="大写" value="upper" />
                </el-select>
              </div>
              <div v-else-if="scope.row.type === 'number'" class="config-row">
                <el-input-number v-model="scope.row.min" size="small" placeholder="最小" style="width: 100px" />
                <span style="margin: 0 5px">-</span>
                <el-input-number v-model="scope.row.max" size="small" placeholder="最大" style="width: 100px" />
              </div>
              <div v-else-if="scope.row.type === 'decimal'" class="config-row">
                <el-input-number v-model="scope.row.min" size="small" placeholder="最小" style="width: 80px" />
                <span style="margin: 0 5px">-</span>
                <el-input-number v-model="scope.row.max" size="small" placeholder="最大" style="width: 80px" />
                <el-input-number v-model="scope.row.decimals" :min="0" :max="10" size="small" placeholder="小数位" style="width: 70px; margin-left: 5px" />
              </div>
              <div v-else-if="scope.row.type === 'price'" class="config-row">
                <el-input-number v-model="scope.row.min" size="small" placeholder="最小" style="width: 80px" />
                <span style="margin: 0 5px">-</span>
                <el-input-number v-model="scope.row.max" size="small" placeholder="最大" style="width: 80px" />
              </div>
              <div v-else-if="scope.row.type === 'age'" class="config-row">
                <el-input-number v-model="scope.row.minAge" :min="1" :max="100" size="small" placeholder="最小" style="width: 80px" />
                <span style="margin: 0 5px">-</span>
                <el-input-number v-model="scope.row.maxAge" :min="1" :max="120" size="small" placeholder="最大" style="width: 80px" />
              </div>
              <div v-else-if="scope.row.type === 'date' || scope.row.type === 'datetime'" class="config-row">
                <el-date-picker v-model="scope.row.startDate" type="date" size="small" placeholder="开始日期" style="width: 120px" />
                <el-date-picker v-model="scope.row.endDate" type="date" size="small" placeholder="结束日期" style="width: 120px; margin-left: 5px" />
              </div>
              <div v-else-if="scope.row.type === 'enum'" class="config-row">
                <el-input v-model="scope.row.enumValues" size="small" placeholder="用逗号分隔: 男,女" />
              </div>
              <div v-else-if="scope.row.type === 'autoIncrement'" class="config-row">
                <el-input-number v-model="scope.row.start" size="small" placeholder="起始值" style="width: 100px" />
                <el-input-number v-model="scope.row.step" :min="1" size="small" placeholder="步长" style="width: 80px; margin-left: 5px" />
              </div>
              <div v-else-if="scope.row.type === 'fixed'" class="config-row">
                <el-input v-model="scope.row.fixedValue" size="small" placeholder="固定值" />
              </div>
              <div v-else-if="scope.row.type === 'password'" class="config-row">
                <el-input-number v-model="scope.row.length" :min="6" :max="32" size="small" placeholder="长度" style="width: 80px" />
              </div>
              <span v-else class="no-config">-</span>
            </template>
          </el-table-column>
          <el-table-column label="操作" width="80" align="center">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click="removeField(scope.$index)" style="color: #f56c6c">
                <i class="el-icon-delete"></i>
              </el-button>
            </template>
          </el-table-column>
        </el-table>

        <div v-else class="empty-fields">
          <p>暂无字段，请点击"添加字段"按钮添加</p>
        </div>

        <div class="quick-add">
          <span>快速添加：</span>
          <el-button size="mini" @click="addPresetFields('user')">用户信息</el-button>
          <el-button size="mini" @click="addPresetFields('contact')">联系方式</el-button>
          <el-button size="mini" @click="addPresetFields('address')">地址信息</el-button>
          <el-button size="mini" @click="addPresetFields('network')">网络信息</el-button>
          <el-button size="mini" @click="addPresetFields('product')">商品信息</el-button>
          <el-button size="mini" @click="addPresetFields('order')">订单信息</el-button>
        </div>
      </div>

      <div class="action-buttons">
        <el-button type="primary" size="large" @click="generate">生成数据</el-button>
        <el-button size="large" @click="copyResult">复制结果</el-button>
        <el-button size="large" @click="downloadResult">下载文件</el-button>
        <el-button size="large" @click="clearAll">清空全部</el-button>
      </div>

      <el-divider>生成结果</el-divider>

      <div class="result-section">
        <div class="result-info" v-if="result">
          <span>共生成 {{ form.count }} 条数据，{{ form.fields.length }} 个字段</span>
        </div>
        <el-input
          v-model="result"
          type="textarea"
          :rows="15"
          readonly
          placeholder="生成的数据将显示在这里..."
        />
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'FakeDataTool',
  data() {
    return {
      form: {
        count: 100,
        outputFormat: 'json',
        tableName: 'users',
        fields: []
      },
      result: '',
      autoIncrementCounters: {}
    }
  },
  methods: {
    addField() {
      this.form.fields.push({
        name: `field_${this.form.fields.length + 1}`,
        type: 'name',
        length: 16,
        charType: 'mixed',
        min: 0,
        max: 100,
        decimals: 2,
        minAge: 18,
        maxAge: 60,
        startDate: null,
        endDate: null,
        enumValues: '',
        start: 1,
        step: 1,
        fixedValue: ''
      })
    },
    removeField(index) {
      this.form.fields.splice(index, 1)
    },
    addPresetFields(preset) {
      const presets = {
        user: [
          { name: 'id', type: 'autoIncrement', start: 1, step: 1 },
          { name: 'name', type: 'name' },
          { name: 'gender', type: 'gender' },
          { name: 'age', type: 'age', minAge: 18, maxAge: 60 },
          { name: 'email', type: 'email' },
          { name: 'phone', type: 'phone' }
        ],
        contact: [
          { name: 'name', type: 'name' },
          { name: 'email', type: 'email' },
          { name: 'phone', type: 'phone' },
          { name: 'address', type: 'address' },
          { name: 'zipcode', type: 'zipcode' }
        ],
        address: [
          { name: 'province', type: 'province' },
          { name: 'city', type: 'city' },
          { name: 'address', type: 'address' },
          { name: 'zipcode', type: 'zipcode' }
        ],
        network: [
          { name: 'ip', type: 'ipv4' },
          { name: 'mac', type: 'mac' },
          { name: 'domain', type: 'domain' },
          { name: 'url', type: 'url' }
        ],
        product: [
          { name: 'id', type: 'autoIncrement', start: 1, step: 1 },
          { name: 'name', type: 'productName' },
          { name: 'price', type: 'price', min: 10, max: 1000 },
          { name: 'category', type: 'enum', enumValues: '电子产品,服装,食品,家居,图书' }
        ],
        order: [
          { name: 'order_id', type: 'orderId' },
          { name: 'user_name', type: 'name' },
          { name: 'product', type: 'productName' },
          { name: 'price', type: 'price', min: 100, max: 10000 },
          { name: 'create_time', type: 'datetime' }
        ]
      }
      
      const fields = presets[preset]
      if (fields) {
        fields.forEach(f => {
          this.form.fields.push({
            name: f.name,
            type: f.type,
            length: f.length || 16,
            charType: f.charType || 'mixed',
            min: f.min || 0,
            max: f.max || 100,
            decimals: f.decimals || 2,
            minAge: f.minAge || 18,
            maxAge: f.maxAge || 60,
            startDate: f.startDate || null,
            endDate: f.endDate || null,
            enumValues: f.enumValues || '',
            start: f.start || 1,
            step: f.step || 1,
            fixedValue: f.fixedValue || ''
          })
        })
      }
    },
    generate() {
      if (this.form.fields.length === 0) {
        this.$message.warning('请先添加字段')
        return
      }

      this.autoIncrementCounters = {}
      const data = []
      
      for (let i = 0; i < this.form.count; i++) {
        const row = {}
        this.form.fields.forEach(field => {
          row[field.name] = this.generateFieldValue(field)
        })
        data.push(row)
      }

      switch (this.form.outputFormat) {
        case 'json':
          this.result = JSON.stringify(data, null, 2)
          break
        case 'csv':
          const headers = this.form.fields.map(f => f.name).join(',')
          const rows = data.map(row => 
            this.form.fields.map(f => {
              const val = row[f.name]
              if (typeof val === 'string' && (val.includes(',') || val.includes('"'))) {
                return `"${val.replace(/"/g, '""')}"`
              }
              return val
            }).join(',')
          )
          this.result = [headers, ...rows].join('\n')
          break
        case 'sql':
          const sqlRows = data.map(row => {
            const columns = Object.keys(row).join(', ')
            const values = Object.values(row).map(v => {
              if (v === null) return 'NULL'
              if (typeof v === 'number') return v
              return `'${v}'`
            }).join(', ')
            return `INSERT INTO ${this.form.tableName} (${columns}) VALUES (${values});`
          })
          this.result = sqlRows.join('\n')
          break
        case 'excel':
          const excelHeaders = this.form.fields.map(f => f.name).join('\t')
          const excelRows = data.map(row => 
            this.form.fields.map(f => row[f.name]).join('\t')
          )
          this.result = [excelHeaders, ...excelRows].join('\n')
          break
      }
    },
    generateFieldValue(field) {
      const firstNames = ['张', '王', '李', '刘', '陈', '杨', '黄', '赵', '吴', '周', '徐', '孙', '马', '朱', '胡', '郭', '何', '林', '罗', '高']
      const lastNames = ['伟', '芳', '娜', '敏', '静', '丽', '强', '磊', '军', '洋', '勇', '艳', '杰', '涛', '明', '超', '秀兰', '霞', '平', '刚']
      const englishFirstNames = ['James', 'John', 'Robert', 'Michael', 'William', 'David', 'Richard', 'Joseph', 'Thomas', 'Charles', 'Mary', 'Patricia', 'Jennifer', 'Linda', 'Elizabeth', 'Susan', 'Jessica', 'Sarah', 'Karen', 'Lisa']
      const englishLastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez', 'Wilson', 'Anderson', 'Taylor', 'Thomas', 'Moore', 'Jackson', 'Martin', 'Lee', 'Thompson', 'White']
      const domains = ['gmail.com', 'qq.com', '163.com', 'outlook.com', 'hotmail.com', 'yahoo.com', 'sina.com', 'sohu.com', '126.com', 'foxmail.com']
      const streets = ['中山路', '解放路', '人民路', '建设路', '文化路', '工业路', '和平路', '光明路', '胜利路', '前进路', '幸福路', '团结路']
      const cities = ['北京市', '上海市', '广州市', '深圳市', '杭州市', '南京市', '成都市', '武汉市', '西安市', '重庆市', '苏州市', '天津市', '青岛市', '大连市', '宁波市']
      const provinces = ['北京市', '上海市', '天津市', '重庆市', '河北省', '山西省', '辽宁省', '吉林省', '黑龙江省', '江苏省', '浙江省', '安徽省', '福建省', '江西省', '山东省', '河南省', '湖北省', '湖南省', '广东省', '海南省', '四川省', '贵州省', '云南省', '陕西省', '甘肃省', '青海省', '台湾省', '内蒙古自治区', '广西壮族自治区', '西藏自治区', '宁夏回族自治区', '新疆维吾尔自治区', '香港特别行政区', '澳门特别行政区']
      const companies = ['华为', '腾讯', '阿里巴巴', '字节跳动', '百度', '京东', '美团', '滴滴', '小米', '网易', '新浪', '搜狐', '360', '联想', '中兴', '格力', '海尔', '美的', 'OPPO', 'vivo']
      const companyTypes = ['科技有限公司', '网络科技有限公司', '软件有限公司', '信息技术有限公司', '电子商务有限公司', '贸易有限公司', '实业有限公司', '投资有限公司', '集团有限公司', '控股有限公司']
      const jobs = ['软件工程师', '产品经理', 'UI设计师', '测试工程师', '运维工程师', '前端开发工程师', '后端开发工程师', '全栈工程师', '数据分析师', '项目经理', '架构师', '技术总监', '运营经理', '市场经理', '销售经理', '人事经理', '财务经理', '行政助理', '客服专员', '数据专员']
      const industries = ['互联网', '金融', '教育', '医疗', '房地产', '制造业', '零售', '物流', '传媒', '娱乐', '旅游', '餐饮', '能源', '环保', '农业']
      const products = ['iPhone', 'MacBook', 'iPad', '华为手机', '小米手机', '联想笔记本', '戴尔显示器', '机械键盘', '游戏鼠标', '蓝牙耳机', '智能手表', '平板电脑', '数码相机', '无人机', '智能音箱']
      const loremWords = ['lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing', 'elit', 'sed', 'do', 'eiusmod', 'tempor', 'incididunt', 'ut', 'labore', 'et', 'dolore', 'magna', 'aliqua', 'enim', 'ad', 'minim', 'veniam', 'quis', 'nostrud', 'exercitation', 'ullamco', 'laboris', 'nisi', 'aliquip', 'ex', 'ea', 'commodo', 'consequat']
      const chineseSentences = ['这是一段测试文本。', '欢迎使用假数据生成器。', '今天天气真不错。', '数据生成完成。', '系统运行正常。', '用户已成功注册。', '订单已确认。', '商品已发货。', '支付成功。', '感谢您的使用。']

      switch (field.type) {
        case 'name':
          return firstNames[Math.floor(Math.random() * firstNames.length)] + lastNames[Math.floor(Math.random() * lastNames.length)]
        case 'firstName':
          return englishFirstNames[Math.floor(Math.random() * englishFirstNames.length)]
        case 'lastName':
          return englishLastNames[Math.floor(Math.random() * englishLastNames.length)]
        case 'chineseName':
          return firstNames[Math.floor(Math.random() * firstNames.length)] + lastNames[Math.floor(Math.random() * lastNames.length)]
        case 'gender':
          return Math.random() > 0.5 ? '男' : '女'
        case 'age':
          return Math.floor(Math.random() * (field.maxAge - field.minAge + 1)) + field.minAge
        case 'birthday':
          const year = 1960 + Math.floor(Math.random() * 45)
          const month = String(Math.floor(Math.random() * 12) + 1).padStart(2, '0')
          const day = String(Math.floor(Math.random() * 28) + 1).padStart(2, '0')
          return `${year}-${month}-${day}`
        case 'email':
          const emailName = this.randomString(8, 'lower')
          return `${emailName}@${domains[Math.floor(Math.random() * domains.length)]}`
        case 'phone':
          const prefixes = ['138', '139', '137', '136', '135', '134', '159', '158', '157', '150', '151', '152', '188', '187', '182', '183', '186', '185', '177', '176']
          return prefixes[Math.floor(Math.random() * prefixes.length)] + this.randomNumber(8)
        case 'idCard':
          const provinceCodes = ['11', '12', '13', '14', '15', '21', '22', '23', '31', '32', '33', '34', '35', '36', '37', '41', '42', '43', '44', '45', '46', '50', '51', '52', '53', '54', '61', '62', '63', '64', '65']
          const idPrefix = provinceCodes[Math.floor(Math.random() * provinceCodes.length)]
          const idYear = 1960 + Math.floor(Math.random() * 45)
          const idMonth = String(Math.floor(Math.random() * 12) + 1).padStart(2, '0')
          const idDay = String(Math.floor(Math.random() * 28) + 1).padStart(2, '0')
          const idSuffix = this.randomNumber(3) + String(Math.floor(Math.random() * 10))
          const idBase = `${idPrefix}0000${idYear}${idMonth}${idDay}${idSuffix}`
          return idBase + this.calculateIdCardCheckCode(idBase)
        case 'address':
          return cities[Math.floor(Math.random() * cities.length)] + streets[Math.floor(Math.random() * streets.length)] + Math.floor(Math.random() * 999 + 1) + '号'
        case 'province':
          return provinces[Math.floor(Math.random() * provinces.length)]
        case 'city':
          return cities[Math.floor(Math.random() * cities.length)]
        case 'zipcode':
          return this.randomNumber(6)
        case 'ipv4':
          return `${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}`
        case 'ipv6':
          return Array(8).fill(0).map(() => Math.floor(Math.random() * 65536).toString(16)).join(':')
        case 'mac':
          return Array(6).fill(0).map(() => Math.floor(Math.random() * 256).toString(16).padStart(2, '0').toUpperCase()).join(':')
        case 'url':
          const protocols = ['https://', 'http://']
          const tlds = ['.com', '.cn', '.net', '.org', '.io', '.co', '.edu', '.gov']
          return protocols[Math.floor(Math.random() * protocols.length)] + this.randomString(10, 'lower') + tlds[Math.floor(Math.random() * tlds.length)]
        case 'domain':
          const domainTlds = ['.com', '.cn', '.net', '.org', '.io', '.co']
          return this.randomString(8, 'lower') + domainTlds[Math.floor(Math.random() * domainTlds.length)]
        case 'uuid':
          return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            const r = Math.random() * 16 | 0
            const v = c === 'x' ? r : (r & 0x3 | 0x8)
            return v.toString(16)
          })
        case 'username':
          return this.randomString(8, 'lower')
        case 'password':
          return this.randomString(field.length || 12, 'mixed')
        case 'string':
          return this.randomString(field.length || 16, field.charType || 'mixed')
        case 'number':
          return Math.floor(Math.random() * (field.max - field.min + 1)) + field.min
        case 'decimal':
          const decimalValue = Math.random() * (field.max - field.min) + field.min
          return Number(decimalValue.toFixed(field.decimals || 2))
        case 'boolean':
          return Math.random() > 0.5
        case 'lorem':
          return Array(20).fill(0).map(() => loremWords[Math.floor(Math.random() * loremWords.length)]).join(' ')
        case 'chineseText':
          return Array(5).fill(0).map(() => chineseSentences[Math.floor(Math.random() * chineseSentences.length)]).join('')
        case 'colorHex':
          return '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0')
        case 'colorRgb':
          return `rgb(${Math.floor(Math.random() * 256)}, ${Math.floor(Math.random() * 256)}, ${Math.floor(Math.random() * 256)})`
        case 'date':
          const startD = field.startDate ? new Date(field.startDate) : new Date(2020, 0, 1)
          const endD = field.endDate ? new Date(field.endDate) : new Date()
          const dateVal = new Date(startD.getTime() + Math.random() * (endD.getTime() - startD.getTime()))
          return dateVal.toISOString().split('T')[0]
        case 'time':
          const h = String(Math.floor(Math.random() * 24)).padStart(2, '0')
          const m = String(Math.floor(Math.random() * 60)).padStart(2, '0')
          const s = String(Math.floor(Math.random() * 60)).padStart(2, '0')
          return `${h}:${m}:${s}`
        case 'datetime':
          const startDT = field.startDate ? new Date(field.startDate) : new Date(2020, 0, 1)
          const endDT = field.endDate ? new Date(field.endDate) : new Date()
          const dtVal = new Date(startDT.getTime() + Math.random() * (endDT.getTime() - startDT.getTime()))
          return dtVal.toISOString().replace('T', ' ').substring(0, 19)
        case 'timestamp':
          return Math.floor(Date.now() / 1000) - Math.floor(Math.random() * 31536000)
        case 'year':
          return 2020 + Math.floor(Math.random() * 6)
        case 'month':
          return Math.floor(Math.random() * 12) + 1
        case 'bankCard':
          const bankPrefixes = ['6222', '6225', '6228', '6230', '6217', '6212', '6210', '6220', '6250', '6282']
          return bankPrefixes[Math.floor(Math.random() * bankPrefixes.length)] + this.randomNumber(12)
        case 'company':
          return companies[Math.floor(Math.random() * companies.length)] + companyTypes[Math.floor(Math.random() * companyTypes.length)]
        case 'job':
          return jobs[Math.floor(Math.random() * jobs.length)]
        case 'industry':
          return industries[Math.floor(Math.random() * industries.length)]
        case 'price':
          const priceVal = Math.random() * (field.max - field.min) + field.min
          return Number(priceVal.toFixed(2))
        case 'productName':
          return products[Math.floor(Math.random() * products.length)] + ' ' + (Math.floor(Math.random() * 9) + 1) + '代'
        case 'orderId':
          const orderPrefix = ['ORD', 'PO', 'SO', 'NO']
          return orderPrefix[Math.floor(Math.random() * orderPrefix.length)] + Date.now().toString().slice(-8) + this.randomNumber(4)
        case 'isbn':
          return '978' + this.randomNumber(10)
        case 'enum':
          if (!field.enumValues) return ''
          const enumList = field.enumValues.split(',').map(s => s.trim())
          return enumList[Math.floor(Math.random() * enumList.length)]
        case 'autoIncrement':
          const key = field.name
          if (!this.autoIncrementCounters[key]) {
            this.autoIncrementCounters[key] = field.start || 1
          }
          const current = this.autoIncrementCounters[key]
          this.autoIncrementCounters[key] += field.step || 1
          return current
        case 'fixed':
          return field.fixedValue || ''
        case 'null':
          return null
        default:
          return ''
      }
    },
    randomString(length, type) {
      let chars = ''
      switch (type) {
        case 'number':
          chars = '0123456789'
          break
        case 'letter':
          chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
          break
        case 'lower':
          chars = 'abcdefghijklmnopqrstuvwxyz'
          break
        case 'upper':
          chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
          break
        default:
          chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
      }
      return Array(length).fill(0).map(() => chars.charAt(Math.floor(Math.random() * chars.length))).join('')
    },
    randomNumber(length) {
      return Array(length).fill(0).map(() => Math.floor(Math.random() * 10)).join('')
    },
    calculateIdCardCheckCode(base) {
      const weights = [7, 9, 10, 5, 8, 4, 2, 1, 6, 3, 7, 9, 10, 5, 8, 4, 2]
      const codes = ['1', '0', 'X', '9', '8', '7', '6', '5', '4', '3', '2']
      let sum = 0
      for (let i = 0; i < 17; i++) {
        sum += parseInt(base[i]) * weights[i]
      }
      return codes[sum % 11]
    },
    copyResult() {
      if (!this.result) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.result).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadResult() {
      if (!this.result) {
        this.$message.warning('没有可下载的内容')
        return
      }
      let mimeType = 'text/plain'
      let extension = 'txt'
      switch (this.form.outputFormat) {
        case 'json':
          mimeType = 'application/json'
          extension = 'json'
          break
        case 'csv':
          mimeType = 'text/csv'
          extension = 'csv'
          break
        case 'sql':
          mimeType = 'text/plain'
          extension = 'sql'
          break
        case 'excel':
          mimeType = 'text/plain'
          extension = 'txt'
          break
      }
      const blob = new Blob([this.result], { type: mimeType })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `fake-data.${extension}`
      link.click()
      URL.revokeObjectURL(url)
    },
    clearAll() {
      this.form.fields = []
      this.result = ''
      this.autoIncrementCounters = {}
    },
    loadExample() {
      this.form.count = 50
      this.form.outputFormat = 'json'
      this.form.fields = [
        { name: 'id', type: 'autoIncrement', start: 1, step: 1 },
        { name: 'name', type: 'name' },
        { name: 'gender', type: 'gender' },
        { name: 'age', type: 'age', minAge: 18, maxAge: 60 },
        { name: 'email', type: 'email' },
        { name: 'phone', type: 'phone' },
        { name: 'address', type: 'address' },
        { name: 'company', type: 'company' },
        { name: 'create_time', type: 'datetime' }
      ]
      this.generate()
    }
  }
}
</script>

