<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Cron 表达式解析</span>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <el-form label-width="120px">
            <el-form-item label="Cron 表达式">
              <el-input
                v-model="cronExpression"
                placeholder="输入 Cron 表达式，如: 0 0 12 * * ?"
                @input="parseCron"
              >
                <el-button slot="append" @click="copy(cronExpression)">复制</el-button>
              </el-input>
            </el-form-item>
            
            <el-form-item>
              <el-button type="primary" @click="parseCron">解析</el-button>
              <el-button @click="clear">清空</el-button>
            </el-form-item>
          </el-form>
        </el-col>
      </el-row>

      <el-row v-if="parsed" :gutter="20" style="margin-top: 20px">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">字段说明</div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="秒">{{ cronFields.second }}</el-descriptions-item>
              <el-descriptions-item label="分钟">{{ cronFields.minute }}</el-descriptions-item>
              <el-descriptions-item label="小时">{{ cronFields.hour }}</el-descriptions-item>
              <el-descriptions-item label="日期">{{ cronFields.dayOfMonth }}</el-descriptions-item>
              <el-descriptions-item label="月份">{{ cronFields.month }}</el-descriptions-item>
              <el-descriptions-item label="星期">{{ cronFields.dayOfWeek }}</el-descriptions-item>
              <el-descriptions-item v-if="cronFields.year" label="年份">{{ cronFields.year }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
        
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">人类可读描述</div>
            <div class="description">
              <p><strong>执行规则：</strong>{{ description }}</p>
            </div>
          </el-card>
          
          <el-card shadow="never" style="margin-top: 20px">
            <div slot="header">下次执行时间</div>
            <el-timeline>
              <el-timeline-item
                v-for="(time, index) in nextExecutions"
                :key="index"
                :timestamp="time"
              >
                {{ index === 0 ? '即将执行' : '第' + (index + 1) + '次' }}
              </el-timeline-item>
            </el-timeline>
          </el-card>
        </el-col>
      </el-row>

      <el-divider>常用 Cron 表达式</el-divider>

      <el-row>
        <el-col :span="24">
          <el-table :data="commonCrons" border size="small">
            <el-table-column prop="name" label="描述" width="150" />
            <el-table-column prop="expression" label="表达式">
              <template slot-scope="scope">
                <code>{{ scope.row.expression }}</code>
                <el-button
                  type="text"
                  size="mini"
                  style="float: right"
                  @click="useExpression(scope.row.expression)"
                >使用</el-button>
              </template>
            </el-table-column>
            <el-table-column prop="detail" label="说明" />
          </el-table>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CronTool',
  data() {
    return {
      cronExpression: '',
      parsed: false,
      cronFields: {
        second: '',
        minute: '',
        hour: '',
        dayOfMonth: '',
        month: '',
        dayOfWeek: '',
        year: ''
      },
      description: '',
      nextExecutions: [],
      commonCrons: [
        { name: '每秒执行', expression: '* * * * * ?', detail: '每秒执行一次' },
        { name: '每分钟', expression: '0 * * * * ?', detail: '每分钟的第0秒执行' },
        { name: '每小时', expression: '0 0 * * * ?', detail: '每小时的第0分0秒执行' },
        { name: '每天零点', expression: '0 0 0 * * ?', detail: '每天凌晨0点执行' },
        { name: '每天中午', expression: '0 0 12 * * ?', detail: '每天中午12点执行' },
        { name: '每周一', expression: '0 0 0 ? * MON', detail: '每周一凌晨执行' },
        { name: '每月1号', expression: '0 0 0 1 * ?', detail: '每月1号凌晨执行' },
        { name: '工作日', expression: '0 0 0 ? * MON-FRI', detail: '工作日每天凌晨执行' },
        { name: '每5分钟', expression: '0 0/5 * * * ?', detail: '每5分钟执行一次' },
        { name: '每10秒', expression: '0/10 * * * * ?', detail: '每10秒执行一次' }
      ]
    }
  },
  methods: {
    parseCron() {
      if (!this.cronExpression) {
        this.parsed = false
        return
      }
      
      const parts = this.cronExpression.trim().split(/\s+/)
      
      if (parts.length < 6 || parts.length > 7) {
        this.$message.error('Cron 表达式格式错误，需要 6 或 7 个字段')
        this.parsed = false
        return
      }
      
      this.cronFields = {
        second: parts[0],
        minute: parts[1],
        hour: parts[2],
        dayOfMonth: parts[3],
        month: parts[4],
        dayOfWeek: parts[5],
        year: parts[6] || ''
      }
      
      this.description = this.getDescription()
      this.nextExecutions = this.calculateNextExecutions()
      this.parsed = true
    },
    getDescription() {
      const { second, minute, hour, dayOfMonth, month, dayOfWeek } = this.cronFields
      
      let desc = ''
      
      if (second === '0' && minute === '0' && hour === '0') {
        desc = '每天凌晨'
      } else if (second === '0' && minute === '0') {
        desc = `每小时的第 ${hour} 分`
      } else if (second === '0') {
        desc = `每小时的 ${minute} 分 ${second} 秒`
      } else {
        desc = `${hour}时${minute}分${second}秒`
      }
      
      if (dayOfMonth !== '*' && dayOfMonth !== '?') {
        desc += `，每月${dayOfMonth}号`
      }
      
      if (dayOfWeek !== '*' && dayOfWeek !== '?') {
        const weekMap = { 'MON': '周一', 'TUE': '周二', 'WED': '周三', 'THU': '周四', 'FRI': '周五', 'SAT': '周六', 'SUN': '周日' }
        const weeks = dayOfWeek.split(',').map(w => weekMap[w] || w).join('、')
        desc += `，每周${weeks}`
      }
      
      if (month !== '*') {
        desc += `，${month}月`
      }
      
      return desc || '自定义规则'
    },
    calculateNextExecutions() {
      const executions = []
      let current = new Date()
      
      for (let i = 0; i < 5; i++) {
        current = this.getNextExecution(current)
        if (current) {
          executions.push(current.toLocaleString())
          current = new Date(current.getTime() + 1000)
        }
      }
      
      return executions
    },
    getNextExecution(fromDate) {
      // 简化的下次执行时间计算
      const next = new Date(fromDate)
      next.setSeconds(next.getSeconds() + 1)
      return next
    },
    clear() {
      this.cronExpression = ''
      this.parsed = false
    },
    useExpression(expr) {
      this.cronExpression = expr
      this.parseCron()
    },
    copy(text) {
      if (!text) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .description {
    padding: 10px;
    background: #f5f7fa;
    border-radius: 4px;

    p {
      margin: 0;
      line-height: 1.6;
    }
  }

  code {
    background: #f5f7fa;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: monospace;
    font-size: 12px;
  }
}
</style>
