<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>IP 工具</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="IP 查询" name="query">
          <el-row :gutter="20">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">查询 IP 地址信息</div>
                <el-input
                  v-model="queryIp"
                  placeholder="输入 IP 地址，如: 8.8.8.8，留空则查询本机IP"
                  @keyup.enter.native="queryIpInfo"
                >
                  <el-button slot="append" type="primary" @click="queryIpInfo" :loading="queryLoading">
                    查询
                  </el-button>
                </el-input>
                <div class="quick-query">
                  <el-button size="small" @click="queryMyIp">查询本机 IP</el-button>
                </div>
              </el-card>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 20px" v-if="ipInfo">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">查询结果</div>
                <el-descriptions :column="2" border>
                  <el-descriptions-item label="IP 地址">{{ ipInfo.ip }}</el-descriptions-item>
                  <el-descriptions-item label="国家">{{ ipInfo.country }}</el-descriptions-item>
                  <el-descriptions-item label="省份">{{ ipInfo.region }}</el-descriptions-item>
                  <el-descriptions-item label="城市">{{ ipInfo.city }}</el-descriptions-item>
                  <el-descriptions-item label="ISP">{{ ipInfo.isp }}</el-descriptions-item>
                  <el-descriptions-item label="时区">{{ ipInfo.timezone }}</el-descriptions-item>
                  <el-descriptions-item label="经度">{{ ipInfo.lon }}</el-descriptions-item>
                  <el-descriptions-item label="纬度">{{ ipInfo.lat }}</el-descriptions-item>
                  <el-descriptions-item label="ASN" :span="2">{{ ipInfo.asn }}</el-descriptions-item>
                  <el-descriptions-item label="组织" :span="2">{{ ipInfo.org }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="IP 转换" name="convert">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">IP 地址输入</div>
                <el-input
                  v-model="convertIp"
                  placeholder="输入 IP 地址，如: 192.168.1.1"
                  @input="convertIpAddress"
                />
              </el-card>
            </el-col>
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">转换结果</div>
                <el-descriptions :column="1" border size="small">
                  <el-descriptions-item label="十进制">
                    <span class="result-value">{{ convertResult.decimal }}</span>
                    <el-button type="text" size="mini" @click="copyValue(convertResult.decimal)">复制</el-button>
                  </el-descriptions-item>
                  <el-descriptions-item label="二进制">
                    <span class="result-value">{{ convertResult.binary }}</span>
                    <el-button type="text" size="mini" @click="copyValue(convertResult.binary)">复制</el-button>
                  </el-descriptions-item>
                  <el-descriptions-item label="十六进制">
                    <span class="result-value">{{ convertResult.hex }}</span>
                    <el-button type="text" size="mini" @click="copyValue(convertResult.hex)">复制</el-button>
                  </el-descriptions-item>
                  <el-descriptions-item label="八进制">
                    <span class="result-value">{{ convertResult.octal }}</span>
                    <el-button type="text" size="mini" @click="copyValue(convertResult.octal)">复制</el-button>
                  </el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 20px">
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">数字转 IP</div>
                <el-input
                  v-model="convertNumber"
                  placeholder="输入十进制数字，如: 3232235777"
                  @input="numberToIp"
                >
                  <el-select v-model="numberBase" slot="prepend" style="width: 100px" @change="numberToIp">
                    <el-option label="十进制" value="decimal" />
                    <el-option label="十六进制" value="hex" />
                    <el-option label="二进制" value="binary" />
                    <el-option label="八进制" value="octal" />
                  </el-select>
                </el-input>
              </el-card>
            </el-col>
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">转换结果</div>
                <div class="ip-result">
                  <span class="result-value large">{{ numberToIpResult }}</span>
                  <el-button type="text" size="mini" @click="copyValue(numberToIpResult)">复制</el-button>
                </div>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="子网计算" name="subnet">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">子网计算器</div>
                <el-form label-width="100px">
                  <el-form-item label="IP 地址">
                    <el-input v-model="subnetIp" placeholder="192.168.1.1" @input="calculateSubnet" />
                  </el-form-item>
                  <el-form-item label="子网掩码">
                    <el-input v-model="subnetMask" placeholder="255.255.255.0" @input="calculateSubnet" />
                    <div class="mask-buttons">
                      <el-button size="mini" v-for="cidr in [8, 16, 20, 24, 25, 26, 27, 28, 29, 30]" 
                                 :key="cidr" 
                                 @click="setCidr(cidr)">
                        /{{ cidr }}
                      </el-button>
                    </div>
                  </el-form-item>
                  <el-form-item label="或 CIDR">
                    <el-input v-model="cidrNotation" placeholder="24" @input="cidrToMask" />
                  </el-form-item>
                </el-form>
              </el-card>
            </el-col>
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">计算结果</div>
                <el-descriptions :column="1" border size="small">
                  <el-descriptions-item label="网络地址">{{ subnetResult.network }}</el-descriptions-item>
                  <el-descriptions-item label="广播地址">{{ subnetResult.broadcast }}</el-descriptions-item>
                  <el-descriptions-item label="可用主机数">{{ subnetResult.hosts }}</el-descriptions-item>
                  <el-descriptions-item label="可用 IP 范围">{{ subnetResult.range }}</el-descriptions-item>
                  <el-descriptions-item label="子网掩码">{{ subnetResult.mask }}</el-descriptions-item>
                  <el-descriptions-item label="CIDR">{{ subnetResult.cidr }}</el-descriptions-item>
                  <el-descriptions-item label="IP 类型">{{ subnetResult.type }}</el-descriptions-item>
                  <el-descriptions-item label="通配符掩码">{{ subnetResult.wildcard }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="DNS 查询" name="dns">
          <el-row :gutter="20">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">DNS 记录查询 (Google DNS over HTTPS)</div>
                <el-form :inline="true">
                  <el-form-item label="域名">
                    <el-input v-model="dnsDomain" placeholder="example.com" @keyup.enter.native="queryDns" style="width:250px" />
                  </el-form-item>
                  <el-form-item label="记录类型">
                    <el-select v-model="dnsType" style="width:120px">
                      <el-option label="A (IPv4)" value="A" />
                      <el-option label="AAAA (IPv6)" value="AAAA" />
                      <el-option label="CNAME" value="CNAME" />
                      <el-option label="MX" value="MX" />
                      <el-option label="NS" value="NS" />
                      <el-option label="TXT" value="TXT" />
                      <el-option label="SOA" value="SOA" />
                      <el-option label="PTR" value="PTR" />
                      <el-option label="SRV" value="SRV" />
                    </el-select>
                  </el-form-item>
                  <el-form-item>
                    <el-button type="primary" @click="queryDns" :loading="dnsLoading">查询</el-button>
                  </el-form-item>
                </el-form>
              </el-card>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 20px" v-if="dnsResults.length > 0">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">DNS 查询结果</div>
                <el-table :data="dnsResults" border size="small">
                  <el-table-column prop="name" label="域名" />
                  <el-table-column prop="type" label="类型" width="100" />
                  <el-table-column prop="TTL" label="TTL" width="100" />
                  <el-table-column label="值">
                    <template slot-scope="scope">
                      <code>{{ scope.row.data }}</code>
                      <el-button type="text" size="mini" @click="copyValue(scope.row.data)">复制</el-button>
                    </template>
                  </el-table-column>
                </el-table>
              </el-card>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 10px" v-if="dnsError">
            <el-col :span="24">
              <el-alert :title="dnsError" type="error" show-icon :closable="false" />
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="IP 验证" name="validate">
          <el-row :gutter="20">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">IP 地址验证</div>
                <el-input
                  v-model="validateIp"
                  type="textarea"
                  :rows="6"
                  placeholder="输入 IP 地址，每行一个，如:
192.168.1.1
10.0.0.1
256.1.1.1
2001:0db8:85a3:0000:0000:8a2e:0370:7334"
                />
                <div style="margin-top: 10px">
                  <el-button type="primary" @click="validateIpAddresses">验证</el-button>
                </div>
              </el-card>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 20px" v-if="validateResults.length > 0">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">验证结果</div>
                <el-table :data="validateResults" border size="small">
                  <el-table-column prop="ip" label="IP 地址" />
                  <el-table-column prop="valid" label="是否有效" width="100">
                    <template slot-scope="scope">
                      <el-tag :type="scope.row.valid ? 'success' : 'danger'" size="small">
                        {{ scope.row.valid ? '有效' : '无效' }}
                      </el-tag>
                    </template>
                  </el-table-column>
                  <el-table-column prop="version" label="版本" width="80" />
                  <el-table-column prop="type" label="类型" />
                  <el-table-column prop="private" label="私有地址" width="100">
                    <template slot-scope="scope">
                      <el-tag :type="scope.row.private ? 'warning' : 'info'" size="small">
                        {{ scope.row.private ? '是' : '否' }}
                      </el-tag>
                    </template>
                  </el-table-column>
                </el-table>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'IpTool',
  data() {
    return {
      activeTab: 'query',
      queryIp: '',
      queryLoading: false,
      ipInfo: null,
      convertIp: '',
      convertResult: {
        decimal: '',
        binary: '',
        hex: '',
        octal: ''
      },
      convertNumber: '',
      numberBase: 'decimal',
      numberToIpResult: '',
      subnetIp: '192.168.1.1',
      subnetMask: '255.255.255.0',
      cidrNotation: '24',
      subnetResult: {
        network: '',
        broadcast: '',
        hosts: 0,
        range: '',
        mask: '',
        cidr: '',
        type: '',
        wildcard: ''
      },
      validateIp: '',
      validateResults: [],
      dnsDomain: '',
      dnsType: 'A',
      dnsResults: [],
      dnsLoading: false,
      dnsError: '',
      apiEndpoints: [
        'https://ipapi.co/{ip}/json/',
        'https://ip-api.com/json/{ip}',
        'https://ipwho.is/{ip}'
      ],
      currentApiIndex: 0
    }
  },
  mounted() {
    this.calculateSubnet()
  },
  methods: {
    async queryIpInfo() {
      if (this.queryLoading) return
      
      this.queryLoading = true
      this.ipInfo = null

      const ip = this.queryIp.trim()
      const url = ip ? this.apiEndpoints[this.currentApiIndex].replace('{ip}', ip) : 'https://ipapi.co/json/'
      
      try {
        const response = await fetch(url)
        const data = await response.json()
        
        if (data.error || data.status === 'fail') {
          throw new Error(data.reason || data.message || '查询失败')
        }
        
        this.ipInfo = this.normalizeIpData(data, ip)
      } catch (error) {
        this.currentApiIndex = (this.currentApiIndex + 1) % this.apiEndpoints.length
        
        if (this.currentApiIndex !== 0) {
          this.$message.warning('尝试备用接口...')
          this.queryIpInfo()
          return
        }
        
        this.$message.error('查询失败: ' + error.message)
      } finally {
        this.queryLoading = false
      }
    },
    normalizeIpData(data, queryIp) {
      if (data.ip || data.query) {
        return {
          ip: data.ip || data.query,
          country: data.country_name || data.country || '-',
          region: data.region || data.regionName || '-',
          city: data.city || '-',
          isp: data.isp || data.org || '-',
          timezone: data.timezone || '-',
          lon: data.longitude || data.lon || '-',
          lat: data.latitude || data.lat || '-',
          asn: data.asn || '-',
          org: data.org || data.isp || '-'
        }
      }
      return data
    },
    async queryMyIp() {
      this.queryIp = ''
      await this.queryIpInfo()
    },
    convertIpAddress() {
      const ip = this.convertIp.trim()
      if (!this.isValidIpv4(ip)) {
        this.convertResult = { decimal: '', binary: '', hex: '', octal: '' }
        return
      }

      const parts = ip.split('.').map(Number)
      const decimal = (parts[0] << 24) + (parts[1] << 16) + (parts[2] << 8) + parts[3]
      
      this.convertResult = {
        decimal: decimal.toString(),
        binary: decimal.toString(2).padStart(32, '0'),
        hex: '0x' + decimal.toString(16).toUpperCase().padStart(8, '0'),
        octal: '0' + decimal.toString(8).padStart(11, '0')
      }
    },
    numberToIp() {
      const num = this.convertNumber.trim()
      if (!num) {
        this.numberToIpResult = ''
        return
      }

      try {
        let decimal
        switch (this.numberBase) {
          case 'decimal':
            decimal = parseInt(num, 10)
            break
          case 'hex':
            decimal = parseInt(num.replace(/^0x/i, ''), 16)
            break
          case 'binary':
            decimal = parseInt(num, 2)
            break
          case 'octal':
            decimal = parseInt(num.replace(/^0/, ''), 8)
            break
        }

        if (isNaN(decimal) || decimal < 0 || decimal > 4294967295) {
          this.numberToIpResult = '无效的数字'
          return
        }

        const part1 = (decimal >>> 24) & 255
        const part2 = (decimal >>> 16) & 255
        const part3 = (decimal >>> 8) & 255
        const part4 = decimal & 255

        this.numberToIpResult = `${part1}.${part2}.${part3}.${part4}`
      } catch {
        this.numberToIpResult = '转换失败'
      }
    },
    calculateSubnet() {
      const ip = this.subnetIp.trim()
      const mask = this.subnetMask.trim()
      
      if (!this.isValidIpv4(ip) || !this.isValidIpv4(mask)) {
        return
      }

      const ipParts = ip.split('.').map(Number)
      const maskParts = mask.split('.').map(Number)
      
      const ipNum = (ipParts[0] << 24) + (ipParts[1] << 16) + (ipParts[2] << 8) + ipParts[3]
      const maskNum = (maskParts[0] << 24) + (maskParts[1] << 16) + (maskParts[2] << 8) + maskParts[3]
      
      const networkNum = ipNum & maskNum
      const broadcastNum = networkNum | (~maskNum >>> 0)
      
      const network = this.numToIp(networkNum)
      const broadcast = this.numToIp(broadcastNum)
      
      let cidr = 0
      let tempMask = maskNum
      while (tempMask) {
        cidr += tempMask & 1
        tempMask >>>= 1
      }
      
      const hosts = Math.pow(2, 32 - cidr) - 2
      const firstHost = this.numToIp(networkNum + 1)
      const lastHost = this.numToIp(broadcastNum - 1)
      
      const wildcard = this.numToIp(~maskNum >>> 0)
      
      let type = '公网'
      if (ipParts[0] === 10) {
        type = 'A类私有'
      } else if (ipParts[0] === 172 && ipParts[1] >= 16 && ipParts[1] <= 31) {
        type = 'B类私有'
      } else if (ipParts[0] === 192 && ipParts[1] === 168) {
        type = 'C类私有'
      } else if (ipParts[0] === 127) {
        type = '本地回环'
      } else if (ipParts[0] === 169 && ipParts[1] === 254) {
        type = '链路本地'
      }

      this.subnetResult = {
        network,
        broadcast,
        hosts: hosts > 0 ? hosts : 0,
        range: hosts > 0 ? `${firstHost} - ${lastHost}` : '无可用主机',
        mask,
        cidr: `/${cidr}`,
        type,
        wildcard
      }
      
      this.cidrNotation = cidr.toString()
    },
    cidrToMask() {
      const cidr = parseInt(this.cidrNotation)
      if (isNaN(cidr) || cidr < 0 || cidr > 32) return
      
      const maskNum = cidr === 0 ? 0 : (~0 << (32 - cidr)) >>> 0
      this.subnetMask = this.numToIp(maskNum)
      this.calculateSubnet()
    },
    setCidr(cidr) {
      this.cidrNotation = cidr.toString()
      this.cidrToMask()
    },
    numToIp(num) {
      return [
        (num >>> 24) & 255,
        (num >>> 16) & 255,
        (num >>> 8) & 255,
        num & 255
      ].join('.')
    },
    isValidIpv4(ip) {
      const parts = ip.split('.')
      if (parts.length !== 4) return false
      return parts.every(part => {
        const num = parseInt(part, 10)
        return !isNaN(num) && num >= 0 && num <= 255 && part === num.toString()
      })
    },
    isValidIpv6(ip) {
      const ipv6Pattern = /^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::$|^([0-9a-fA-F]{1,4}:){1,7}:$|^:([0-9a-fA-F]{1,4}:){1,7}$|^([0-9a-fA-F]{1,4}:){1,6}:[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:){1,5}(:[0-9a-fA-F]{1,4}){1,2}$|^([0-9a-fA-F]{1,4}:){1,4}(:[0-9a-fA-F]{1,4}){1,3}$|^([0-9a-fA-F]{1,4}:){1,3}(:[0-9a-fA-F]{1,4}){1,4}$|^([0-9a-fA-F]{1,4}:){1,2}(:[0-9a-fA-F]{1,4}){1,5}$|^[0-9a-fA-F]{1,4}:((:[0-9a-fA-F]{1,4}){1,6})$|^:((:[0-9a-fA-F]{1,4}){1,7}|:)$|^([0-9a-fA-F]{1,4}:){1,7}:$/
      return ipv6Pattern.test(ip)
    },
    getIpType(ip) {
      if (!this.isValidIpv4(ip) && !this.isValidIpv6(ip)) {
        return '无效'
      }
      
      if (this.isValidIpv6(ip)) {
        return 'IPv6'
      }
      
      const parts = ip.split('.').map(Number)
      if (parts[0] === 10) return 'A类私有'
      if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return 'B类私有'
      if (parts[0] === 192 && parts[1] === 168) return 'C类私有'
      if (parts[0] === 127) return '本地回环'
      if (parts[0] === 169 && parts[1] === 254) return '链路本地'
      if (parts[0] >= 224 && parts[0] <= 239) return 'D类组播'
      if (parts[0] >= 240) return 'E类保留'
      if (parts[0] < 128) return 'A类公网'
      if (parts[0] < 192) return 'B类公网'
      return 'C类公网'
    },
    isPrivateIp(ip) {
      if (!this.isValidIpv4(ip)) return false
      const parts = ip.split('.').map(Number)
      return (
        parts[0] === 10 ||
        (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) ||
        (parts[0] === 192 && parts[1] === 168)
      )
    },
    validateIpAddresses() {
      const ips = this.validateIp.split('\n').filter(ip => ip.trim())
      this.validateResults = ips.map(ip => {
        const trimmedIp = ip.trim()
        const isV4 = this.isValidIpv4(trimmedIp)
        const isV6 = this.isValidIpv6(trimmedIp)
        
        return {
          ip: trimmedIp,
          valid: isV4 || isV6,
          version: isV4 ? 'IPv4' : (isV6 ? 'IPv6' : '-'),
          type: this.getIpType(trimmedIp),
          private: isV4 && this.isPrivateIp(trimmedIp)
        }
      })
    },
    copyValue(value) {
      if (!value) return
      navigator.clipboard.writeText(value).then(() => {
        this.$message.success('已复制: ' + value)
      })
    },
    async queryDns() {
      if (!this.dnsDomain.trim()) {
        this.$message.warning('请输入域名')
        return
      }

      this.dnsLoading = true
      this.dnsError = ''
      this.dnsResults = []

      try {
        const res = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(this.dnsDomain.trim())}&type=${this.dnsType}`)
        if (!res.ok) throw new Error(`请求失败 (${res.status})`)
        const data = await res.json()
        if (data.Answer) {
          this.dnsResults = data.Answer.map(a => ({
            name: a.name,
            type: this.dnsType,
            TTL: a.TTL,
            data: a.data
          }))
        } else if (data.Authority) {
          this.dnsResults = data.Authority.map(a => ({
            name: a.name,
            type: `${a.type} (Authority)`,
            TTL: a.TTL,
            data: a.data
          }))
        } else {
          this.dnsError = `未找到 ${this.dnsType} 记录`
        }
      } catch (e) {
        this.dnsError = '查询失败: ' + e.message
      } finally {
        this.dnsLoading = false
      }
    },
    clearAll() {
