<template>
  <div class="regex-builder-tool">
    <el-card>
      <div slot="header">
        <span>正则生成器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form :model="config" label-width="120px">
            <el-form-item label="匹配类型">
              <el-select v-model="config.patternType" style="width: 100%" @change="generateRegex">
                <el-option-group label="常用模式">
                  <el-option label="自定义" value="custom" />
                  <el-option label="邮箱地址" value="email" />
                  <el-option label="手机号" value="phone" />
                  <el-option label="身份证号" value="idCard" />
                  <el-option label="URL" value="url" />
                  <el-option label="IP地址" value="ip" />
                </el-option-group>
                <el-option-group label="数字相关">
                  <el-option label="整数" value="integer" />
                  <el-option label="小数" value="decimal" />
                  <el-option label="正数" value="positive" />
                  <el-option label="负数" value="negative" />
                  <el-option label="百分比" value="percent" />
                  <el-option label="货币" value="currency" />
                </el-option-group>
                <el-option-group label="字符串相关">
                  <el-option label="中文字符" value="chinese" />
                  <el-option label="英文字母" value="english" />
                  <el-option label="数字字母" value="alphanumeric" />
                  <el-option label="密码强度" value="password" />
                  <el-option label="用户名" value="username" />
                </el-option-group>
                <el-option-group label="日期时间">
                  <el-option label="日期(yyyy-MM-dd)" value="date" />
                  <el-option label="时间(HH:mm:ss)" value="time" />
                  <el-option label="日期时间" value="datetime" />
                </el-option-group>
                <el-option-group label="网络相关">
                  <el-option label="域名" value="domain" />
                  <el-option label="MAC地址" value="mac" />
                  <el-option label="端口号" value="port" />
                </el-option-group>
              </el-select>
            </el-form-item>

            <template v-if="config.patternType === 'custom'">
              <el-form-item label="字符类型">
                <el-checkbox-group v-model="config.charTypes" @change="generateRegex">
                  <el-checkbox label="digits">数字</el-checkbox>
                  <el-checkbox label="letters">字母</el-checkbox>
                  <el-checkbox label="chinese">中文</el-checkbox>
                  <el-checkbox label="special">特殊字符</el-checkbox>
                  <el-checkbox label="space">空格</el-checkbox>
                </el-checkbox-group>
              </el-form-item>

              <el-row :gutter="10">
                <el-col :span="12">
                  <el-form-item label="最小长度">
                    <el-input-number v-model="config.minLength" :min="0" :max="100" style="width: 100%" @change="generateRegex" />
                  </el-form-item>
                </el-col>
                <el-col :span="12">
                  <el-form-item label="最大长度">
                    <el-input-number v-model="config.maxLength" :min="1" :max="1000" style="width: 100%" @change="generateRegex" />
                  </el-form-item>
                </el-col>
              </el-row>

              <el-form-item label="开头字符">
                <el-input v-model="config.startsWith" placeholder="^abc" @input="generateRegex" />
              </el-form-item>

              <el-form-item label="结尾字符">
                <el-input v-model="config.endsWith" placeholder="xyz$" @input="generateRegex" />
              </el-form-item>
            </template>

            <template v-if="config.patternType === 'password'">
              <el-form-item label="密码要求">
                <el-checkbox-group v-model="config.passwordRules" @change="generateRegex">
                  <el-checkbox label="uppercase">大写字母</el-checkbox>
                  <el-checkbox label="lowercase">小写字母</el-checkbox>
                  <el-checkbox label="digits">数字</el-checkbox>
                  <el-checkbox label="special">特殊字符</el-checkbox>
                </el-checkbox-group>
              </el-form-item>
              <el-form-item label="最小长度">
                <el-slider v-model="config.passwordMinLength" :min="6" :max="32" show-input @change="generateRegex" />
              </el-form-item>
            </template>

            <el-form-item label="正则表达式">
              <el-input v-model="generatedRegex" readonly>
                <el-button slot="append" @click="copyRegex">复制</el-button>
              </el-input>
            </el-form-item>

            <el-form-item label="修饰符">
              <el-checkbox-group v-model="config.flags" @change="generateRegex">
                <el-checkbox label="g">全局(g)</el-checkbox>
                <el-checkbox label="i">忽略大小写(i)</el-checkbox>
                <el-checkbox label="m">多行(m)</el-checkbox>
                <el-checkbox label="s">单行(s)</el-checkbox>
              </el-checkbox-group>
            </el-form-item>
          </el-form>
        </el-col>

        <el-col :span="12">
          <div class="test-section">
            <div class="section-title">测试文本</div>
            <el-input
              v-model="testText"
              type="textarea"
              :rows="8"
              placeholder="输入要测试的文本..."
              @input="testRegex"
            />

            <div class="section-title" style="margin-top: 20px;">匹配结果</div>
            <div class="match-results" v-if="matches.length > 0">
              <div v-for="(match, index) in matches" :key="index" class="match-item">
                <span class="match-index">#{{ index + 1 }}</span>
                <span class="match-text">{{ match.text }}</span>
                <span class="match-position">位置: {{ match.index }}</span>
              </div>
            </div>
            <div v-else-if="testText" class="no-match">
              未找到匹配
            </div>

            <div class="section-title" style="margin-top: 20px;">代码示例</div>
            <el-tabs v-model="codeTab">
              <el-tab-pane label="JavaScript" name="js">
                <pre class="code-block"><code>{{ jsCode }}</code></pre>
              </el-tab-pane>
              <el-tab-pane label="Java" name="java">
                <pre class="code-block"><code>{{ javaCode }}</code></pre>
              </el-tab-pane>
              <el-tab-pane label="Python" name="python">
                <pre class="code-block"><code>{{ pythonCode }}</code></pre>
              </el-tab-pane>
            </el-tabs>
            <el-button type="text" @click="copyCode">复制代码</el-button>
          </div>
        </el-col>
      </el-row>

      <el-divider>常用正则表达式参考</el-divider>

      <el-table :data="commonPatterns" border size="small">
        <el-table-column prop="name" label="名称" width="150" />
        <el-table-column prop="pattern" label="正则表达式" width="300">
          <template slot-scope="scope">
            <code>{{ scope.row.pattern }}</code>
          </template>
        </el-table-column>
        <el-table-column prop="description" label="说明" />
        <el-table-column label="操作" width="100">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="usePattern(scope.row)">使用</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'RegexBuilderTool',
  data() {
    return {
      config: {
        patternType: 'email',
        charTypes: ['digits', 'letters'],
        minLength: 1,
        maxLength: 50,
        startsWith: '',
        endsWith: '',
        passwordRules: ['uppercase', 'lowercase', 'digits'],
        passwordMinLength: 8,
        flags: ['g']
      },
      generatedRegex: '',
      testText: '',
      matches: [],
      codeTab: 'js',
      commonPatterns: [
        { name: '邮箱', pattern: '^[\\w-]+(\\.[\\w-]+)*@[\\w-]+(\\.[\\w-]+)+$', description: '标准邮箱格式' },
        { name: '手机号', pattern: '^1[3-9]\\d{9}$', description: '中国大陆手机号' },
        { name: '身份证号', pattern: '^\\d{17}[\\dXx]$', description: '18位身份证号' },
        { name: 'URL', pattern: '^https?://[\\w.-]+(?:/[\\w./-]*)?$', description: 'HTTP/HTTPS URL' },
        { name: 'IPv4', pattern: '^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$', description: 'IPv4地址' },
        { name: '中文字符', pattern: '[\\u4e00-\\u9fa5]', description: '匹配中文字符' },
        { name: '正整数', pattern: '^[1-9]\\d*$', description: '大于0的整数' },
        { name: '负整数', pattern: '^-[1-9]\\d*$', description: '小于0的整数' }
      ]
    }
  },
  computed: {
    jsCode() {
      const flags = this.config.flags.join('')
      return `const regex = /${this.escapeForCode(this.generatedRegex)}/${flags};
const str = 'your text here';
const matches = str.match(regex);
console.log(matches);`
    },
    javaCode() {
      return `String regex = "${this.escapeForJava(this.generatedRegex)}";
Pattern pattern = Pattern.compile(regex);
Matcher matcher = pattern.matcher(input);
while (matcher.find()) {
    System.out.println(matcher.group());
}`
    },
    pythonCode() {
      const flags = this.config.flags.includes('i') ? ', re.IGNORECASE' : ''
      return `import re

pattern = r'${this.escapeForPython(this.generatedRegex)}'
text = 'your text here'
matches = re.findall(pattern, text${flags})
print(matches)`
    }
  },
  mounted() {
    this.generateRegex()
  },
  methods: {
    generateRegex() {
      const patterns = {
        email: '^[\\w-]+(\\.[\\w-]+)*@[\\w-]+(\\.[\\w-]+)+$',
        phone: '^1[3-9]\\d{9}$',
        idCard: '^\\d{17}[\\dXx]$',
        url: '^https?://[\\w.-]+(?:/[\\w./-]*)?$',
        ip: '^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$',
        integer: '^-?\\d+$',
        decimal: '^-?\\d+\\.\\d+$',
        positive: '^[1-9]\\d*(?:\\.\\d+)?$',
        negative: '^-[1-9]\\d*(?:\\.\\d+)?$',
        percent: '^\\d{1,3}(?:\\.\\d+)?%$',
        currency: '^[¥$€]?\\d+(?:,\\d{3})*(?:\\.\\d{2})?$',
        chinese: '[\\u4e00-\\u9fa5]+',
        english: '^[a-zA-Z]+$',
        alphanumeric: '^[a-zA-Z0-9]+$',
        username: '^[a-zA-Z][a-zA-Z0-9_-]{3,15}$',
        date: '^\\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\\d|3[01])$',
        time: '^(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d$',
        datetime: '^\\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\\d|3[01]) (?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d$',
        domain: '^[a-zA-Z0-9][-a-zA-Z0-9]*\\.[a-zA-Z0-9][-a-zA-Z0-9.]*$',
        mac: '^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$',
        port: '^([1-9]\\d{0,3}|[1-5]\\d{4}|6[0-4]\\d{3}|65[0-4]\\d{2}|655[0-2]\\d|6553[0-5])$'
      }

      if (this.config.patternType === 'custom') {
        this.generatedRegex = this.buildCustomRegex()
      } else if (this.config.patternType === 'password') {
        this.generatedRegex = this.buildPasswordRegex()
      } else {
        this.generatedRegex = patterns[this.config.patternType] || ''
      }

      this.testRegex()
    },
    buildCustomRegex() {
      let charClass = ''
      if (this.config.charTypes.includes('digits')) charClass += '0-9'
      if (this.config.charTypes.includes('letters')) charClass += 'a-zA-Z'
      if (this.config.charTypes.includes('chinese')) charClass += '\\u4e00-\\u9fa5'
      if (this.config.charTypes.includes('special')) charClass += '\\W_'
      if (this.config.charTypes.includes('space')) charClass += '\\s'

      if (!charClass) charClass = '.'

      let quantifier = ''
      if (this.config.minLength === 0 && this.config.maxLength === 1000) {
        quantifier = '*'
      } else if (this.config.minLength === 1 && this.config.maxLength === 1000) {
        quantifier = '+'
      } else if (this.config.minLength === this.config.maxLength) {
        quantifier = `{${this.config.minLength}}`
      } else {
        quantifier = `{${this.config.minLength},${this.config.maxLength}}`
      }

      let regex = `[${charClass}]${quantifier}`
      if (this.config.startsWith) {
        regex = this.config.startsWith + regex
      } else {
        regex = '^' + regex
      }
      if (this.config.endsWith) {
        regex = regex + this.config.endsWith
      } else {
        regex = regex + '$'
      }

      return regex
    },
    buildPasswordRegex() {
      const rules = this.config.passwordRules
      let positiveLookaheads = ''
      
      if (rules.includes('uppercase')) {
        positiveLookaheads += '(?=.*[A-Z])'
      }
      if (rules.includes('lowercase')) {
        positiveLookaheads += '(?=.*[a-z])'
      }
      if (rules.includes('digits')) {
        positiveLookaheads += '(?=.*\\d)'
      }
      if (rules.includes('special')) {
        positiveLookaheads += '(?=.*[!@#$%^&*])'
      }

      return `^${positiveLookaheads}.{${this.config.passwordMinLength},}$`
    },
    testRegex() {
      if (!this.generatedRegex || !this.testText) {
        this.matches = []
        return
      }

      try {
        const flags = this.config.flags.join('')
        const regex = new RegExp(this.generatedRegex, flags)
        this.matches = []

        let match
        while ((match = regex.exec(this.testText)) !== null) {
          this.matches.push({
            text: match[0],
            index: match.index
          })
          if (!flags.includes('g')) break
        }
      } catch (e) {
        this.matches = []
      }
    },
    copyRegex() {
      navigator.clipboard.writeText(this.generatedRegex).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    copyCode() {
      let code = ''
      switch (this.codeTab) {
        case 'js':
          code = this.jsCode
          break
        case 'java':
          code = this.javaCode
          break
        case 'python':
          code = this.pythonCode
          break
      }
      navigator.clipboard.writeText(code).then(() => {
        this.$message.success('代码已复制到剪贴板')
      })
    },
    usePattern(pattern) {
      this.config.patternType = 'custom'
      this.generatedRegex = pattern.pattern
      this.testRegex()
    },
    escapeForCode(str) {
      return str.replace(/\\/g, '\\\\')
    },
    escapeForJava(str) {
      return str.replace(/\\/g, '\\\\').replace(/"/g, '\\"')
    },
    escapeForPython(str) {
      return str.replace(/\\/g, '\\\\').replace(/'/g, "\\'")
    },
    loadExample() {
      this.config.patternType = 'email'
      this.generateRegex()
      this.testText = 'test@example.com\ninvalid-email\nanother@test.org'
      this.testRegex()
    }
  }
}
</script>

<style scoped>
.regex-builder-tool {
  padding: 20px;
}

.test-section {
  height: 100%;
}

.section-title {
  font-weight: bold;
  margin-bottom: 10px;
  color: #606266;
}

.match-results {
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  max-height: 200px;
  overflow-y: auto;
}

.match-item {
  padding: 8px 12px;
  border-bottom: 1px solid #ebeef5;
  display: flex;
  align-items: center;
  gap: 10px;
}

.match-item:last-child {
  border-bottom: none;
}

.match-index {
  color: #409eff;
  font-weight: bold;
  min-width: 30px;
}

.match-text {
  flex: 1;
  font-family: monospace;
  background: #f5f7fa;
  padding: 2px 6px;
  border-radius: 3px;
}

.match-position {
  color: #909399;
  font-size: 12px;
}

.no-match {
  padding: 20px;
  text-align: center;
  color: #909399;
  background: #f5f7fa;
  border-radius: 4px;
}

.code-block {
  background: #f5f7fa;
  padding: 15px;
  border-radius: 4px;
  overflow-x: auto;
  font-family: 'Courier New', monospace;
  font-size: 13px;
  line-height: 1.6;
}
</style>
