<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>SSE (Server-Sent Events) 测试工具</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearEvents">清空事件</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <div class="connection-panel">
            <el-input
              v-model="sseUrl"
              placeholder="http://localhost:8080/api/sse/connect"
              class="url-input"
            >
              <template slot="prepend">SSE URL</template>
            </el-input>
            <el-button
              :type="connected ? 'danger' : 'primary'"
              @click="toggleConnection"
            >
              {{ connected ? '断开连接' : '连接' }}
            </el-button>
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="24">
          <div class="status-bar">
            <span class="status-label">状态:</span>
            <el-tag :type="connected ? 'success' : 'info'" size="small">
              {{ connected ? '已连接' : '未连接' }}
            </el-tag>
            <span v-if="connected" class="connection-info">
              | 连接时间: {{ connectTime }} | 接收事件: {{ eventCount }}
            </span>
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="12">
          <div class="config-panel">
            <div class="panel-header">
              <span>请求配置</span>
            </div>
            <el-form label-width="80px" size="small">
              <el-form-item label="请求方法">
                <el-select v-model="method" style="width: 100%">
                  <el-option label="GET" value="GET" />
                  <el-option label="POST" value="POST" />
                </el-select>
              </el-form-item>
              <el-form-item label="请求头">
                <div class="headers-editor">
                  <div v-for="(header, index) in headers" :key="index" class="header-row">
                    <el-input v-model="header.key" placeholder="Header Name" style="width: 40%" />
                    <el-input v-model="header.value" placeholder="Header Value" style="width: 40%" />
                    <el-button type="danger" icon="el-icon-delete" circle size="mini" @click="removeHeader(index)" />
                  </div>
                  <el-button size="mini" @click="addHeader">添加请求头</el-button>
                </div>
              </el-form-item>
              <el-form-item v-if="method === 'POST'" label="请求体">
                <el-input
                  v-model="requestBody"
                  type="textarea"
                  :rows="4"
                  placeholder="请求体内容..."
                />
              </el-form-item>
              <el-form-item>
                <el-button type="primary" :disabled="connected" @click="sendTestRequest">
                  发送测试请求
                </el-button>
              </el-form-item>
            </el-form>
          </div>
        </el-col>

        <el-col :span="12">
          <div class="events-panel">
            <div class="panel-header">
              <span>事件流</span>
              <el-button size="mini" @click="exportEvents">导出</el-button>
            </div>
            <div class="events-container" ref="eventsContainer">
              <div
                v-for="(event, index) in events"
                :key="index"
                :class="['event-item', event.type]"
              >
                <div class="event-header">
                  <span class="event-time">{{ event.time }}</span>
                  <el-tag size="mini" :type="getEventTagType(event.type)">
                    {{ event.eventName || 'message' }}
                  </el-tag>
                </div>
                <div class="event-content">
                  <pre v-if="isJson(event.data)">{{ formatJson(event.data) }}</pre>
                  <span v-else>{{ event.data }}</span>
                </div>
              </div>
              <div v-if="events.length === 0" class="no-events">
                暂无事件
              </div>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="24">
          <div class="quick-urls">
            <span class="label">快速连接:</span>
            <el-button size="small" @click="setUrl('http://localhost:8080/api/sse/connect')">
              本地SSE
            </el-button>
            <el-button size="small" @click="setUrl('http://localhost:8080/api/sse/test')">
              测试SSE
            </el-button>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'SseTool',
  data() {
    return {
      sseUrl: 'http://localhost:8080/api/sse/connect',
      connected: false,
      connectTime: '',
      eventCount: 0,
      eventSource: null,
      method: 'GET',
      headers: [
        { key: 'Content-Type', value: 'application/json' }
      ],
      requestBody: '',
      events: []
    }
  },
  methods: {
    toggleConnection() {
      if (this.connected) {
        this.disconnect()
      } else {
        this.connect()
      }
    },
    connect() {
      try {
        this.eventSource = new EventSource(this.sseUrl)
        
        this.eventSource.onopen = () => {
          this.connected = true
          this.connectTime = new Date().toLocaleTimeString()
          this.addEvent('system', 'SSE 连接成功', 'connected')
          this.$message.success('连接成功')
        }
        
        this.eventSource.onmessage = (event) => {
          this.addEvent('message', event.data, 'message')
        }
        
        this.eventSource.onerror = (error) => {
          this.addEvent('error', '连接错误或已关闭', 'error')
          this.connected = false
          this.$message.error('连接错误')
        }
        
        this.eventSource.addEventListener('connected', (event) => {
          this.addEvent('connected', event.data, 'connected')
        })
        
        this.eventSource.addEventListener('response', (event) => {
          this.addEvent('response', event.data, 'response')
        })
        
      } catch (e) {
        this.$message.error('连接失败: ' + e.message)
      }
    },
    disconnect() {
      if (this.eventSource) {
        this.eventSource.close()
        this.eventSource = null
      }
      this.connected = false
      this.addEvent('system', 'SSE 连接已关闭', 'disconnected')
    },
    async sendTestRequest() {
      try {
        const headersObj = {}
        this.headers.forEach(h => {
          if (h.key) {
            headersObj[h.key] = h.value
          }
        })
        
        const response = await fetch(this.sseUrl, {
          method: this.method,
          headers: headersObj,
          body: this.method === 'POST' ? this.requestBody : undefined
        })
        
        const reader = response.body.getReader()
        const decoder = new TextDecoder()
        
        this.addEvent('system', '请求已发送，等待响应...', 'request')
        
        while (true) {
          const { done, value } = await reader.read()
          if (done) break
          
          const chunk = decoder.decode(value)
          const lines = chunk.split('\n')
          
          lines.forEach(line => {
            if (line.startsWith('data:')) {
              const data = line.substring(5).trim()
              this.addEvent('response', data, 'response')
            } else if (line.startsWith('event:')) {
              // 处理事件名
            }
          })
        }
        
        this.addEvent('system', '响应完成', 'complete')
        
      } catch (e) {
        this.$message.error('请求失败: ' + e.message)
        this.addEvent('error', e.message, 'error')
      }
    },
    addEvent(eventName, data, type) {
      this.events.push({
        eventName,
        data,
        type,
        time: new Date().toLocaleTimeString()
      })
      this.eventCount++
      this.$nextTick(() => {
        const container = this.$refs.eventsContainer
        if (container) {
          container.scrollTop = container.scrollHeight
        }
      })
    },
    clearEvents() {
      this.events = []
      this.eventCount = 0
    },
    addHeader() {
      this.headers.push({ key: '', value: '' })
    },
    removeHeader(index) {
      this.headers.splice(index, 1)
    },
    isJson(str) {
      try {
        JSON.parse(str)
        return true
      } catch (e) {
        return false
      }
    },
    formatJson(str) {
      try {
        return JSON.stringify(JSON.parse(str), null, 2)
      } catch (e) {
        return str
      }
    },
    getEventTagType(type) {
      const types = {
        'message': '',
        'connected': 'success',
        'response': 'primary',
        'error': 'danger',
        'system': 'info',
        'disconnected': 'warning'
      }
      return types[type] || ''
    },
    setUrl(url) {
      this.sseUrl = url
    },
    exportEvents() {
      const content = this.events.map(e => `[${e.time}] [${e.eventName || 'message'}]: ${e.data}`).join('\n')
      const blob = new Blob([content], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'sse_events_' + new Date().toISOString().slice(0, 10) + '.txt'
      a.click()
      URL.revokeObjectURL(url)
    }
  },
  beforeDestroy() {
    if (this.eventSource) {
      this.eventSource.close()
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  padding: 20px;

  .tool-card {
    ::v-deep .el-card__header {
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
  }

  .connection-panel {
    display: flex;
    gap: 10px;

    .url-input {
      flex: 1;
    }
  }

  .status-bar {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px;
    background: #f5f7fa;
    border-radius: 4px;

    .status-label {
      font-weight: bold;
    }

    .connection-info {
      color: #909399;
      font-size: 13px;
    }
  }

  .config-panel,
  .events-panel {
    border: 1px solid #ebeef5;
    border-radius: 4px;
    overflow: hidden;

    .panel-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 10px 15px;
      background: #f5f7fa;
      border-bottom: 1px solid #ebeef5;
      font-weight: bold;
    }
  }

  .config-panel {
    .headers-editor {
      .header-row {
        display: flex;
        gap: 5px;
        margin-bottom: 5px;
      }
    }
  }

  .events-panel {
    .events-container {
      height: 350px;
      overflow-y: auto;
      padding: 10px;
      background: #fafafa;

      .event-item {
        margin-bottom: 10px;
        padding: 10px;
        border-radius: 4px;
        background: #fff;
        border-left: 3px solid #409eff;

        &.error {
          border-left-color: #f56c6c;
          background: #fef0f0;
        }

        &.connected {
          border-left-color: #67c23a;
        }

        &.disconnected {
          border-left-color: #e6a23c;
        }

        .event-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 5px;

          .event-time {
            font-size: 12px;
            color: #909399;
          }
        }

        .event-content {
          font-size: 13px;
          word-break: break-all;

          pre {
            margin: 0;
            white-space: pre-wrap;
            font-family: 'Courier New', monospace;
            font-size: 12px;
          }
        }
      }

      .no-events {
        text-align: center;
        color: #909399;
        padding: 40px;
      }
    }
  }

  .quick-urls {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px;
    background: #f5f7fa;
    border-radius: 4px;

    .label {
      font-weight: bold;
    }
  }
}
</style>
