<template>
  <div class="flexbox-tool">
    <el-card>
      <div slot="header">
        <span>Flexbox 布局生成器</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form :model="flexConfig" label-width="120px">
            <el-form-item label="flex-direction">
              <el-radio-group v-model="flexConfig.direction">
                <el-radio-button label="row">row</el-radio-button>
                <el-radio-button label="row-reverse">row-reverse</el-radio-button>
                <el-radio-button label="column">column</el-radio-button>
                <el-radio-button label="column-reverse">column-reverse</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="justify-content">
              <el-radio-group v-model="flexConfig.justify">
                <el-radio-button label="flex-start">flex-start</el-radio-button>
                <el-radio-button label="center">center</el-radio-button>
                <el-radio-button label="flex-end">flex-end</el-radio-button>
                <el-radio-button label="space-between">space-between</el-radio-button>
                <el-radio-button label="space-around">space-around</el-radio-button>
                <el-radio-button label="space-evenly">space-evenly</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="align-items">
              <el-radio-group v-model="flexConfig.alignItems">
                <el-radio-button label="flex-start">flex-start</el-radio-button>
                <el-radio-button label="center">center</el-radio-button>
                <el-radio-button label="flex-end">flex-end</el-radio-button>
                <el-radio-button label="stretch">stretch</el-radio-button>
                <el-radio-button label="baseline">baseline</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="flex-wrap">
              <el-radio-group v-model="flexConfig.wrap">
                <el-radio-button label="nowrap">nowrap</el-radio-button>
                <el-radio-button label="wrap">wrap</el-radio-button>
                <el-radio-button label="wrap-reverse">wrap-reverse</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="align-content">
              <el-radio-group v-model="flexConfig.alignContent">
                <el-radio-button label="flex-start">flex-start</el-radio-button>
                <el-radio-button label="center">center</el-radio-button>
                <el-radio-button label="flex-end">flex-end</el-radio-button>
                <el-radio-button label="space-between">space-between</el-radio-button>
                <el-radio-button label="space-around">space-around</el-radio-button>
                <el-radio-button label="stretch">stretch</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="gap">
              <el-slider v-model="flexConfig.gap" :max="50" show-input />
            </el-form-item>

            <el-form-item>
              <el-button type="primary" @click="copyCss">复制CSS</el-button>
              <el-button @click="reset">重置</el-button>
            </el-form-item>
          </el-form>
        </el-col>

        <el-col :span="12">
          <div class="preview-section">
            <div class="preview-container" :style="containerStyle">
              <div v-for="i in 6" :key="i" class="preview-item" :style="itemStyle">
                {{ i }}
              </div>
            </div>
            <div class="css-output">
              <pre><code>{{ cssCode }}</code></pre>
            </div>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'FlexboxTool',
  data() {
    return {
      flexConfig: {
        direction: 'row',
        justify: 'flex-start',
        alignItems: 'stretch',
        wrap: 'nowrap',
        alignContent: 'stretch',
        gap: 10
      }
    }
  },
  computed: {
    containerStyle() {
      return {
        display: 'flex',
        flexDirection: this.flexConfig.direction,
        justifyContent: this.flexConfig.justify,
        alignItems: this.flexConfig.alignItems,
        flexWrap: this.flexConfig.wrap,
        alignContent: this.flexConfig.alignContent,
        gap: `${this.flexConfig.gap}px`
      }
    },
    itemStyle() {
      return {
        minWidth: '60px',
        minHeight: '60px'
      }
    },
    cssCode() {
      return `.container {
  display: flex;
  flex-direction: ${this.flexConfig.direction};
  justify-content: ${this.flexConfig.justify};
  align-items: ${this.flexConfig.alignItems};
  flex-wrap: ${this.flexConfig.wrap};
  align-content: ${this.flexConfig.alignContent};
  gap: ${this.flexConfig.gap}px;
}`
    }
  },
  methods: {
    copyCss() {
      navigator.clipboard.writeText(this.cssCode).then(() => {
        this.$message.success('CSS已复制')
      })
    },
    reset() {
      this.flexConfig = {
        direction: 'row',
        justify: 'flex-start',
        alignItems: 'stretch',
        wrap: 'nowrap',
        alignContent: 'stretch',
        gap: 10
      }
    }
  }
}
</script>

<style scoped>
.flexbox-tool {
  padding: 20px;
}

.preview-section {
  text-align: center;
}

.preview-container {
  min-height: 300px;
  background: #f5f7fa;
  border: 2px dashed #dcdfe6;
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 20px;
}

.preview-item {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  font-weight: bold;
  border-radius: 8px;
}

.css-output {
  background: #f5f7fa;
  padding: 15px;
  border-radius: 4px;
  text-align: left;
}

.css-output pre {
  margin: 0;
  font-family: monospace;
  font-size: 13px;
  line-height: 1.6;
}
</style>
