<template>
  <div class="pdf-preview-tool">
    <el-card>
      <div slot="header">
        <span>PDF 预览工具</span>
        <el-tag v-if="!backendAvailable" type="warning" style="margin-left: 10px">需要后端服务</el-tag>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <div class="upload-area" @click="triggerUpload" @drop.prevent="handleDrop" @dragover.prevent>
            <input type="file" ref="fileInput" @change="handleFileSelect" accept=".pdf" style="display: none" />
            <div v-if="!pdfFile" class="upload-placeholder">
              <i class="el-icon-document" style="font-size: 48px; color: #909399"></i>
              <p>点击或拖拽PDF文件到此处</p>
              <p style="color: #909399; font-size: 12px">支持 .pdf 格式</p>
            </div>
            <div v-else class="file-info">
              <i class="el-icon-document" style="font-size: 48px; color: #409EFF"></i>
              <p>{{ pdfFile.name }}</p>
              <p style="color: #909399; font-size: 12px">{{ formatFileSize(pdfFile.size) }}</p>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-divider v-if="pdfFile">预览设置</el-divider>

      <el-form v-if="pdfFile" label-width="100px">
        <el-row :gutter="20">
          <el-col :span="6">
            <el-form-item label="当前页">
              <el-input-number v-model="currentPage" :min="1" :max="totalPages" @change="renderPage" />
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="缩放比例">
              <el-select v-model="scale" @change="renderPage">
                <el-option label="50%" :value="0.5" />
                <el-option label="75%" :value="0.75" />
                <el-option label="100%" :value="1" />
                <el-option label="125%" :value="1.25" />
                <el-option label="150%" :value="1.5" />
                <el-option label="200%" :value="2" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="总页数">
              <el-tag>{{ totalPages }} 页</el-tag>
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item>
              <el-button-group>
                <el-button @click="prevPage" :disabled="currentPage <= 1">
                  <i class="el-icon-arrow-left"></i> 上一页
                </el-button>
                <el-button @click="nextPage" :disabled="currentPage >= totalPages">
                  下一页 <i class="el-icon-arrow-right"></i>
                </el-button>
              </el-button-group>
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <div v-if="pdfFile" class="preview-container">
        <canvas ref="pdfCanvas" class="pdf-canvas"></canvas>
      </div>

      <el-divider v-if="pdfFile">操作</el-divider>

      <el-form v-if="pdfFile" label-width="100px">
        <el-form-item>
          <el-button type="primary" @click="downloadPage">下载当前页</el-button>
          <el-button type="success" @click="downloadAll">下载全部图片</el-button>
          <el-button @click="clearAll">清空</el-button>
        </el-form-item>
      </el-form>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'PdfPreviewTool',
  data() {
    return {
      backendAvailable: false,
      pdfFile: null,
      pdfDoc: null,
      currentPage: 1,
      totalPages: 0,
      scale: 1,
      pageImages: []
    }
  },
  async mounted() {
    await this.checkBackend()
    this.loadPdfJs()
  },
  methods: {
    async checkBackend() {
      try {
        const response = await fetch('/api/ping', { 
          method: 'GET',
          signal: AbortSignal.timeout(3000)
        })
        this.backendAvailable = response.ok
      } catch (e) {
        this.backendAvailable = false
      }
    },
    loadPdfJs() {
      if (window.pdfjsLib) return
      
      const script = document.createElement('script')
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js'
      script.onload = () => {
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'
      }
      document.head.appendChild(script)
    },
    triggerUpload() {
      this.$refs.fileInput.click()
    },
    handleFileSelect(e) {
      const file = e.target.files[0]
      if (file) {
        this.loadPdf(file)
      }
    },
    handleDrop(e) {
      const file = e.dataTransfer.files[0]
      if (file && file.name.endsWith('.pdf')) {
        this.loadPdf(file)
      }
    },
    async loadPdf(file) {
      this.pdfFile = file
      
      if (!window.pdfjsLib) {
        this.$message.warning('PDF.js 正在加载，请稍后重试')
        setTimeout(() => this.loadPdf(file), 1000)
        return
      }

      try {
        const arrayBuffer = await file.arrayBuffer()
        this.pdfDoc = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise
        this.totalPages = this.pdfDoc.numPages
        this.currentPage = 1
        this.pageImages = []
        this.renderPage()
      } catch (error) {
        this.$message.error('PDF 加载失败: ' + error.message)
      }
    },
    async renderPage() {
      if (!this.pdfDoc) return

      try {
        const page = await this.pdfDoc.getPage(this.currentPage)
        const canvas = this.$refs.pdfCanvas
        const ctx = canvas.getContext('2d')
        
        const viewport = page.getViewport({ scale: this.scale })
        canvas.width = viewport.width
        canvas.height = viewport.height

        await page.render({
          canvasContext: ctx,
          viewport: viewport
        }).promise
      } catch (error) {
        this.$message.error('页面渲染失败: ' + error.message)
      }
    },
    prevPage() {
      if (this.currentPage > 1) {
        this.currentPage--
        this.renderPage()
      }
    },
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++
        this.renderPage()
      }
    },
    downloadPage() {
      const canvas = this.$refs.pdfCanvas
      const link = document.createElement('a')
      link.download = `${this.pdfFile.name}_page_${this.currentPage}.png`
      link.href = canvas.toDataURL('image/png')
      link.click()
    },
    async downloadAll() {
      this.$message.info('正在生成所有页面图片...')
      
      for (let i = 1; i <= this.totalPages; i++) {
        this.currentPage = i
        await this.renderPage()
        await new Promise(resolve => setTimeout(resolve, 100))
        this.downloadPage()
        await new Promise(resolve => setTimeout(resolve, 300))
      }
      
      this.$message.success('下载完成')
    },
    formatFileSize(bytes) {
      if (bytes < 1024) return bytes + ' B'
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB'
      return (bytes / (1024 * 1024)).toFixed(2) + ' MB'
    },
    clearAll() {
      this.pdfFile = null
      this.pdfDoc = null
      this.currentPage = 1
      this.totalPages = 0
      this.pageImages = []
      this.$refs.fileInput.value = ''
    }
  }
}
</script>

<style scoped>
.pdf-preview-tool {
  padding: 20px;
}

.upload-area {
  border: 2px dashed #dcdfe6;
  border-radius: 8px;
  min-height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color 0.3s;
}

.upload-area:hover {
  border-color: #409EFF;
}

.upload-placeholder,
.file-info {
  text-align: center;
  color: #909399;
}

.preview-container {
  margin-top: 20px;
  text-align: center;
  overflow: auto;
  max-height: 600px;
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  padding: 20px;
  background: #f5f7fa;
}

.pdf-canvas {
  max-width: 100%;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);
}
</style>
