<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>XML 格式化</span>
        <el-button size="small" @click="clear">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <div class="input-section">
            <div class="section-header">
              <span>XML 内容</span>
              <el-tag size="mini" type="info">输入或粘贴 XML，点击按钮格式化</el-tag>
            </div>
            <el-input
              v-model="xmlText"
              type="textarea"
              :rows="15"
              placeholder="输入 XML，如: <root><name>张三</name><age>25</age></root>"
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px">
        <el-col :span="24" class="action-row">
          <el-radio-group v-model="indent" size="small">
            <el-radio-button :label="2">2空格</el-radio-button>
            <el-radio-button :label="4">4空格</el-radio-button>
            <el-radio-button :label="1">Tab</el-radio-button>
          </el-radio-group>
          
          <div class="action-buttons">
            <el-button type="primary" @click="format">格式化</el-button>
            <el-button type="warning" @click="compress">压缩</el-button>
            <el-button type="info" @click="validate">验证</el-button>
            <el-button @click="copy">复制</el-button>
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px" v-if="error">
        <el-col :span="24">
          <el-alert type="error" :closable="false" show-icon>
            <template slot="title">{{ error }}</template>
          </el-alert>
        </el-col>
      </el-row>

      <el-row style="margin-top: 15px" v-if="stats">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">XML 统计</div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="元素数">{{ stats.elements }}</el-descriptions-item>
              <el-descriptions-item label="属性数">{{ stats.attributes }}</el-descriptions-item>
              <el-descriptions-item label="文本节点">{{ stats.textNodes }}</el-descriptions-item>
              <el-descriptions-item label="字符数">{{ stats.chars }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'XmlTool',
  data() {
    return {
      xmlText: '',
      indent: 2,
      error: '',
      stats: null
    }
  },
  methods: {
    format() {
      if (!this.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }
      
      try {
        this.xmlText = this.formatXml(this.xmlText)
        this.error = ''
        this.updateStats()
        this.$message.success('格式化成功')
      } catch (e) {
        this.error = 'XML 格式错误: ' + e.message
        this.stats = null
      }
    },
    formatXml(xml) {
      const PADDING = this.indent === 1 ? '\t' : ' '.repeat(this.indent)
      let formatted = ''
      let pad = 0
      
      xml = xml.replace(/(>)(<)(\/*)/g, '$1\n$2$3')
      xml.split('\n').forEach((node) => {
        let indent = 0
        if (node.match(/.+<\/\w[^>]*>$/)) {
          indent = 0
        } else if (node.match(/^<\/\w/)) {
          if (pad !== 0) pad -= 1
        } else if (node.match(/^<\w([^>]*[^\/])?>.*$/)) {
          indent = 1
        }
        
        formatted += PADDING.repeat(pad) + node + '\n'
        pad += indent
      })
      
      return formatted.trim()
    },
    compress() {
      if (!this.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }
      
      try {
        this.xmlText = this.xmlText
          .replace(/\n/g, '')
          .replace(/\s{2,}/g, ' ')
          .replace(/>\s+</g, '><')
          .trim()
        this.error = ''
        this.updateStats()
        this.$message.success('压缩成功')
      } catch (e) {
        this.error = '压缩失败: ' + e.message
      }
    },
    validate() {
      if (!this.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }
      
      try {
        const parser = new DOMParser()
        const doc = parser.parseFromString(this.xmlText, 'text/xml')
        const errorNode = doc.querySelector('parsererror')
        
        if (errorNode) {
          this.error = 'XML 格式错误: ' + errorNode.textContent
        } else {
          this.error = ''
          this.$message.success('XML 格式正确')
        }
      } catch (e) {
        this.error = 'XML 格式错误: ' + e.message
      }
    },
    updateStats() {
      const parser = new DOMParser()
      const doc = parser.parseFromString(this.xmlText, 'text/xml')
      
      const elements = doc.getElementsByTagName('*').length
      const textNodes = this.countTextNodes(doc.documentElement)
      
      let attributes = 0
      const allElements = doc.getElementsByTagName('*')
      for (let i = 0; i < allElements.length; i++) {
        attributes += allElements[i].attributes.length
      }
      
      this.stats = {
        elements,
        attributes,
        textNodes,
        chars: this.xmlText.length
      }
    },
    countTextNodes(node) {
      let count = 0
      if (node && node.childNodes) {
        for (let i = 0; i < node.childNodes.length; i++) {
          const child = node.childNodes[i]
          if (child.nodeType === 3 && child.textContent.trim()) {
            count++
          } else if (child.nodeType === 1) {
            count += this.countTextNodes(child)
          }
        }
      }
      return count
    },
    copy() {
      if (!this.xmlText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.xmlText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      this.xmlText = ''
      this.error = ''
      this.stats = null
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;
    }
  }

  .action-row {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .action-buttons {
      display: flex;
      gap: 10px;
    }
  }
}
</style>
