<template>
  <div class="color-palette-tool">
    <el-card>
      <div slot="header">
        <span>调色板生成器</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="100px">
            <el-form-item label="生成方式">
              <el-select v-model="palette.type" style="width: 100%" @change="generatePalette">
                <el-option label="随机调色板" value="random" />
                <el-option label="互补色" value="complementary" />
                <el-option label="类似色" value="analogous" />
                <el-option label="三角色" value="triadic" />
                <el-option label="分裂互补" value="split-complementary" />
                <el-option label="四角色" value="tetradic" />
                <el-option label="渐变色" value="gradient" />
                <el-option label="从图片提取" value="image" />
              </el-select>
            </el-form-item>

            <el-form-item label="基础颜色" v-if="palette.type !== 'random' && palette.type !== 'gradient' && palette.type !== 'image'">
              <el-color-picker v-model="palette.baseColor" @change="generatePalette" />
              <el-input v-model="palette.baseColor" style="width: 120px; margin-left: 10px" @change="generatePalette" />
            </el-form-item>

            <el-form-item label="颜色数量" v-if="palette.type === 'random' || palette.type === 'gradient'">
              <el-slider v-model="palette.count" :min="2" :max="10" @change="generatePalette" />
            </el-form-item>

            <el-form-item label="起始颜色" v-if="palette.type === 'gradient'">
              <el-color-picker v-model="palette.startColor" @change="generatePalette" />
            </el-form-item>

            <el-form-item label="结束颜色" v-if="palette.type === 'gradient'">
              <el-color-picker v-model="palette.endColor" @change="generatePalette" />
            </el-form-item>

            <el-form-item label="上传图片" v-if="palette.type === 'image'">
              <el-upload
                action="#"
                :auto-upload="false"
                :show-file-list="false"
                accept="image/*"
                @change="handleImageUpload"
              >
                <el-button size="small" type="primary">选择图片</el-button>
              </el-upload>
            </el-form-item>
          </el-form>

          <el-divider>调色板</el-divider>
          <div class="palette-display">
            <div 
              v-for="(color, index) in colors" 
              :key="index" 
              class="color-item"
              :style="{ backgroundColor: color }"
              @click="copyColor(color)"
            >
              <div class="color-info">
                <span class="color-hex">{{ color }}</span>
              </div>
            </div>
          </div>
        </el-col>

        <el-col :span="12">
          <el-divider>颜色详情</el-divider>
          <el-table :data="colorDetails" border size="small">
            <el-table-column label="颜色" width="60">
              <template slot-scope="scope">
                <div class="color-preview" :style="{ backgroundColor: scope.row.hex }"></div>
              </template>
            </el-table-column>
            <el-table-column prop="hex" label="HEX" width="90" />
            <el-table-column prop="rgb" label="RGB" width="120" />
            <el-table-column prop="hsl" label="HSL" />
            <el-table-column label="操作" width="80">
              <template slot-scope="scope">
                <el-button type="text" size="small" @click="copyColor(scope.row.hex)">复制</el-button>
              </template>
            </el-table-column>
          </el-table>

          <el-divider>导出</el-divider>
          <el-form label-width="80px">
            <el-form-item label="格式">
              <el-select v-model="exportFormat" style="width: 200px">
                <el-option label="CSS 变量" value="css" />
                <el-option label="SCSS 变量" value="scss" />
                <el-option label="JSON" value="json" />
                <el-option label="Tailwind 配置" value="tailwind" />
              </el-select>
            </el-form-item>
          </el-form>
          <el-input
            type="textarea"
            :rows="10"
            :value="exportCode"
            readonly
          />
          <div style="margin-top: 10px">
            <el-button type="primary" @click="copyExport">复制代码</el-button>
          </div>

          <el-divider>预设调色板</el-divider>
          <div class="preset-palettes">
            <div 
              v-for="(preset, index) in presetPalettes" 
              :key="index" 
              class="preset-item"
              @click="applyPreset(preset)"
            >
              <div class="preset-colors">
                <div 
                  v-for="(color, cIndex) in preset.colors" 
                  :key="cIndex"
                  class="preset-color"
                  :style="{ backgroundColor: color }"
                ></div>
              </div>
              <span class="preset-name">{{ preset.name }}</span>
            </div>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ColorPaletteTool',
  data() {
    return {
      palette: {
        type: 'random',
        baseColor: '#409EFF',
        startColor: '#409EFF',
        endColor: '#67C23A',
        count: 5
      },
      colors: [],
      exportFormat: 'css',
      presetPalettes: [
        { name: '海洋', colors: ['#0077b6', '#00b4d8', '#90e0ef', '#caf0f8', '#03045e'] },
        { name: '日落', colors: ['#ff6b6b', '#feca57', '#ff9ff3', '#54a0ff', '#5f27cd'] },
        { name: '森林', colors: ['#2d6a4f', '#40916c', '#52b788', '#74c69d', '#95d5b2'] },
        { name: '糖果', colors: ['#ffadad', '#ffd6a5', '#fdffb6', '#caffbf', '#9bf6ff'] },
        { name: '复古', colors: ['#264653', '#2a9d8f', '#e9c46a', '#f4a261', '#e76f51'] }
      ]
    }
  },
  computed: {
    colorDetails() {
      return this.colors.map(color => {
        const rgb = this.hexToRgb(color)
        const hsl = this.rgbToHsl(rgb.r, rgb.g, rgb.b)
        return {
          hex: color,
          rgb: `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`,
          hsl: `hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)`
        }
      })
    },
    exportCode() {
      switch (this.exportFormat) {
        case 'css':
          return this.colors.map((c, i) => `--color-${i + 1}: ${c};`).join('\n')
        case 'scss':
          return this.colors.map((c, i) => `$color-${i + 1}: ${c};`).join('\n')
        case 'json':
          return JSON.stringify({ colors: this.colors }, null, 2)
        case 'tailwind':
          return `colors: {\n${this.colors.map((c, i) => `  'color-${i + 1}': '${c}',`).join('\n')}\n}`
        default:
          return ''
      }
    }
  },
  mounted() {
    this.generatePalette()
  },
  methods: {
    generatePalette() {
      switch (this.palette.type) {
        case 'random':
          this.colors = this.generateRandomPalette(this.palette.count)
          break
        case 'complementary':
          this.colors = this.generateComplementary(this.palette.baseColor)
          break
        case 'analogous':
          this.colors = this.generateAnalogous(this.palette.baseColor)
          break
        case 'triadic':
          this.colors = this.generateTriadic(this.palette.baseColor)
          break
        case 'split-complementary':
          this.colors = this.generateSplitComplementary(this.palette.baseColor)
          break
        case 'tetradic':
          this.colors = this.generateTetradic(this.palette.baseColor)
          break
        case 'gradient':
          this.colors = this.generateGradient(this.palette.startColor, this.palette.endColor, this.palette.count)
          break
        case 'image':
          break
      }
    },
    generateRandomPalette(count) {
      const colors = []
      for (let i = 0; i < count; i++) {
        colors.push('#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0'))
      }
      return colors
    },
    generateComplementary(baseColor) {
      const hsl = this.hexToHsl(baseColor)
      return [
        baseColor,
        this.hslToHex((hsl.h + 180) % 360, hsl.s, hsl.l)
      ]
    },
    generateAnalogous(baseColor) {
      const hsl = this.hexToHsl(baseColor)
      return [
        this.hslToHex((hsl.h - 30 + 360) % 360, hsl.s, hsl.l),
        baseColor,
        this.hslToHex((hsl.h + 30) % 360, hsl.s, hsl.l)
      ]
    },
    generateTriadic(baseColor) {
      const hsl = this.hexToHsl(baseColor)
      return [
        baseColor,
        this.hslToHex((hsl.h + 120) % 360, hsl.s, hsl.l),
        this.hslToHex((hsl.h + 240) % 360, hsl.s, hsl.l)
      ]
    },
    generateSplitComplementary(baseColor) {
      const hsl = this.hexToHsl(baseColor)
      return [
        baseColor,
        this.hslToHex((hsl.h + 150) % 360, hsl.s, hsl.l),
        this.hslToHex((hsl.h + 210) % 360, hsl.s, hsl.l)
      ]
    },
    generateTetradic(baseColor) {
      const hsl = this.hexToHsl(baseColor)
      return [
        baseColor,
        this.hslToHex((hsl.h + 90) % 360, hsl.s, hsl.l),
        this.hslToHex((hsl.h + 180) % 360, hsl.s, hsl.l),
        this.hslToHex((hsl.h + 270) % 360, hsl.s, hsl.l)
      ]
    },
    generateGradient(startColor, endColor, count) {
      const colors = []
      const start = this.hexToRgb(startColor)
      const end = this.hexToRgb(endColor)
      
      for (let i = 0; i < count; i++) {
        const ratio = i / (count - 1)
        const r = Math.round(start.r + (end.r - start.r) * ratio)
        const g = Math.round(start.g + (end.g - start.g) * ratio)
        const b = Math.round(start.b + (end.b - start.b) * ratio)
        colors.push(this.rgbToHex(r, g, b))
      }
      
      return colors
    },
    hexToRgb(hex) {
      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
      return result ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16)
      } : { r: 0, g: 0, b: 0 }
    },
    rgbToHex(r, g, b) {
      return '#' + [r, g, b].map(x => x.toString(16).padStart(2, '0')).join('')
    },
    hexToHsl(hex) {
      const rgb = this.hexToRgb(hex)
      return this.rgbToHsl(rgb.r, rgb.g, rgb.b)
    },
    rgbToHsl(r, g, b) {
      r /= 255; g /= 255; b /= 255
      const max = Math.max(r, g, b), min = Math.min(r, g, b)
      let h, s, l = (max + min) / 2

      if (max === min) {
        h = s = 0
      } else {
        const d = max - min
        s = l > 0.5 ? d / (2 - max - min) : d / (max + min)
        switch (max) {
          case r: h = ((g - b) / d + (g < b ? 6 : 0)) / 6; break
          case g: h = ((b - r) / d + 2) / 6; break
          case b: h = ((r - g) / d + 4) / 6; break
        }
      }

      return { h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100) }
    },
    hslToHex(h, s, l) {
      s /= 100; l /= 100
      const a = s * Math.min(l, 1 - l)
      const f = n => {
        const k = (n + h / 30) % 12
        const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1)
        return Math.round(255 * color).toString(16).padStart(2, '0')
      }
      return `#${f(0)}${f(8)}${f(4)}`
    },
    handleImageUpload(file) {
      const reader = new FileReader()
      reader.onload = (e) => {
        const img = new Image()
        img.onload = () => {
          const canvas = document.createElement('canvas')
          const ctx = canvas.getContext('2d')
          canvas.width = img.width
          canvas.height = img.height
          ctx.drawImage(img, 0, 0)
          
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height)
          const colors = this.extractColors(imageData, 5)
          this.colors = colors
        }
        img.src = e.target.result
      }
      reader.readAsDataURL(file.raw)
    },
    extractColors(imageData, count) {
      const colorMap = {}
      const data = imageData.data
      
      for (let i = 0; i < data.length; i += 40) {
        const r = data[i]
        const g = data[i + 1]
        const b = data[i + 2]
        const key = `${Math.round(r / 32) * 32},${Math.round(g / 32) * 32},${Math.round(b / 32) * 32}`
        colorMap[key] = (colorMap[key] || 0) + 1
      }
      
      const sorted = Object.entries(colorMap).sort((a, b) => b[1] - a[1])
      return sorted.slice(0, count).map(([key]) => {
        const [r, g, b] = key.split(',').map(Number)
        return this.rgbToHex(r, g, b)
      })
    },
    copyColor(color) {
      navigator.clipboard.writeText(color).then(() => {
        this.$message.success(`已复制: ${color}`)
      })
    },
    copyExport() {
      navigator.clipboard.writeText(this.exportCode).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    applyPreset(preset) {
      this.colors = [...preset.colors]
    }
  }
}
</script>

<style scoped>
.color-palette-tool {
  padding: 20px;
}

.palette-display {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.color-item {
  width: 80px;
  height: 80px;
  border-radius: 8px;
  cursor: pointer;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  transition: transform 0.2s;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.color-item:hover {
  transform: scale(1.05);
}

.color-info {
  background: rgba(0, 0, 0, 0.5);
  padding: 4px 8px;
  border-radius: 0 0 8px 8px;
  width: 100%;
  text-align: center;
}

.color-hex {
  color: white;
  font-size: 11px;
  font-family: monospace;
}

.color-preview {
  width: 30px;
  height: 30px;
  border-radius: 4px;
  border: 1px solid #dcdfe6;
}

.preset-palettes {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.preset-item {
  cursor: pointer;
  padding: 5px;
  border-radius: 8px;
  border: 1px solid #ebeef5;
  transition: all 0.3s;
}

.preset-item:hover {
  border-color: #409eff;
}

.preset-colors {
  display: flex;
  gap: 2px;
  margin-bottom: 5px;
}

.preset-color {
  width: 20px;
  height: 20px;
  border-radius: 4px;
}

.preset-name {
  font-size: 12px;
  color: #606266;
}
</style>
