<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>JavaScript 混淆器</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="editor-header">
            <span>源代码</span>
            <el-button-group>
              <el-button size="small" @click="loadExample">加载示例</el-button>
              <el-button size="small" @click="formatCode">格式化</el-button>
            </el-button-group>
          </div>
          <el-input
            v-model="sourceCode"
            type="textarea"
            :rows="18"
            placeholder="输入 JavaScript 代码..."
          />
        </el-col>
        <el-col :span="12">
          <div class="editor-header">
            <span>输出结果</span>
            <el-button-group>
              <el-button size="small" @click="copyResult" :disabled="!resultCode">复制</el-button>
              <el-button size="small" @click="downloadResult" :disabled="!resultCode">下载</el-button>
            </el-button-group>
          </div>
          <el-input
            v-model="resultCode"
            type="textarea"
            :rows="18"
            readonly
            placeholder="混淆后的代码将显示在这里..."
          />
          <div class="result-info" v-if="resultCode">
            <el-tag size="small">原始: {{ sourceCode.length }} 字符</el-tag>
            <el-tag size="small" type="warning" style="margin-left: 10px">
              混淆: {{ resultCode.length }} 字符
            </el-tag>
            <el-tag size="small" type="info" style="margin-left: 10px">
              {{ ((1 - resultCode.length / Math.max(sourceCode.length, 1)) * 100).toFixed(1) }}%
            </el-tag>
          </div>
        </el-col>
      </el-row>

      <el-divider>混淆选项</el-divider>

      <el-form label-width="140px" :inline="true">
        <el-form-item label="控制流平坦化">
          <el-switch v-model="options.controlFlowFlattening" />
        </el-form-item>
        <el-form-item label="死代码注入">
          <el-switch v-model="options.deadCodeInjection" />
        </el-form-item>
        <el-form-item label="字符串数组化">
          <el-switch v-model="options.stringArray" />
        </el-form-item>
        <el-form-item label="字符串编码">
          <el-select v-model="options.stringArrayEncoding" size="small" style="width: 100px" :disabled="!options.stringArray">
            <el-option label="无" value="" />
            <el-option label="Base64" value="base64" />
            <el-option label="RC4" value="rc4" />
          </el-select>
        </el-form-item>
        <el-form-item label="变量名混淆">
          <el-switch v-model="options.renameGlobals" />
        </el-form-item>
        <el-form-item label="自我保护">
          <el-switch v-model="options.selfDefending" />
        </el-form-item>
        <el-form-item label="调试保护">
          <el-switch v-model="options.debugProtection" />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="obfuscate" :loading="processing">混淆代码</el-button>
        </el-form-item>
      </el-form>

      <el-divider v-if="error">错误</el-divider>
      <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CodeObfuscatorTool',
  data() {
    return {
      sourceCode: '',
      resultCode: '',
      processing: false,
      error: '',
      options: {
        controlFlowFlattening: false,
        deadCodeInjection: false,
        stringArray: true,
        stringArrayEncoding: 'base64',
        renameGlobals: false,
        selfDefending: false,
        debugProtection: false,
      }
    }
  },
  methods: {
    obfuscate() {
      if (!this.sourceCode.trim()) {
        this.$message.warning('请输入要混淆的代码')
        return
      }

      this.processing = true
      this.error = ''

      try {
        this.resultCode = this.simpleObfuscate(this.sourceCode)
        this.$message.success('混淆完成')
      } catch (e) {
        this.error = e.message || '混淆失败'
        this.resultCode = ''
      } finally {
        this.processing = false
      }
    },

    simpleObfuscate(code) {
      let result = code

      // 移除注释
      result = result.replace(/\/\*[\s\S]*?\*\//g, '')
      result = result.replace(/\/\/.*/g, '')

      // 字符串数组化
      if (this.options.stringArray) {
        const strings = []
        result = result.replace(/"([^"\\]*(\\.[^"\\]*)*)"/g, (match, str) => {
          strings.push(str)
          return '"_0x' + (strings.length - 1).toString(36) + '"'
        })
        result = result.replace(/'([^'\\]*(\\.[^'\\]*)*)'/g, (match, str) => {
          strings.push(str)
          return "'_0x" + (strings.length - 1).toString(36) + "'"
        })

        if (strings.length > 0) {
          let mapping = ''
          if (this.options.stringArrayEncoding === 'base64') {
            mapping = strings.map(s => btoa(unescape(encodeURIComponent(s)))).join(',')
            result = ';(function(){var _s=[' + mapping + '].map(function(s){return decodeURIComponent(escape(atob(s)))});\n' + result + '\n})();'
          } else if (this.options.stringArrayEncoding === 'rc4') {
            const key = Math.random().toString(36).slice(2, 10)
            mapping = strings.map(s => {
              let r = ''
              for (let i = 0; i < s.length; i++) {
                r += String.fromCharCode(s.charCodeAt(i) ^ key.charCodeAt(i % key.length))
              }
              return btoa(unescape(encodeURIComponent(r)))
            }).join(',')
            result = ';(function(){var _k="' + key + '";var _s=[' + mapping + '].map(function(s){var r=decodeURIComponent(escape(atob(s)));var o="";for(var i=0;i<r.length;i++)o+=String.fromCharCode(r.charCodeAt(i)^_k.charCodeAt(i%_k.length));return o});\n' + result + '\n})();'
          } else {
            mapping = strings.map(s => JSON.stringify(s)).join(',')
            result = ';(function(){var _s=[' + mapping + '];\n' + result + '\n})();'
          }

          // 替换字符串引用
          result = result.replace(/"_0x([0-9a-z]+)"/g, '_s[parseInt("$1",36)]')
          result = result.replace(/'_0x([0-9a-z]+)'/g, '_s[parseInt("$1",36)]')
        }
      }

      // 变量名混淆 (简单替换常见变量名)
      if (this.options.renameGlobals) {
        const varNames = new Map()
        let counter = 0
        result = result.replace(/\b(var|let|const)\s+([a-zA-Z_$][\w$]*)/g, (match, keyword, name) => {
          if (!varNames.has(name) && name.length > 1 && !['this', 'new', 'return', 'class', 'function', 'true', 'false', 'null', 'undefined', 'if', 'else', 'for', 'while', 'do', 'switch', 'case', 'break', 'continue', 'try', 'catch', 'finally', 'throw', 'typeof', 'instanceof', 'in', 'of', 'import', 'export', 'default', 'from', 'as'].includes(name)) {
            varNames.set(name, '_' + (counter++).toString(36))
          }
          return keyword + ' ' + (varNames.get(name) || name)
        })
        for (const [old, newName] of varNames) {
          const regex = new RegExp('\\b' + old + '\\b', 'g')
          result = result.replace(regex, newName)
        }
      }

      // 控制流平坦化简化版
      if (this.options.controlFlowFlattening) {
        const lines = result.split('\n').filter(l => l.trim())
        if (lines.length > 3) {
          result = ';(function(){\nvar _f=[' + lines.length + '];\nfor(var i=0;i<_f.length;i++)_f[i]=function(){\n' +
            lines.map((l, i) => 'if(i===' + i + '){' + l.trim() + (l.trim().endsWith(';') || l.trim().endsWith('{') || l.trim().endsWith('}') ? '' : ';') + '}').join('\n') +
            '\n};\nfor(var i=0;i<_f.length;i++)_f[i]();\n})();'
        }
      }

      // 死代码注入
      if (this.options.deadCodeInjection) {
        const deadCode = ';(function(){if(typeof _xyz==="undefined"){var _xyz=Date.now()^Math.random();while(_xyz-->0){};}})();'
        result = deadCode + '\n' + result
      }

      // 调试保护
      if (this.options.debugProtection) {
        result = ';(function(){var _d=setInterval(function(){debugger;},100);setTimeout(function(){clearInterval(_d);},5000);})();\n' + result
      }

      // 自我保护
      if (this.options.selfDefending) {
        result = ';(function(){var _t=' + Date.now() + ';if((Date.now()-_t)>5000)return;})();\n' + result
      }

      // 基础压缩
      result = result.replace(/\n\s*\n/g, '\n')
      result = result.replace(/  +/g, ' ')

      return result
    },

    formatCode() {
      try {
        this.sourceCode = this.sourceCode
          .replace(/(\{|;)\s*/g, '$1\n  ')
          .replace(/\}\s*/g, '\n}\n')
          .replace(/\n\s*\n/g, '\n')
        this.$message.success('格式化完成')
      } catch (e) {
        this.$message.warning('格式化失败')
      }
    },

    copyResult() {
      navigator.clipboard.writeText(this.resultCode).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },

    downloadResult() {
      const blob = new Blob([this.resultCode], { type: 'text/javascript' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'obfuscated.js'
      a.click()
      URL.revokeObjectURL(url)
    },

    loadExample() {
      this.sourceCode = `function fibonacci(n) {
  if (n <= 1) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    const temp = a + b;
    a = b;
    b = temp;
  }
  return b;
}

const result = fibonacci(10);
console.log("斐波那契数列第10项:", result);

// 用户数据
const user = {
  name: "张三",
  age: 28,
  email: "zhangsan@example.com"
};

console.log("用户信息:", JSON.stringify(user, null, 2));`
    },

    clearAll() {
      this.sourceCode = ''
      this.resultCode = ''
      this.error = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  padding: 20px;
}

.editor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  font-weight: bold;
}

.result-info {
  margin-top: 10px;
  text-align: right;
}
</style>
