<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Properties 多格式互转</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" type="primary" @click="convert">转换</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <el-select v-model="inputFormat" size="small" @change="onFormatChange('input')">
                <el-option label="Properties" value="properties" />
                <el-option label="YAML" value="yaml" />
                <el-option label="JSON" value="json" />
              </el-select>
              <el-button type="text" size="mini" @click="loadExample">加载示例</el-button>
            </div>
            <el-input
              v-model="inputText"
              type="textarea"
              :rows="18"
              :placeholder="getPlaceholder('input')"
            />
          </div>
        </el-col>
        
        <el-col :span="12">
          <div class="output-section">
            <div class="section-header">
              <el-select v-model="outputFormat" size="small" @change="onFormatChange('output')">
                <el-option label="Properties" value="properties" />
                <el-option label="YAML" value="yaml" />
                <el-option label="JSON" value="json" />
              </el-select>
              <div>
                <el-button type="text" size="mini" @click="swapFormat">交换</el-button>
                <el-button type="text" size="mini" @click="copyResult">复制</el-button>
                <el-button type="text" size="mini" @click="downloadResult">下载</el-button>
              </div>
            </div>
            <el-input
              v-model="outputText"
              type="textarea"
              :rows="18"
              readonly
              placeholder="转换结果将显示在这里..."
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">快速转换</div>
            <div class="quick-actions">
              <el-button-group>
                <el-button size="small" @click="quickConvert('properties', 'yaml')">Properties → YAML</el-button>
                <el-button size="small" @click="quickConvert('properties', 'json')">Properties → JSON</el-button>
              </el-button-group>
              <el-button-group>
                <el-button size="small" @click="quickConvert('yaml', 'properties')">YAML → Properties</el-button>
                <el-button size="small" @click="quickConvert('yaml', 'json')">YAML → JSON</el-button>
              </el-button-group>
              <el-button-group>
                <el-button size="small" @click="quickConvert('json', 'properties')">JSON → Properties</el-button>
                <el-button size="small" @click="quickConvert('json', 'yaml')">JSON → YAML</el-button>
              </el-button-group>
            </div>
          </el-card>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">格式说明</div>
            <el-row :gutter="20">
              <el-col :span="8">
                <div class="format-info">
                  <h4>Properties</h4>
                  <pre class="code-block"># 注释
server.port=8080
spring.application.name=demo
spring.datasource.url=jdbc:mysql://localhost</pre>
                </div>
              </el-col>
              <el-col :span="8">
                <div class="format-info">
                  <h4>YAML</h4>
                  <pre class="code-block"># 注释
server:
  port: 8080
spring:
  application:
    name: demo
  datasource:
    url: jdbc:mysql://localhost</pre>
                </div>
              </el-col>
              <el-col :span="8">
                <div class="format-info">
                  <h4>JSON</h4>
                  <pre class="code-block">{
  "server": {
    "port": 8080
  },
  "spring": {
    "application": {
      "name": "demo"
    }
  }
}</pre>
                </div>
              </el-col>
            </el-row>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'PropertiesConverterTool',
  data() {
    return {
      inputText: '',
      outputText: '',
      inputFormat: 'properties',
      outputFormat: 'yaml'
    }
  },
  methods: {
    convert() {
      if (!this.inputText.trim()) {
        this.$message.warning('请输入内容')
        return
      }

      if (this.inputFormat === this.outputFormat) {
        this.outputText = this.inputText
        return
      }

      try {
        let obj = this.parseInput()
        this.outputText = this.formatOutput(obj)
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('转换失败: ' + e.message)
      }
    },
    parseInput() {
      switch (this.inputFormat) {
        case 'properties':
          return this.parseProperties(this.inputText)
        case 'yaml':
          return this.parseYaml(this.inputText)
        case 'json':
          return JSON.parse(this.inputText)
        default:
          return {}
      }
    },
    formatOutput(obj) {
      switch (this.outputFormat) {
        case 'properties':
          return this.toProperties(obj)
        case 'yaml':
          return this.toYaml(obj, 0)
        case 'json':
          return JSON.stringify(obj, null, 2)
        default:
          return ''
      }
    },
    parseProperties(text) {
      const lines = text.split('\n')
      const result = {}
      
      lines.forEach(line => {
        line = line.trim()
        if (!line || line.startsWith('#') || line.startsWith('!')) return
        
        const equalIndex = line.indexOf('=')
        const colonIndex = line.indexOf(':')
        
        let separatorIndex = -1
        if (equalIndex !== -1 && colonIndex !== -1) {
          separatorIndex = Math.min(equalIndex, colonIndex)
        } else if (equalIndex !== -1) {
          separatorIndex = equalIndex
        } else if (colonIndex !== -1) {
          separatorIndex = colonIndex
        }
        
        if (separatorIndex === -1) return
        
        const key = line.substring(0, separatorIndex).trim()
        let value = line.substring(separatorIndex + 1).trim()
        
        value = this.unescapePropertiesValue(value)
        
        this.setNestedValue(result, key.split('.'), value)
      })
      
      return result
    },
    unescapePropertiesValue(value) {
      return value
        .replace(/\\n/g, '\n')
        .replace(/\\t/g, '\t')
        .replace(/\\r/g, '\r')
        .replace(/\\\\/g, '\\')
    },
    escapePropertiesValue(value) {
      return String(value)
        .replace(/\\/g, '\\\\')
        .replace(/\n/g, '\\n')
        .replace(/\t/g, '\\t')
        .replace(/\r/g, '\\r')
    },
    parseYaml(yaml) {
      const lines = yaml.split('\n')
      const result = {}
      const stack = [{ obj: result, indent: -1 }]
      
      lines.forEach(line => {
        if (!line.trim() || line.trim().startsWith('#')) return
        
        const indent = line.search(/\S/)
        const content = line.trim()
        
        if (content.includes(':')) {
          const colonIndex = content.indexOf(':')
          const key = content.substring(0, colonIndex).trim()
          let value = content.substring(colonIndex + 1).trim()
          
          while (stack.length > 1 && stack[stack.length - 1].indent >= indent) {
            stack.pop()
          }
          
          const current = stack[stack.length - 1].obj
          
          if (value) {
            if (value.startsWith('"') && value.endsWith('"')) {
              value = value.slice(1, -1)
            } else if (value.startsWith("'") && value.endsWith("'")) {
              value = value.slice(1, -1)
            }
            if (value === 'true' || value === 'false') {
              current[key] = value === 'true'
            } else if (!isNaN(value) && value !== '') {
              current[key] = Number(value)
            } else {
              current[key] = value
            }
          } else {
            current[key] = {}
            stack.push({ obj: current[key], indent })
          }
        } else if (content.startsWith('- ')) {
          const current = stack[stack.length - 1].obj
          const key = Object.keys(current).pop()
          if (!Array.isArray(current[key])) {
            current[key] = []
          }
          current[key].push(content.substring(2).trim())
        }
      })
      
      return result
    },
    toProperties(obj, prefix = '') {
      const lines = []
      
      const flatten = (o, pre) => {
        for (const [key, value] of Object.entries(o)) {
          const newKey = pre ? `${pre}.${key}` : key
          
          if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
            flatten(value, newKey)
          } else if (Array.isArray(value)) {
            value.forEach((item, index) => {
              lines.push(`${newKey}[${index}]=${this.escapePropertiesValue(item)}`)
            })
          } else {
            lines.push(`${newKey}=${this.escapePropertiesValue(value)}`)
          }
        }
      }
      
      flatten(obj, prefix)
      return lines.join('\n')
    },
    toYaml(obj, indent) {
      const spaces = '  '.repeat(indent)
      let yaml = ''
      
      const sortedKeys = Object.keys(obj).sort((a, b) => {
        const aIsObj = typeof obj[a] === 'object' && obj[a] !== null && !Array.isArray(obj[a])
        const bIsObj = typeof obj[b] === 'object' && obj[b] !== null && !Array.isArray(obj[b])
        if (aIsObj && !bIsObj) return 1
        if (!aIsObj && bIsObj) return -1
        return 0
      })
      
      for (const key of sortedKeys) {
        const value = obj[key]
        
        if (Array.isArray(value)) {
          yaml += `${spaces}${key}:\n`
          value.forEach(item => {
            if (typeof item === 'object' && item !== null) {
              yaml += `${spaces}  - ${this.toYaml(item, indent + 2).trim()}\n`
            } else {
              yaml += `${spaces}  - ${item}\n`
            }
          })
        } else if (typeof value === 'object' && value !== null) {
          yaml += `${spaces}${key}:\n`
          yaml += this.toYaml(value, indent + 1)
        } else if (typeof value === 'string') {
          if (value.includes('\n') || value.includes(':') || value.includes('#')) {
            yaml += `${spaces}${key}: "${value.replace(/"/g, '\\"')}"\n`
          } else {
            yaml += `${spaces}${key}: ${value}\n`
          }
        } else if (typeof value === 'boolean') {
          yaml += `${spaces}${key}: ${value}\n`
        } else if (typeof value === 'number') {
          yaml += `${spaces}${key}: ${value}\n`
        } else {
          yaml += `${spaces}${key}: ${value}\n`
        }
      }
      
      return yaml
    },
    setNestedValue(obj, keys, value) {
      let current = obj
      for (let i = 0; i < keys.length - 1; i++) {
        const key = keys[i]
        if (!(key in current)) {
          current[key] = {}
        }
        current = current[key]
      }
      current[keys[keys.length - 1]] = value
    },
    quickConvert(from, to) {
      this.inputFormat = from
      this.outputFormat = to
      this.convert()
    },
    swapFormat() {
      const temp = this.inputFormat
      this.inputFormat = this.outputFormat
      this.outputFormat = temp
      this.inputText = this.outputText
      this.outputText = ''
    },
    onFormatChange(type) {
      if (type === 'input') {
        this.outputText = ''
      }
    },
    getPlaceholder(type) {
      if (type === 'input') {
        const placeholders = {
          properties: '# Properties 格式\nserver.port=8080\nspring.application.name=demo',
          yaml: '# YAML 格式\nserver:\n  port: 8080\nspring:\n  application:\n    name: demo',
          json: '{\n  "server": {\n    "port": 8080\n  }\n}'
        }
        return placeholders[this.inputFormat]
      }
      return ''
    },
    loadExample() {
      const examples = {
        properties: `# Server Configuration
server.port=8080
server.servlet.context-path=/api

# Database Configuration
spring.datasource.url=jdbc:mysql://localhost:3306/test
spring.datasource.username=root
spring.datasource.password=123456
spring.datasource.driver-class-name=com.mysql.cj.jdbc.Driver

# JPA Configuration
spring.jpa.hibernate.ddl-auto=update
spring.jpa.show-sql=true
spring.jpa.properties.hibernate.format_sql=true

# Application
spring.application.name=it-tools
spring.profiles.active=dev

# Logging
logging.level.root=INFO
logging.level.com.example=DEBUG`,
        yaml: `# Server Configuration
server:
  port: 8080
  servlet:
    context-path: /api

# Database Configuration
spring:
  datasource:
    url: jdbc:mysql://localhost:3306/test
    username: root
    password: "123456"
    driver-class-name: com.mysql.cj.jdbc.Driver
  jpa:
    hibernate:
      ddl-auto: update
    show-sql: true
    properties:
      hibernate:
        format_sql: true
  application:
    name: it-tools
  profiles:
    active: dev

# Logging
logging:
  level:
    root: INFO
    com.example: DEBUG`,
        json: `{
  "server": {
    "port": 8080,
    "servlet": {
      "context-path": "/api"
    }
  },
  "spring": {
    "datasource": {
      "url": "jdbc:mysql://localhost:3306/test",
      "username": "root",
      "password": "123456",
      "driver-class-name": "com.mysql.cj.jdbc.Driver"
    },
    "jpa": {
      "hibernate": {
        "ddl-auto": "update"
      },
      "show-sql": true,
      "properties": {
        "hibernate": {
          "format_sql": true
        }
      }
    },
    "application": {
      "name": "it-tools"
    },
    "profiles": {
      "active": "dev"
    }
  },
  "logging": {
    "level": {
      "root": "INFO",
      "com.example": "DEBUG"
    }
  }
}`
      }
      this.inputText = examples[this.inputFormat]
    },
    copyResult() {
      if (!this.outputText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.outputText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadResult() {
      if (!this.outputText) {
        this.$message.warning('没有可下载的内容')
        return
      }
      
      const extensions = {
        properties: 'properties',
        yaml: 'yml',
        json: 'json'
      }
      
      const blob = new Blob([this.outputText], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `config.${extensions[this.outputFormat]}`
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    clearAll() {
      this.inputText = ''
      this.outputText = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section, .output-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
    }
  }

  .quick-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;

    .el-button-group {
      margin-right: 10px;
    }
  }

  .format-info {
    h4 {
      margin: 0 0 10px 0;
      color: #409EFF;
    }

    .code-block {
      background: #f5f7fa;
      padding: 10px;
      border-radius: 4px;
      font-size: 12px;
      font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
      margin: 0;
      white-space: pre-wrap;
      word-break: break-all;
    }
  }
}
</style>
